@PluginDescriptor(
	name = "Codex Pest Control Pilot",
	description = "Tells you which Pest Control portal to work next, marks it in the world and counts your points toward the void piece you choose",
	tags = {"pest control", "void", "portal", "minigame", "points", "commendation", "codex"}
)
public class CodexPestControlPlugin extends Plugin
{
	private static final Logger log = LoggerFactory.getLogger(CodexPestControlPlugin.class);
	private static final String LOGBOOK_KEY = "logbook";
	/** Where a save this version could not keep whole is put aside, once, before it is written over. */
	private static final String BACKUP_KEY = "logbookBackup";
	/** Past this a save is far bigger than any the pilot writes, and is not copied aside. */
	private static final int BACKUP_MAX = 1_000_000;
	/** Codex Gear Roadmap keeps the bank it last saw here (item ids); read only, and only when that plugin has saved one. */
	/** The Void Knights' Outpost island. */
	private static final int OUTPOST_REGION = 10537;
	/** A spinner this close to a portal is healing it. */
	private static final int SPINNER_RANGE = 8;
	/** A brawler this close to a portal is in the way. */
	private static final int BRAWLER_RANGE = 6;
	/** A player this close to a portal is working it. */
	private static final int CROWD_RANGE = 10;

	private static final Pattern SHIELD = Pattern.compile("The ([a-z]+), [^ ]+ portal shield has dropped!", Pattern.CASE_INSENSITIVE);
	private static final Pattern COMMENDATION = Pattern.compile("([0-9,]+) (?:Void Knight )?Commendation points?", Pattern.CASE_INSENSITIVE);
	private static final Pattern NOW_HAVE = Pattern.compile("now have ([0-9,]+)", Pattern.CASE_INSENSITIVE);
	private static final Pattern NUMBER = Pattern.compile("([0-9,]+)");

	private static final int[] PORTAL_TEXT = {
		InterfaceID.PestStatusOverlay.PEST_STATUS_PORTTXT1, InterfaceID.PestStatusOverlay.PEST_STATUS_PORTTXT2,
		InterfaceID.PestStatusOverlay.PEST_STATUS_PORTTXT3, InterfaceID.PestStatusOverlay.PEST_STATUS_PORTTXT4
	};
	private static final Map<Integer, Integer> OPEN = new HashMap<>();
	private static final Map<Integer, Integer> SHIELDED = new HashMap<>();
	private static final Set<Integer> SPINNERS = new java.util.HashSet<>();
	private static final Set<Integer> BRAWLERS = new java.util.HashSet<>();
	private static final Skill[] VOID_SKILLS = {Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.HITPOINTS, Skill.RANGED, Skill.MAGIC};

	static
	{
		int[] open = {NpcID.PEST_PORTAL_1_ACTIVE, NpcID.PEST_PORTAL_2_ACTIVE, NpcID.PEST_PORTAL_3_ACTIVE, NpcID.PEST_PORTAL_4_ACTIVE};
		int[] openBt = {NpcID.PEST_PORTAL_1_ACTIVE_BT1, NpcID.PEST_PORTAL_2_ACTIVE_BT1, NpcID.PEST_PORTAL_3_ACTIVE_BT1, NpcID.PEST_PORTAL_4_ACTIVE_BT1};
		int[] shut = {NpcID.PEST_PORTAL_SHIELD_1_ACTIVE, NpcID.PEST_PORTAL_SHIELD_2_ACTIVE, NpcID.PEST_PORTAL_SHIELD_3_ACTIVE, NpcID.PEST_PORTAL_SHIELD_4_ACTIVE};
		int[] shutBt = {NpcID.PEST_PORTAL_SHIELD_1_ACTIVE_BT1, NpcID.PEST_PORTAL_SHIELD_2_ACTIVE_BT1, NpcID.PEST_PORTAL_SHIELD_3_ACTIVE_BT1, NpcID.PEST_PORTAL_SHIELD_4_ACTIVE_BT1};
		for (int i = 0; i < 4; i++)
		{
			OPEN.put(open[i], i);
			OPEN.put(openBt[i], i);
			SHIELDED.put(shut[i], i);
			SHIELDED.put(shutBt[i], i);
		}
		SPINNERS.add(NpcID.PEST_SPINNER_1);
		SPINNERS.add(NpcID.PEST_SPINNER_2);
		SPINNERS.add(NpcID.PEST_SPINNER_3);
		SPINNERS.add(NpcID.PEST_SPINNER_4);
		SPINNERS.add(NpcID.PEST_SPINNER_5);
		BRAWLERS.add(NpcID.PEST_BRAWLER_1);
		BRAWLERS.add(NpcID.PEST_BRAWLER_2);
		BRAWLERS.add(NpcID.PEST_BRAWLER_3);
		BRAWLERS.add(NpcID.PEST_BRAWLER_4);
		BRAWLERS.add(NpcID.PEST_BRAWLER_5);
	}

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ScheduledExecutorService executor;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Inject
	private Gson gson;

	@Inject
	private CodexPestControlConfig config;

	@Inject
	private PortalMarker marker;

	@Inject
	private MinimapMarker minimap;

	@Inject
	private RewardShopGuide shopGuide;

	@Inject
	private Notifier notifier;

	private final PilotPlaque plaque = new PilotPlaque();
	private final Map<Portal, NPC> portals = new EnumMap<>(Portal.class);
	private final List<NPC> spinners = new ArrayList<>();
	private final List<NPC> brawlers = new ArrayList<>();

	private PilotPanel panel;
	private NavigationButton navButton;

	private String profile;
	private Logbook logbook;
	private Set<Reward> carriedOwned = EnumSet.noneOf(Reward.class);
	/** The rewards worn now, for the void check. */
	private Set<Reward> worn = EnumSet.noneOf(Reward.class);
	/** Rewards in the bank as Codex Gear Roadmap last saved it, or null when it has saved none. Used until this plugin sees the bank. */
	private SharedBank shared;
	/** Codex Navigator's goal board as saved for this profile, or null; and what its goals need, read from it. */
	private String navBoard;
	private String navKey;
	private List<NavigatorGoals.Need> navNeeds = Collections.emptyList();
	/** The rewards in {@link #shared}, worked out once per read. */
	private Set<Reward> sharedOwned = EnumSet.noneOf(Reward.class);
	private Battle battle;
	/** A game whose status bar has gone, waiting a few ticks for its closing messages. */
	private Battle ending;
	private final GameWatch watch = new GameWatch();
	private final Alerts alerts = new Alerts();
	private final Boarding boarding = new Boarding();
	/** Ticks since the lander's overlay was last seen, capped just past the grace. */
	private int ticksSinceLander = LANDER_GRACE_TICKS + 1;
	/** A game whose bar shows within this many ticks of leaving the lander was boarded from it. */
	private static final int LANDER_GRACE_TICKS = 5;
	/**
	 * The connection dropped and the scene is being sent again: a portal that spawns open may have
	 * dropped its shield while the connection was gone, so when is not known. Until the first tick back.
	 */
	private boolean rejoining;
	private Result result = new Result();
	private Boat landerBoat;
	private boolean inLander;
	private boolean dirty;
	private boolean unsaved;
	/** Counts logbook loads, so a slow read that an account switch or shutdown overtook is dropped. */
	private int loadGeneration;

	/** What a game's closing messages said. */
	private static final class Result
	{
		boolean lost;
		boolean noZeal;
		int earned = -1;
		int total = -1;
	}

	@Provides
	CodexPestControlConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(CodexPestControlConfig.class);
	}

	@Override
	protected void startUp()
	{
		ItemIcons icons = new LoadingIcons(itemManager::getImage);
		panel = new PilotPanel(icons, new PanelActions());
		navButton = NavigationButton.builder()
			.tooltip("Codex Pest Control Pilot")
			.icon(Sigil.icon(16))
			.priority(8)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(plaque);
		overlayManager.add(marker);
		overlayManager.add(minimap);
		overlayManager.add(shopGuide);
		clientThread.invokeLater(() ->
		{
			loadProfile();
			watch.reset();
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				carriedOwned = carried();
				worn = owned(client.getItemContainer(InventoryID.WORN));
				for (NPC npc : client.getTopLevelWorldView().npcs())
				{
					track(npc);
				}
			}
			publish();
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(plaque);
		overlayManager.remove(marker);
		overlayManager.remove(minimap);
		overlayManager.remove(shopGuide);
		clientToolbar.removeNavigation(navButton);
		clientThread.invokeLater(() ->
		{
			save();
			// A logbook still being read off the client thread must not come back after this.
			loadGeneration++;
			logbook = null;
			profile = null;
			battle = null;
			ending = null;
			portals.clear();
			spinners.clear();
			brawlers.clear();
		});
		panel = null;
	}

	@Subscribe
	public void onClientShutdown(ClientShutdown event)
	{
		// ConfigManager writes its changes to disk in this same event, before a save queued on the
		// client thread runs, so a save made here has to be sent on by hand or it is never written.
		CompletableFuture<Void> done = new CompletableFuture<>();
		clientThread.invokeLater(() ->
		{
			try
			{
				if (unsaved && profile != null && logbook != null)
				{
					save();
					configManager.sendConfig();
				}
			}
			finally
			{
				done.complete(null);
			}
		});
		event.waitFor(done);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			// A dropped connection the client gets back puts you in the same game: it is held, not
			// ended, and carries on with your damage. Logging out or hopping leaves it.
			rejoining = state == GameState.CONNECTION_LOST;
			if (state != GameState.CONNECTION_LOST)
			{
				if (battle != null && logbook != null)
				{
					finish(battle, true);
				}
				else if (ending != null && logbook != null)
				{
					finish(ending, false);
				}
				battle = null;
				ending = null;
				watch.reset();
			}
			portals.clear();
			spinners.clear();
			brawlers.clear();
			inLander = false;
			save();
			publish();
		}
		else if (state == GameState.LOADING)
		{
			// A new area: every NPC the client knew is gone and the new ones spawn afresh.
			portals.clear();
			spinners.clear();
			brawlers.clear();
		}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		save();
		if (configManager.getRSProfileKey() == null)
		{
			// Logging out can leave no profile until the next login. The account's logbook stays in
			// hand, saved, so the panel still shows it and the game under way is still recorded.
			return;
		}
		loadProfile();
		carriedOwned = client.getGameState() == GameState.LOGGED_IN ? carried() : EnumSet.noneOf(Reward.class);
		publish();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (CodexPestControlConfig.GROUP.equals(event.getGroup()))
		{
			dirty = true;
		}
		else if (NavigatorGoals.GROUP.equals(event.getGroup()) && NavigatorGoals.KEY.equals(event.getKey()))
		{
			clientThread.invokeLater(() ->
			{
				if (profile != null && profile.equals(configManager.getRSProfileKey()))
				{
					readNavigator();
					dirty = true;
				}
			});
		}
		else if (SharedBank.STEWARD_GROUP.equals(event.getGroup()) && SharedBank.STEWARD_KEY.equals(event.getKey())
			|| SharedBank.ROADMAP_GROUP.equals(event.getGroup()) && SharedBank.ROADMAP_KEY.equals(event.getKey()))
		{
			// Another Codex plugin saved the bank; it only counts for the profile in hand.
			clientThread.invokeLater(() ->
			{
				if (profile != null && profile.equals(configManager.getRSProfileKey()) && logbook != null)
				{
					readShared();
					dirty = true;
				}
			});
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		track(event.getNpc());
	}

	@Subscribe
	public void onNpcChanged(NpcChanged event)
	{
		track(event.getNpc());
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		NPC npc = event.getNpc();
		spinners.remove(npc);
		brawlers.remove(npc);
		portals.values().removeIf(p -> p == npc);
	}

	private void track(NPC npc)
	{
		int id = npc.getId();
		if (SPINNERS.contains(id))
		{
			if (!spinners.contains(npc))
			{
				spinners.add(npc);
			}
			return;
		}
		if (BRAWLERS.contains(id))
		{
			if (!brawlers.contains(npc))
			{
				brawlers.add(npc);
			}
			return;
		}
		Integer open = OPEN.get(id);
		Integer shut = SHIELDED.get(id);
		if (open != null)
		{
			Portal p = Portal.values()[open];
			portals.put(p, npc);
			if (battle != null && rejoining)
			{
				battle.foundOpen(p);
			}
			else if (battle != null)
			{
				battle.shieldDropped(p);
			}
		}
		else if (shut != null)
		{
			portals.put(Portal.values()[shut], npc);
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (battle != null && event.getActor() instanceof NPC && event.getHitsplat().isMine())
		{
			Portal on = null;
			for (Map.Entry<Portal, NPC> e : portals.entrySet())
			{
				if (e.getValue() == event.getActor())
				{
					on = e.getKey();
				}
			}
			battle.addDamage(event.getHitsplat().getAmount(), on);
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE)
		{
			return;
		}
		String text = event.getMessage().replaceAll("<[^>]*>", "");
		Matcher shield = SHIELD.matcher(text);
		if (shield.lookingAt())
		{
			if (battle != null)
			{
				battle.shieldDropped(Portal.named(shield.group(1)));
				dirty = true;
			}
			return;
		}
		if (battle == null && ending == null)
		{
			return;
		}
		String lower = text.toLowerCase(Locale.ENGLISH);
		if (lower.contains("void knight was killed") || lower.contains("island is lost"))
		{
			result.lost = true;
		}
		if (lower.contains("lack of zeal"))
		{
			result.noZeal = true;
		}
		Matcher total = NOW_HAVE.matcher(text);
		if (total.find())
		{
			result.total = parse(total.group(1));
		}
		Matcher points = COMMENDATION.matcher(text);
		if (points.find() && !text.substring(0, points.start()).toLowerCase(Locale.ENGLISH).endsWith("now have "))
		{
			result.earned = parse(points.group(1));
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (logbook == null)
		{
			return;
		}
		int id = event.getContainerId();
		if (id == InventoryID.BANK)
		{
			if (logbook.seeOwned(owned(event.getItemContainer()), System.currentTimeMillis()))
			{
				unsaved = true;
			}
			dirty = true;
		}
		else if (id == InventoryID.INV || id == InventoryID.WORN)
		{
			carriedOwned = carried();
			worn = owned(client.getItemContainer(InventoryID.WORN));
			dirty = true;
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (logbook == null || client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}
		switch (watch.tick(visible(InterfaceID.PestStatusOverlay.PEST_STATUS_PORT1)))
		{
			case START:
				result = new Result();
				ending = null;
				for (NPC npc : client.getTopLevelWorldView().npcs())
				{
					track(npc);
				}
				battle = new Battle();
				// Portals that spawned before the game was seen may already be open; when is not known.
				for (Map.Entry<Portal, NPC> e : portals.entrySet())
				{
					if (OPEN.containsKey(e.getValue().getId()))
					{
						battle.foundOpen(e.getKey());
					}
				}
				Alerts.Alert begun = alerts.start(battle);
				// Only a game boarded from the lander is news, not one already on when the plugin started.
				// The lander's overlay can close a tick or two before the game's bar shows.
				battle.setWhole(ticksSinceLander <= LANDER_GRACE_TICKS);
				if (battle.isWhole())
				{
					notifier.notify(config.notifyStart(), begun.getMessage());
				}
				break;
			case RESUME:
				if (ending != null)
				{
					battle = ending;
					alerts.resume(battle);
				}
				else
				{
					battle = new Battle();
					alerts.start(battle);
				}
				ending = null;
				break;
			case SETTLE:
				ending = battle;
				battle = null;
				break;
			case FINISH:
				if (ending != null)
				{
					finish(ending, false);
				}
				ending = null;
				break;
			default:
				break;
		}
		if (battle != null && portals.isEmpty())
		{
			// Back from a dropped connection, the scene was loaded afresh: find the portals again.
			for (NPC npc : client.getTopLevelWorldView().npcs())
			{
				track(npc);
			}
		}
		// The first tick back in play: the scene has been sent again, so a portal that opens from
		// now on is seen opening.
		rejoining = false;

		if (battle != null)
		{
			battle.tick();
			for (Portal p : Portal.values())
			{
				int hp = number(PORTAL_TEXT[p.ordinal()]);
				if (hp >= 0)
				{
					battle.setHealth(p, hp);
				}
			}
			int knight = number(InterfaceID.PestStatusOverlay.PEST_STATUS_OVER_HEALTH);
			if (knight >= 0)
			{
				battle.setKnightHealth(knight);
			}
			for (Alerts.Alert a : alerts.check(battle, config.knightWarn()))
			{
				notifier.notify(a.getKind() == Alerts.Kind.SHIELD ? config.notifyShield() : config.notifyKnight(), a.getMessage());
			}
			dirty = true;
		}


		boolean lander = visible(InterfaceID.PestLanderOverlay.PEST_LANDER_OVER_POINTS);
		if (lander)
		{
			int points = number(InterfaceID.PestLanderOverlay.PEST_LANDER_OVER_POINTS);
			if (logbook.seePoints(points, System.currentTimeMillis()))
			{
				unsaved = true;
			}
			Boat boat = landerBoat();
			if (boat != null)
			{
				landerBoat = boat;
			}
			boolean quiet = boarding.isQuiet(client.getWorld());
			int ready = boarding.getReady();
			Widget readyLine = client.getWidget(InterfaceID.PestLanderOverlay.PEST_LANDER_OVER_PL);
			boarding.tick(readyLine == null ? null : readyLine.getText());
			dirty |= quiet != boarding.isQuiet(client.getWorld()) || ready != boarding.getReady();
		}
		else
		{
			boarding.leave();
		}
		ticksSinceLander = lander ? 0 : Math.min(ticksSinceLander + 1, LANDER_GRACE_TICKS + 1);
		if (lander != inLander)
		{
			inLander = lander;
			dirty = true;
		}
		if (unsaved && battle == null)
		{
			save();
		}
		if (dirty)
		{
			publish();
		}
	}

	/** Logs a finished game, updates the points and says when a piece of the goal is now affordable. */
	private void finish(Battle b, boolean left)
	{
		Result r = result;
		result = new Result();
		boolean allFallen = true;
		for (Portal p : Portal.values())
		{
			allFallen &= b.isFallen(p);
		}
		GameRecord.Result outcome;
		if (left && r.earned < 0)
		{
			outcome = GameRecord.Result.LEFT;
		}
		else if (r.lost)
		{
			outcome = GameRecord.Result.LOST;
		}
		else if (r.noZeal)
		{
			outcome = GameRecord.Result.NO_POINTS;
		}
		else if (r.earned > 0 || allFallen)
		{
			outcome = GameRecord.Result.WON;
		}
		else
		{
			outcome = GameRecord.Result.LEFT;
		}
		int earned = Math.max(0, r.earned);
		Boat boat = Boat.forPoints(earned);
		if (boat == null)
		{
			boat = landerBoat;
		}
		if (outcome == GameRecord.Result.WON && earned == 0 && boat != null)
		{
			// The points message was missed; a won game gives the lander's points.
			earned = boat.getPoints();
		}

		if (outcome != GameRecord.Result.LEFT)
		{
			logbook.getClock().learn(b.getDropTicks());
		}
		Outlook before = outlook();
		long now = System.currentTimeMillis();
		GameRecord game = new GameRecord(now, boat, outcome, earned, b.getDamage(), (int) Math.round(b.getTicks() * 0.6));
		Set<Bests.Kind> beat = logbook.record(game, b.isWhole());
		if (r.total >= 0)
		{
			logbook.seePoints(r.total, now);
		}
		else if (earned > 0 && logbook.getPoints() >= 0)
		{
			logbook.seePoints(logbook.getPoints() + earned, now);
		}
		unsaved = true;
		dirty = true;
		Outlook after = outlook();
		summarise(game, after, beat);
		announce(before, after);
	}

	/** Real levels in the order of the skills the reward shop sells experience in. */
	private int[] levels()
	{
		Experience.Skill[] skills = Experience.Skill.values();
		int[] out = new int[skills.length];
		for (int i = 0; i < skills.length; i++)
		{
			out[i] = client.getRealSkillLevel(Skill.valueOf(skills[i].name()));
		}
		return out;
	}

	/** A line in the chat box after a game; see {@link GameSummary}. */
	private void summarise(GameRecord game, Outlook after, Set<Bests.Kind> beat)
	{
		String text = config.gameSummary() ? GameSummary.of(game, after, Sitting.latest(logbook.getGames(), game.getEnded())) : null;
		String best = config.gameSummary() ? logbook.getBests().news(beat) : null;
		if (text == null && best == null)
		{
			return;
		}
		text = best == null ? text : text == null ? best + "." : text + " " + best + ".";
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT).append("Codex Pest Control Pilot: ")
				.append(ChatColorType.NORMAL).append(text)
				.build())
			.build());
	}

	/** The goal's elite pieces while the hard Western Provinces diary still locks them. */
	private Set<Reward> locked(Outlook o)
	{
		Set<Reward> locked = EnumSet.noneOf(Reward.class);
		if (client.getVarbitValue(VarbitID.WESTERN_DIARY_HARD_COMPLETE) != 1)
		{
			for (Reward r : o.getNeeded())
			{
				if (r.isElite())
				{
					locked.add(r);
				}
			}
		}
		return locked;
	}

	private void announce(Outlook before, Outlook after)
	{
		if (!config.announce() || after == null)
		{
			return;
		}
		String text = GameSummary.announcement(before, after, locked(after));
		if (text == null)
		{
			return;
		}
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.CONSOLE)
			.runeLiteFormattedMessage(new ChatMessageBuilder()
				.append(ChatColorType.HIGHLIGHT).append("Codex Pest Control Pilot: ")
				.append(ChatColorType.NORMAL).append(text)
				.build())
			.build());
	}

	private Boat landerBoat()
	{
		Widget w = client.getWidget(InterfaceID.PestLanderOverlay.PEST_LANDER_OVER_LEVEL);
		if (w == null || w.getText() == null)
		{
			return null;
		}
		String t = w.getText().toLowerCase(Locale.ENGLISH);
		if (t.contains("novice"))
		{
			return Boat.NOVICE;
		}
		if (t.contains("intermediate"))
		{
			return Boat.INTERMEDIATE;
		}
		if (t.contains("veteran"))
		{
			return Boat.VETERAN;
		}
		return null;
	}

	private boolean visible(int component)
	{
		Widget w = client.getWidget(component);
		return w != null && !w.isHidden();
	}

	/** The first number in a widget's text, or -1. */
	private int number(int component)
	{
		Widget w = client.getWidget(component);
		if (w == null || w.getText() == null)
		{
			return -1;
		}
		Matcher m = NUMBER.matcher(w.getText());
		return m.find() ? parse(m.group(1)) : -1;
	}

	private static int parse(String digits)
	{
		try
		{
			return Integer.parseInt(digits.replace(",", ""));
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	private Set<Reward> owned(ItemContainer container)
	{
		Set<Reward> out = EnumSet.noneOf(Reward.class);
		if (container == null)
		{
			return out;
		}
		for (Item item : container.getItems())
		{
			for (Reward r : Reward.values())
			{
				if (r.isOwnedBy(item.getId()))
				{
					out.add(r);
				}
			}
		}
		return out;
	}

	private Set<Reward> carried()
	{
		Set<Reward> out = owned(client.getItemContainer(InventoryID.INV));
		out.addAll(owned(client.getItemContainer(InventoryID.WORN)));
		return out;
	}

	/**
	 * The bank another Codex plugin last saved for this profile: Codex Bank Steward's full bank,
	 * else Codex Gear Roadmap's gear, else null.
	 */
	private SharedBank readSharedBank()
	{
		return SharedBank.read(gson,
			configManager.getRSProfileConfiguration(SharedBank.STEWARD_GROUP, SharedBank.STEWARD_KEY),
			configManager.getRSProfileConfiguration(SharedBank.ROADMAP_GROUP, SharedBank.ROADMAP_KEY));
	}

	/** Reads Codex Navigator's goal board for this profile; never writes it. */
	private void readNavigator()
	{
		navBoard = profile == null ? null : configManager.getRSProfileConfiguration(NavigatorGoals.GROUP, NavigatorGoals.KEY);
		navKey = null;
	}

	/** The levels Navigator's goals need in the shop's skills, read again only when the board or a level changes. */
	private List<NavigatorGoals.Need> navigatorNeeds(int[] levels)
	{
		if (levels == null)
		{
			return Collections.emptyList();
		}
		String key = Arrays.toString(levels);
		if (!key.equals(navKey))
		{
			navKey = key;
			Map<String, Integer> byName = new LinkedHashMap<>();
			for (Experience.Skill s : Experience.Skill.values())
			{
				byName.put(s.getTitle(), levels[s.ordinal()]);
			}
			navNeeds = NavigatorGoals.needs(gson, navBoard, byName);
		}
		return navNeeds;
	}

	/** Experience in the order of the skills the reward shop sells experience in. */
	private long[] experience()
	{
		Experience.Skill[] skills = Experience.Skill.values();
		long[] out = new long[skills.length];
		for (int i = 0; i < skills.length; i++)
		{
			out[i] = client.getSkillExperience(Skill.valueOf(skills[i].name()));
		}
		return out;
	}

	private void readShared()
	{
		shared = readSharedBank();
		sharedOwned = shared == null ? EnumSet.noneOf(Reward.class) : owned(shared);
	}

	/** The rewards in a shared bank. */
	private static Set<Reward> owned(SharedBank bank)
	{
		Set<Reward> out = EnumSet.noneOf(Reward.class);
		for (int id : bank.ids())
		{
			for (Reward r : Reward.values())
			{
				if (r.isOwnedBy(id))
				{
					out.add(r);
				}
			}
		}
		return out;
	}

	private void loadProfile()
	{
		profile = configManager.getRSProfileKey();
		logbook = null;
		shared = null;
		sharedOwned = EnumSet.noneOf(Reward.class);
		int generation = ++loadGeneration;
		if (profile == null)
		{
			return;
		}
		// A damaged save keeps all it can: a field or game that cannot be read is lost alone.
		String saved = configManager.getRSProfileConfiguration(CodexPestControlConfig.GROUP, LOGBOOK_KEY);
		if (saved == null || saved.length() < Logbook.LARGE)
		{
			Logbook read = Logbook.read(gson, saved);
			loaded(profile, saved, read, Salvage.wouldLose(gson, saved, read));
		}
		else
		{
			// Far bigger than any save the pilot writes (a hand-edited one): reading it takes tens of
			// milliseconds, so it is read off the client thread and taken up on it. Until then the
			// pilot shows and records nothing, as when logged out.
			String forProfile = profile;
			executor.execute(() ->
			{
				Logbook got;
				boolean loses;
				try
				{
					got = Logbook.read(gson, saved);
					loses = Salvage.wouldLose(gson, saved, got);
				}
				catch (RuntimeException e)
				{
					log.warn("Could not read the saved logbook", e);
					got = new Logbook();
					loses = true;
				}
				Logbook read = got;
				boolean lose = loses;
				clientThread.invokeLater(() ->
				{
					// Not if the account changed, or the plugin was turned off, while it was read.
					if (generation == loadGeneration && forProfile.equals(profile))
					{
						loaded(forProfile, saved, read, lose);
						dirty = true;
					}
				});
			});
		}
		readShared();
		readNavigator();
		unsaved = false;
		dirty = true;
	}

	/**
	 * Takes up the logbook read from {@code saved}, first putting {@code saved} aside when saving
	 * over it would lose something ({@code lose}): a newer version's fields, or damage mended.
	 */
	private void loaded(String forProfile, String saved, Logbook read, boolean lose)
	{
		if (lose && saved.length() <= BACKUP_MAX)
		{
			log.warn("The saved logbook holds what this version cannot keep; a copy is kept under {}", BACKUP_KEY);
			configManager.setConfiguration(CodexPestControlConfig.GROUP, forProfile, BACKUP_KEY, saved);
		}
		logbook = read;
		unsaved = false;
	}

	private void save()
	{
		if (profile == null || logbook == null || !unsaved)
		{
			return;
		}
		unsaved = false;
		configManager.setConfiguration(CodexPestControlConfig.GROUP, profile, LOGBOOK_KEY, gson.toJson(logbook));
	}

	private Set<Reward> owned()
	{
		Set<Reward> owned = logbook.getOwned();
		if (fromSharedBank())
		{
			owned.addAll(sharedOwned);
		}
		owned.addAll(carriedOwned);
		return owned;
	}

	/** Whether the owned pieces come from another Codex plugin's saved bank, this plugin not having seen the bank yet. */
	private boolean fromSharedBank()
	{
		return logbook.getOwnedSeen() == 0 && shared != null;
	}

	private Boat estimateBoat()
	{
		switch (config.lander())
		{
			case NOVICE:
				return Boat.NOVICE;
			case INTERMEDIATE:
				return Boat.INTERMEDIATE;
			case VETERAN:
				return Boat.VETERAN;
			default:
				List<GameRecord> games = logbook.getGames();
				for (int i = games.size() - 1; i >= 0; i--)
				{
					if (games.get(i).getBoat() != null)
					{
						return games.get(i).getBoat();
					}
				}
				Player me = client.getLocalPlayer();
				return me == null ? Boat.NOVICE : Boat.forCombat(me.getCombatLevel());
		}
	}

	private Outlook outlook()
	{
		if (logbook == null)
		{
			return null;
		}
		return Outlook.of(logbook.getGoal(), owned(), logbook.getPoints(), logbook.pointsPerGame(estimateBoat()),
			logbook.minutesPerGame(), logbook.isMeasured());
	}

	/** Works out the advice and hands the panel, the plaque and the markers what they show. */
	private void publish()
	{
		dirty = false;
		PilotPanel target = panel;
		long now = System.currentTimeMillis();
		boolean loggedIn = client.getGameState() == GameState.LOGGED_IN;
		if (logbook == null || !loggedIn)
		{
			plaque.show(null);
			marker.show(null);
			shopGuide.show(null);
			if (target != null)
			{
				View view = logbook == null ? View.loggedOut() : view(View.State.LOGGED_OUT, null, now);
				SwingUtilities.invokeLater(() -> target.update(view));
			}
			return;
		}

		Player me = client.getLocalPlayer();
		View.Fight fight = null;
		Advice advice = null;
		if (battle != null)
		{
			Field field = field(me);
			advice = battle.advise(field);
			List<View.PortalState> states = new ArrayList<>();
			for (Portal p : Portal.values())
			{
				Integer crowd = field.crowdAt(p);
				states.add(new View.PortalState(p, battle.isShielded(p), battle.isFallen(p), battle.getHealth(p), crowd == null ? -1 : crowd,
					battle.secondsToFall(p), battle.isYoursAlone(p)));
			}
			fight = new View.Fight(states, advice, battle.getKnightHealth(), battle.getDamage(), battle.expectedOrder(),
				battle.getPossible().size(), (int) Math.round(battle.getTicks() * 0.6), activity(), battle.secondsToNextDrop(logbook.getClock()));
		}

		boolean outpost = me != null && me.getWorldLocation().getRegionID() == OUTPOST_REGION;
		View.State state = battle != null ? View.State.BATTLE : inLander ? View.State.LANDER : outpost ? View.State.OUTPOST : View.State.AWAY;
		View view = view(state, fight, now);
		Outlook outlook = outlook();
		showPlaque(state, advice, battle, outlook, Goal.matching(logbook.getGoal()), view.voidCheck);
		showMarker(advice);
		showShop(outlook);
		if (target != null)
		{
			SwingUtilities.invokeLater(() -> target.update(view));
		}
	}

	/** What can be seen around the island now: distances, pests and players at each portal, and your style. */
	private Field field(Player me)
	{
		Field field = new Field()
			.knightWarn(config.knightWarn())
			.activity(activity())
			.nextDrop(battle.secondsToNextDrop(logbook.getClock()))
			.style(style());
		WorldPoint here = me == null ? null : me.getWorldLocation();
		for (Map.Entry<Portal, NPC> e : portals.entrySet())
		{
			Portal p = e.getKey();
			WorldPoint at = e.getValue().getWorldLocation();
			if (here != null)
			{
				field.distance(p, here.distanceTo(at));
			}
			field.spinners(p, near(spinners, at, SPINNER_RANGE));
			field.brawlers(p, near(brawlers, at, BRAWLER_RANGE));
			int crowd = 0;
			for (Player other : client.getTopLevelWorldView().players())
			{
				if (other != me && other.getWorldLocation().distanceTo(at) <= CROWD_RANGE)
				{
					crowd++;
				}
			}
			field.crowd(p, crowd);
		}
		return field;
	}

	private static int near(List<NPC> npcs, WorldPoint at, int range)
	{
		int n = 0;
		for (NPC npc : npcs)
		{
			if (npc.getWorldLocation().distanceTo(at) <= range)
			{
				n++;
			}
		}
		return n;
	}

	/** Your style from the weapon you hold. */
	private Style style()
	{
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		Item weapon = worn == null ? null : worn.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (weapon == null || weapon.getId() <= 0)
		{
			return Style.MELEE;
		}
		return Style.ofWeapon(itemManager.getItemComposition(weapon.getId()).getName());
	}

	/** The game's activity bar as a percentage, or -1 when it cannot be read. */
	private int activity()
	{
		Widget container = client.getWidget(InterfaceID.PestStatusOverlay.ACTIVITY_CONTAINER);
		Widget bar = client.getWidget(InterfaceID.PestStatusOverlay.ACTIVITY_BAR);
		Widget track = container == null ? null : container.getChild(0);
		Widget fill = bar == null ? null : bar.getChild(0);
		if (track == null || fill == null || track.getWidth() <= 0)
		{
			return -1;
		}
		return (int) Math.max(0, Math.min(100, Math.round(100.0 * fill.getWidth() / track.getWidth())));
	}

	private View view(View.State state, View.Fight fight, long now)
	{
		Outlook outlook = outlook();
		Set<Reward> goal = logbook.getGoal();
		List<String> missing = new ArrayList<>();
		boolean elite = false;
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			for (Skill s : VOID_SKILLS)
			{
				if (client.getRealSkillLevel(s) < 42)
				{
					missing.add("42 " + s.getName());
				}
			}
			if (client.getRealSkillLevel(Skill.PRAYER) < 22)
			{
				missing.add("22 Prayer");
			}
			elite = client.getVarbitValue(VarbitID.WESTERN_DIARY_HARD_COMPLETE) == 1;
		}
		List<GameRecord> games = new ArrayList<>(logbook.getGames());
		GameRecord last = games.isEmpty() ? null : games.get(games.size() - 1);
		Player me = client.getLocalPlayer();
		View view = new View(state, me == null ? null : me.getName(), fight, last, outlook, goal, owned(), Goal.matching(goal),
			estimateBoat(), logbook.getOwnedSeen() > 0 || fromSharedBank(), missing, elite, logbook.getPlayed(), logbook.getWon(), logbook.getEarned(),
			logbook.getSeconds(), games, now);
		view.ownedFrom = fromSharedBank() ? shared.getSource() : null;
		view.landers = Landers.of(games);
		view.combat = me == null ? 0 : me.getCombatLevel();
		view.sitting = Sitting.latest(games, now);
		view.levels = me == null ? null : levels();
		view.xp = me == null ? null : experience();
		view.goals = navigatorNeeds(view.levels);
		view.voidCheck = battle == null && me != null ? VoidCheck.of(worn, style(), owned()) : null;
		view.nameOnCard = config.nameOnCard();
		view.bests = logbook.getBests().copy();
		view.knightWarn = config.knightWarn();
		view.ready = state == View.State.LANDER ? boarding.getReady() : -1;
		view.landerTip = state == View.State.LANDER && boarding.isQuiet(client.getWorld()) ? boarding.tip() : null;
		return view;
	}

	/**
	 * The plaque's line on the goal once the points are read. Points that cover elite pieces the
	 * hard diary still locks do not send the player to the shop for all of it, as the panel's
	 * crest and the void card say too.
	 */
	static String goalDetail(Outlook o, boolean elite)
	{
		if (o.isComplete())
		{
			return "Every piece is yours";
		}
		if (o.isAffordable())
		{
			boolean locked = false;
			for (Reward r : o.getNeeded())
			{
				locked |= r.isElite() && !elite;
			}
			return locked ? "Points enough; the diary is due" : "Enough for all of it: visit the reward shop";
		}
		String left = Format.number(o.getRemaining()) + " to go, about " + Format.plural(o.getGames(), "game", "games");
		Set<Reward> locked = EnumSet.noneOf(Reward.class);
		for (Reward r : o.getNeeded())
		{
			if (r.isElite() && !elite)
			{
				locked.add(r);
			}
		}
		Set<Reward> buyable = o.buyableNow(locked);
		// Part of the goal is already yours to buy: worth a trip to the shop before the next game.
		return buyable.size() == 1 ? "buy the " + buyable.iterator().next().getShortTitle().toLowerCase(Locale.ENGLISH) + " now; " + left
			: buyable.size() > 1 ? "buy " + buyable.size() + " pieces now; " + left : left;
	}

	private void showPlaque(View.State state, Advice advice, Battle b, Outlook o, Goal preset, VoidCheck voidCheck)
	{
		CodexPestControlConfig.PlaqueMode mode = config.plaque();
		if (mode == CodexPestControlConfig.PlaqueMode.NEVER || state == View.State.AWAY
			|| state != View.State.BATTLE && mode != CodexPestControlConfig.PlaqueMode.AT_THE_OUTPOST)
		{
			plaque.show(null);
			return;
		}
		if (advice != null)
		{
			Color colour = advice.getPortal() != null ? Theme.portal(advice.getPortal())
				: advice.getKind() == Advice.Kind.GUARD ? Theme.BLOOD : Theme.GOLD;
			String kicker = advice.getKind() == Advice.Kind.ATTACK ? "WORK NEXT" : advice.getKind() == Advice.Kind.NEXT ? "GET AHEAD"
				: advice.getKind() == Advice.Kind.GUARD ? "KNIGHT IN DANGER" : advice.getKind() == Advice.Kind.DONE ? "VICTORY" : "WAIT";
			String foot;
			Color footColor;
			if (b.hasPoints())
			{
				foot = b.getDamage() + " damage: points earned";
				footColor = Theme.GREEN;
			}
			else
			{
				foot = b.getDamage() + " of " + Battle.DAMAGE_FOR_POINTS + " damage for points";
				footColor = Theme.EMBER;
			}
			plaque.show(new PilotPlaque.Shown(kicker, advice.getHeadline(), colour, advice.getDetail(), foot, footColor));
			return;
		}
		if (voidCheck != null && voidCheck.isWarning() && config.voidCheck())
		{
			// Still time to fix it before the game: that matters more than the points tally.
			plaque.show(new PilotPlaque.Shown("VOID CHECK", voidCheck.getHeadline(), Theme.EMBER, voidCheck.getDetail(), null, null));
			return;
		}
		if (state == View.State.LANDER && boarding.isQuiet(client.getWorld()))
		{
			plaque.show(new PilotPlaque.Shown("QUIET LANDER", "Try world " + Boarding.PEST_CONTROL_WORLD, Theme.GOLD_BRIGHT, boarding.tip(), null, null));
			return;
		}
		String goal = preset != null ? preset.getTitle() : "Your goal";
		if (o == null || !o.isPointsKnown())
		{
			plaque.show(new PilotPlaque.Shown("PEST CONTROL", goal, Theme.GOLD, "Board a lander to read your points", null, null));
			return;
		}
		String detail = goalDetail(o, client.getVarbitValue(VarbitID.WESTERN_DIARY_HARD_COMPLETE) == 1);
		plaque.show(new PilotPlaque.Shown("PEST CONTROL", Format.number(o.getPoints()) + " points", Theme.GOLD_BRIGHT,
			goal + ": " + detail, null, null));
	}

	private void showShop(Outlook o)
	{
		if (!config.markShop() || o == null || !o.isPointsKnown() || o.isComplete())
		{
			shopGuide.show(null);
			return;
		}
		Set<Reward> locked = locked(o);
		Set<Reward> goal = EnumSet.noneOf(Reward.class);
		goal.addAll(o.getNeeded());
		goal.removeAll(locked);
		shopGuide.show(new RewardShopGuide.Guide(o.buyableNow(locked), goal));
	}

	private void showMarker(Advice advice)
	{
		if (advice == null || !config.markPortal())
		{
			marker.show(null);
			return;
		}
		NPC target = advice.getPortal() == null ? null : portals.get(advice.getPortal());
		List<NPC> maybe = new ArrayList<>();
		List<Color> colours = new ArrayList<>();
		if (advice.getKind() == Advice.Kind.WAIT && config.markCandidates())
		{
			for (Portal p : advice.getCandidates())
			{
				NPC npc = portals.get(p);
				if (npc != null)
				{
					maybe.add(npc);
					colours.add(Theme.portal(p));
				}
			}
		}
		if (target == null && maybe.isEmpty())
		{
			marker.show(null);
			return;
		}
		String label = advice.getKind() == Advice.Kind.ATTACK ? "Attack" : "Next";
		marker.show(new PortalMarker.Mark(target, target == null ? Theme.GOLD : Theme.portal(advice.getPortal()), label, maybe, colours));
	}

	/** The panel's buttons; each change is made on the client thread, where the logbook lives. */
	private final class PanelActions implements Actions
	{
		@Override
		public void preset(Goal goal)
		{
			clientThread.invokeLater(() ->
			{
				if (logbook != null)
				{
					logbook.setGoal(EnumSet.copyOf(goal.getRewards()));
					unsaved = true;
					save();
					publish();
				}
			});
		}

		@Override
		public void toggle(Reward reward)
		{
			clientThread.invokeLater(() ->
			{
				if (logbook != null)
				{
					logbook.toggle(reward);
					unsaved = true;
					save();
					publish();
				}
			});
		}
	}
}

package com.codex.pestcontrol.core;

import java.util.Collections;
import java.util.List;

/** What the Pilot says to do right now in a game. */
public final class Advice
{
	public enum Kind
	{
		/** A portal's shield is down: go and attack it. */
		ATTACK,
		/** No shield is down yet, but the next one to drop is known: make for it. */
		NEXT,
		/** No shield is down and the next could be one of several: hold by the knight. */
		WAIT,
		/** The Void Knight is in danger: defend him. */
		GUARD,
		/** Every portal has fallen. */
		DONE
	}

	private final Kind kind;
	private final Portal portal;
	private final List<Portal> candidates;
	private final String headline;
	private final String detail;

	public Advice(Kind kind, Portal portal, List<Portal> candidates, String headline, String detail)
	{
		this.kind = kind;
		this.portal = portal;
		this.candidates = candidates == null ? Collections.emptyList() : Collections.unmodifiableList(candidates);
		this.headline = headline;
		this.detail = detail;
	}

	public Kind getKind()
	{
		return kind;
	}

	/** The portal to work, or null when the advice is not about one portal. */
	public Portal getPortal()
	{
		return portal;
	}

	/** Every portal the advice could be about, such as the ones whose shield might drop next. */
	public List<Portal> getCandidates()
	{
		return candidates;
	}

	public String getHeadline()
	{
		return headline;
	}

	public String getDetail()
	{
		return detail;
	}

	@Override
	public String toString()
	{
		return kind + " " + portal + ": " + headline + " (" + detail + ")";
	}
}

package com.codex.pestcontrol.core;

import java.util.ArrayList;
import java.util.List;

/**
 * Decides when a game is worth a desktop notification: when it begins, when a shield is seen
 * dropping, and when the Void Knight first falls low. Each fires once, so a repeated message or a
 * portal seen twice never notifies twice.
 */
public final class Alerts
{
	/** What a notification is about, so each can be switched on or off on its own. */
	public enum Kind
	{
		START,
		SHIELD,
		KNIGHT
	}

	/** One notification to send. */
	public static final class Alert
	{
		private final Kind kind;
		private final String message;

		Alert(Kind kind, String message)
		{
			this.kind = kind;
			this.message = message;
		}

		public Kind getKind()
		{
			return kind;
		}

		public String getMessage()
		{
			return message;
		}

		@Override
		public String toString()
		{
			return kind + ": " + message;
		}
	}

	private int dropsSeen;
	private boolean knightWarned;

	/** A new game began. Portals already open when it was first seen are not news. */
	public Alert start(Battle battle)
	{
		dropsSeen = battle.getDrops().size();
		knightWarned = false;
		return new Alert(Kind.START, "Pest Control: the game has begun");
	}

	/** Carrying on with a game after a dropped connection: nothing seen before it is news again. */
	public void resume(Battle battle)
	{
		dropsSeen = battle.getDrops().size();
	}

	/**
	 * What changed since the last look.
	 *
	 * @param knightWarn the knight's health at which defending him comes first; 0 never warns
	 */
	public List<Alert> check(Battle battle, int knightWarn)
	{
		List<Alert> out = new ArrayList<>();
		List<Portal> drops = battle.getDrops();
		List<Integer> ticks = battle.getDropTicks();
		for (int i = dropsSeen; i < drops.size(); i++)
		{
			// A shield found already down, or a portal seen falling with its drop missed, happened unseen.
			if (ticks.get(i) >= 0)
			{
				out.add(new Alert(Kind.SHIELD, shield(battle, drops.get(i))));
			}
		}
		dropsSeen = drops.size();
		int knight = battle.getKnightHealth();
		if (!knightWarned && knightWarn > 0 && knight > 0 && knight <= knightWarn)
		{
			knightWarned = true;
			out.add(new Alert(Kind.KNIGHT, "Pest Control: the Void Knight is down to " + knight + " health"));
		}
		return out;
	}

	static String shield(Battle battle, Portal p)
	{
		String text = "Pest Control: the " + p.getTitle().toLowerCase(java.util.Locale.ENGLISH) + " shield is down (" + p.getGate() + ")";
		List<Portal> next = battle.nextShields();
		if (next.size() == 1 && !battle.isFallen(next.get(0)))
		{
			text += "; " + next.get(0).getTitle().toLowerCase(java.util.Locale.ENGLISH) + " is next";
		}
		return text;
	}
}

package com.codex.pestcontrol.core;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * One Pest Control game as the Pilot follows it: which shields are down, which portals have
 * fallen, the rotations still possible, the knight's health and the damage you have dealt.
 * It works out what to do next; the plugin only feeds it what the game shows.
 */
public class Battle
{
	/** Damage a player has to deal in a game to be given points for it. */
	public static final int DAMAGE_FOR_POINTS = 50;
	/** A portal this many tiles nearer than the weakest open one is worth going to first. */
	private static final int NEARER_BY = 15;
	/** Until you have your points, an open portal with this many fewer players is worth going to. */
	private static final int QUIETER_BY = 6;
	/** Below this activity, waiting time is better spent on a barricade. */
	private static final int LOW_ACTIVITY = 30;
	/** The team's pace at a portal is measured over this many ticks, about ten seconds. */
	static final int PACE_WINDOW = 17;
	/** Ticks of readings needed before a pace is trusted. */
	static final int PACE_MIN = 6;
	/** A portal falling this many seconds later than the weakest holds the game up enough to go there instead. */
	private static final int LATER_BY = 12;
	/** Seconds shown for a portal the team is not wearing down at all. */
	public static final int STALLED = Integer.MAX_VALUE;

	private final boolean[] shielded = {true, true, true, true};
	private final boolean[] fallen = new boolean[4];
	private final int[] health = {-1, -1, -1, -1};
	private final List<Portal> drops = new ArrayList<>();
	private final List<Integer> dropTicks = new ArrayList<>();
	private List<Rotation> possible = new ArrayList<>(Arrays.asList(Rotation.values()));
	private int knightHealth = -1;
	private int damage;
	private int ticks;
	/** Each portal's health readings over the pace window: {tick, health}, oldest first. */
	private final List<List<int[]>> readings = new ArrayList<>();
	/** Your own hits on each portal over the pace window: {tick, damage}. */
	private final List<List<int[]>> ownHits = new ArrayList<>();
	/** The portal last sent to once points were earned, held unless another clearly holds the game up more. */
	private Portal holding;

	/** Whether the game was boarded from the lander, so seen from its start. */
	private boolean whole;

	public boolean isWhole()
	{
		return whole;
	}

	public void setWhole(boolean whole)
	{
		this.whole = whole;
	}

	public Battle()
	{
		for (int i = 0; i < 4; i++)
		{
			readings.add(new ArrayList<>());
			ownHits.add(new ArrayList<>());
		}
	}

	/** A portal's shield has dropped just now, by its message or by the portal changing. Repeats are ignored. */
	public void shieldDropped(Portal portal)
	{
		drop(portal, ticks);
	}

	/** A portal found already open, so the moment its shield dropped is not known. */
	public void foundOpen(Portal portal)
	{
		drop(portal, -1);
	}

	private void drop(Portal portal, int at)
	{
		if (portal == null || !shielded[portal.ordinal()])
		{
			return;
		}
		shielded[portal.ordinal()] = false;
		// Readings from behind the shield would make a portal the team has only just reached look stalled.
		readings.get(portal.ordinal()).clear();
		ownHits.get(portal.ordinal()).clear();
		int step = drops.size();
		drops.add(portal);
		dropTicks.add(at);
		List<Rotation> left = new ArrayList<>();
		for (Rotation r : possible)
		{
			if (r.at(step) == portal)
			{
				left.add(r);
			}
		}
		// A drop no rotation explains means a missed message; keep reading ahead from what is known.
		if (!left.isEmpty())
		{
			possible = left;
		}
	}

	/** The portal's health as the status widget shows it; zero means it has fallen. */
	public void setHealth(Portal portal, int hp)
	{
		health[portal.ordinal()] = hp;
		List<int[]> r = readings.get(portal.ordinal());
		if (!r.isEmpty() && r.get(r.size() - 1)[0] == ticks)
		{
			r.get(r.size() - 1)[1] = hp;
		}
		else
		{
			r.add(new int[]{ticks, hp});
		}
		trim(r);
		if (hp == 0)
		{
			fall(portal);
		}
	}

	public void fall(Portal portal)
	{
		fallen[portal.ordinal()] = true;
		// A portal can only be killed with its shield down; when its drop was missed, its moment is unknown.
		foundOpen(portal);
	}

	public void setKnightHealth(int hp)
	{
		knightHealth = hp;
	}

	public void addDamage(int amount)
	{
		addDamage(amount, null);
	}

	/** One of your hitsplats; on a portal it is kept apart so the team's own pace there can be told from yours. */
	public void addDamage(int amount, Portal on)
	{
		if (amount <= 0)
		{
			return;
		}
		damage += amount;
		if (on != null)
		{
			List<int[]> hits = ownHits.get(on.ordinal());
			hits.add(new int[]{ticks, amount});
			trim(hits);
		}
	}

	private void trim(List<int[]> samples)
	{
		while (!samples.isEmpty() && samples.get(0)[0] < ticks - PACE_WINDOW)
		{
			samples.remove(0);
		}
	}

	/**
	 * Seconds until the open portal falls at the pace the rest of the team is wearing it down,
	 * leaving your own hits out; {@link #STALLED} when they are not wearing it down at all, or
	 * -1 when it is not open or has not been watched long enough to tell.
	 */
	public int secondsToFall(Portal portal)
	{
		int i = portal.ordinal();
		if (shielded[i] || fallen[i])
		{
			return -1;
		}
		List<int[]> r = readings.get(i);
		trim(r);
		if (r.size() < 2)
		{
			return -1;
		}
		int[] first = r.get(0);
		int[] last = r.get(r.size() - 1);
		int span = last[0] - first[0];
		if (span < PACE_MIN || last[1] <= 0)
		{
			return -1;
		}
		// A hit stamped with a tick lands after that tick's reading, so it shows from the next one on.
		int mine = 0;
		for (int[] hit : ownHits.get(i))
		{
			if (hit[0] >= first[0] && hit[0] < last[0])
			{
				mine += hit[1];
			}
		}
		double perTick = (first[1] - last[1] - mine) / (double) span;
		if (perTick <= 0.05)
		{
			return STALLED;
		}
		return (int) Math.ceil(last[1] / perTick * 0.6);
	}

	/**
	 * Whether you are the only one wearing the open portal down: your hits have landed on it lately
	 * but, leaving them out, its health is not falling. Its pace then reads as stalled, which is the
	 * team's pace, not yours.
	 */
	public boolean isYoursAlone(Portal portal)
	{
		List<int[]> hits = ownHits.get(portal.ordinal());
		trim(hits);
		return !hits.isEmpty() && secondsToFall(portal) == STALLED;
	}

	public void tick()
	{
		ticks++;
	}

	public boolean isShielded(Portal portal)
	{
		return shielded[portal.ordinal()];
	}

	public boolean isFallen(Portal portal)
	{
		return fallen[portal.ordinal()];
	}

	/** The portal's health, or -1 before the status widget has been read. */
	public int getHealth(Portal portal)
	{
		return health[portal.ordinal()];
	}

	public int getKnightHealth()
	{
		return knightHealth;
	}

	public int getDamage()
	{
		return damage;
	}

	public int getTicks()
	{
		return ticks;
	}

	public List<Portal> getDrops()
	{
		return Collections.unmodifiableList(drops);
	}

	/** The tick each shield dropped on, in drop order, -1 where it was not seen. */
	public List<Integer> getDropTicks()
	{
		return Collections.unmodifiableList(dropTicks);
	}

	/** Seconds until the next shield is due by the clock learned so far, or -1 when not known. */
	public int secondsToNextDrop(ShieldClock clock)
	{
		int step = drops.size();
		if (step >= 4 || clock == null)
		{
			return -1;
		}
		int gap = clock.expected(step);
		if (gap < 0)
		{
			return -1;
		}
		int since;
		if (step == 0)
		{
			since = ticks;
		}
		else
		{
			int last = dropTicks.get(step - 1);
			if (last < 0)
			{
				return -1;
			}
			since = ticks - last;
		}
		return (int) Math.max(0, Math.round((gap - since) * 0.6));
	}

	public List<Rotation> getPossible()
	{
		return Collections.unmodifiableList(possible);
	}

	/** The order of the game once it is known, else null. */
	public Rotation getRotation()
	{
		return possible.size() == 1 ? possible.get(0) : null;
	}

	/** Portals whose shield could drop next, standing ones only. */
	public List<Portal> nextShields()
	{
		List<Portal> next = new ArrayList<>();
		for (Rotation r : possible)
		{
			for (int step = drops.size(); step < 4; step++)
			{
				Portal p = r.at(step);
				if (p != null && shielded[p.ordinal()])
				{
					if (!next.contains(p))
					{
						next.add(p);
					}
					break;
				}
			}
		}
		return next;
	}

	/** The portals in the order their shields drop, as far as it is known: dropped ones first. */
	public List<Portal> expectedOrder()
	{
		List<Portal> order = new ArrayList<>(drops);
		Rotation r = getRotation();
		if (r != null)
		{
			for (Portal p : r.order())
			{
				if (!order.contains(p))
				{
					order.add(p);
				}
			}
		}
		return order;
	}

	public boolean hasPoints()
	{
		return damage >= DAMAGE_FOR_POINTS;
	}

	/** What to do now, from the status bar and what can be seen around the island. */
	public Advice advise(Field field)
	{
		Field f = field == null ? new Field() : field;
		boolean knightLow = knightHealth >= 0 && f.knightWarn > 0 && knightHealth <= f.knightWarn;

		List<Portal> open = new ArrayList<>();
		List<Portal> standing = new ArrayList<>();
		for (Portal p : Portal.values())
		{
			if (!fallen[p.ordinal()])
			{
				standing.add(p);
				if (!shielded[p.ordinal()])
				{
					open.add(p);
				}
			}
		}
		if (standing.isEmpty())
		{
			return new Advice(Advice.Kind.DONE, null, null, "Every portal has fallen", "The game ends as the last pests fall");
		}

		if (!open.isEmpty())
		{
			Portal weakest = weakest(open);
			Portal target = pick(open, weakest, f);
			boolean quieter = target != weakest && quieter(target, weakest, f);
			Portal slowest = hasPoints() ? holdingUp(open, target) : null;
			holding = slowest;
			if (slowest != null)
			{
				target = slowest;
				quieter = false;
			}
			String detail = slowest != null ? slowestDetail(slowest, f) : attackDetail(target, quieter, f);
			if (knightLow)
			{
				detail = "Knight at " + knightHealth + " health. " + detail;
			}
			return new Advice(Advice.Kind.ATTACK, target, open, "Attack " + target.getTitle() + " (" + target.getSide() + ")", detail);
		}

		if (knightLow)
		{
			return new Advice(Advice.Kind.GUARD, null, null, "Defend the Void Knight",
				"He is at " + knightHealth + " health and no shield is down: clear the pests around him");
		}

		String when = f.nextDrop < 0 ? "next" : f.nextDrop <= 3 ? "any moment" : "in about " + f.nextDrop + "s";
		boolean idle = f.activity >= 0 && f.activity < LOW_ACTIVITY;
		List<Portal> next = nextShields();
		if (next.size() == 1)
		{
			Portal p = next.get(0);
			String detail = "Its shield drops " + when + ": leave by the " + p.getGate();
			if (f.style.isDistant())
			{
				detail += ". Hang back and hit it from range";
			}
			return new Advice(Advice.Kind.NEXT, p, next, "Head to " + p.getTitle() + " (" + p.getSide() + ")", detail);
		}
		if (next.isEmpty())
		{
			next = standing;
		}
		String detail = list(next) + " drops " + when;
		if (idle)
		{
			detail += ". Repair a barricade meanwhile to raise your activity";
		}
		return new Advice(Advice.Kind.WAIT, null, next, "Hold by the knight", detail);
	}

	/**
	 * Once your points are earned the game ends when the last portal falls, so the open portal
	 * the team is wearing down slowest is where your hits shorten it most. Returns it when it falls
	 * clearly later than the portal otherwise picked, else null. The last pick is held while it is
	 * still close to the slowest, so the advice does not flicker between two portals.
	 */
	private Portal holdingUp(List<Portal> open, Portal picked)
	{
		if (open.size() < 2)
		{
			return null;
		}
		Portal slowest = null;
		int slowestEta = -1;
		for (Portal p : open)
		{
			int eta = secondsToFall(p);
			if (eta < 0)
			{
				// Not every open portal is measured yet: no fair comparison.
				return null;
			}
			if (eta > slowestEta || eta == slowestEta && rank(health[p.ordinal()]) > rank(health[slowest.ordinal()]))
			{
				slowest = p;
				slowestEta = eta;
			}
		}
		if (holding != null && open.contains(holding) && holding != slowest)
		{
			int held = secondsToFall(holding);
			if (held == STALLED || slowestEta != STALLED && slowestEta - held < LATER_BY)
			{
				return holding;
			}
		}
		if (slowest == picked)
		{
			return slowestEta == STALLED || slowestEta >= LATER_BY ? slowest : null;
		}
		int pickedEta = secondsToFall(picked);
		boolean later = slowestEta == STALLED ? pickedEta != STALLED : slowestEta - pickedEta >= LATER_BY && slowestEta >= pickedEta * 3 / 2;
		return later ? slowest : null;
	}

	private String slowestDetail(Portal p, Field f)
	{
		int spinning = f.spinners.getOrDefault(p, 0);
		String lead;
		int eta = secondsToFall(p);
		if (eta == STALLED)
		{
			Integer crowd = f.crowdAt(p);
			if (isYoursAlone(p))
			{
				lead = "Only you are wearing it down: it holds the game up";
			}
			else
			{
				lead = crowd != null && crowd == 0 ? "Nobody is there: it holds the game up" : "The team is not wearing it down: it holds the game up";
			}
		}
		else
		{
			lead = "Falls last at the team's pace, in about " + eta + "s";
		}
		if (spinning > 0)
		{
			return lead + ". Kill the " + (spinning == 1 ? "spinner" : spinning + " spinners") + " healing it first";
		}
		return lead + ". Your points are earned, so your hits end the game sooner here";
	}

	/** What to say about the portal to attack: what stands in the way first, then why this one. */
	private String attackDetail(Portal target, boolean quieter, Field f)
	{
		int spinning = f.spinners.getOrDefault(target, 0);
		if (spinning > 0)
		{
			if (f.style.isDistant())
			{
				return spinning == 1 ? "A spinner is healing it: shoot it from range, then the portal"
					: spinning + " spinners are healing it: shoot them from range, then the portal";
			}
			return spinning == 1 ? "A spinner is healing it: kill it first" : spinning + " spinners are healing it: kill them first";
		}
		int brawling = f.brawlers.getOrDefault(target, 0);
		if (brawling > 0 && !f.style.isDistant())
		{
			return brawling == 1 ? "A brawler blocks the way: clear it first" : brawling + " brawlers block the way: clear them first";
		}
		Integer crowd = f.crowdAt(target);
		if (quieter && crowd != null)
		{
			return crowd == 0 ? "Nobody is there yet: easy damage for your points" : "Only " + players(crowd) + " there: easier damage for your points";
		}
		StringBuilder sb = new StringBuilder("Shield down");
		if (health[target.ordinal()] > 0)
		{
			sb.append(", ").append(health[target.ordinal()]).append(" health left");
		}
		else
		{
			sb.append(": leave by the ").append(target.getGate());
		}
		if (crowd != null && crowd > 0)
		{
			sb.append(", ").append(players(crowd));
		}
		return sb.toString();
	}

	private Portal weakest(List<Portal> open)
	{
		Portal weakest = open.get(0);
		for (Portal p : open)
		{
			if (rank(health[p.ordinal()]) < rank(health[weakest.ordinal()]))
			{
				weakest = p;
			}
		}
		return weakest;
	}

	/**
	 * The weakest open portal, unless you still need damage for points and another has far
	 * fewer players to share it with, or another is a good deal nearer.
	 */
	private Portal pick(List<Portal> open, Portal weakest, Field f)
	{
		if (!hasPoints())
		{
			Portal quietest = weakest;
			for (Portal p : open)
			{
				Integer c = f.crowd.get(p);
				Integer best = f.crowd.get(quietest);
				if (c != null && best != null && c < best)
				{
					quietest = p;
				}
			}
			if (quietest != weakest && quieter(quietest, weakest, f))
			{
				return quietest;
			}
		}
		Portal nearest = weakest;
		for (Portal p : open)
		{
			Integer d = f.distance.get(p);
			Integer best = f.distance.get(nearest);
			if (d != null && (best == null || d < best))
			{
				nearest = p;
			}
		}
		Integer dw = f.distance.get(weakest);
		Integer dn = f.distance.get(nearest);
		if (nearest != weakest && dn != null && (dw == null || dw - dn >= NEARER_BY))
		{
			return nearest;
		}
		return weakest;
	}

	private static boolean quieter(Portal a, Portal than, Field f)
	{
		Integer ca = f.crowd.get(a);
		Integer cb = f.crowd.get(than);
		return ca != null && cb != null && cb - ca >= QUIETER_BY;
	}

	/** "1 player", "12 players". */
	static String players(int n)
	{
		return n + (n == 1 ? " player" : " players");
	}

	private static int rank(int hp)
	{
		return hp < 0 ? Integer.MAX_VALUE : hp;
	}

	/** "Purple", "Purple or Blue", "Purple, Blue or Yellow". */
	static String list(List<Portal> portals)
	{
		StringBuilder sb = new StringBuilder();
		for (int i = 0; i < portals.size(); i++)
		{
			if (i > 0)
			{
				sb.append(i == portals.size() - 1 ? " or " : ", ");
			}
			sb.append(portals.get(i).getTitle());
		}
		return sb.toString();
	}
}

package com.codex.pestcontrol.core;

import java.util.EnumSet;
import java.util.List;
import java.util.Set;

/**
 * Your best games ever, kept apart from the recent games so they outlive them: the most damage
 * in a game, the fastest win and the longest run of games won.
 */
public final class Bests
{
	/** What a game can beat. */
	public enum Kind
	{
		DAMAGE,
		FASTEST,
		STREAK
	}

	/** A best is only news once there are this many games to have beaten. */
	static final int NEWS_AFTER = 5;
	/** A win shorter than this was not a whole game seen from the start. */
	static final int SHORTEST_WIN = 60;

	private int damage;
	private long damageAt;
	private int fastest;
	private long fastestAt;
	private int streak;
	private int bestStreak;
	private long bestStreakAt;
	private int counted;
	/** Whether the run in hand has already been called a new best. */
	private boolean runTold;

	/** Works the bests out from the games kept, for a save made before bests were kept. */
	static Bests of(List<GameRecord> games)
	{
		Bests b = new Bests();
		for (GameRecord g : games)
		{
			b.add(g);
		}
		return b;
	}

	/** @return what the game beat, empty early on when every game is a best */
	public Set<Kind> add(GameRecord g)
	{
		return add(g, true);
	}

	/**
	 * @param whole whether the game was seen from its start; one picked up part way through ran
	 *              longer than its count says, so it cannot be the fastest win
	 * @return what the game beat, empty early on when every game is a best
	 */
	public Set<Kind> add(GameRecord g, boolean whole)
	{
		Set<Kind> beat = EnumSet.noneOf(Kind.class);
		if (g == null || g.getResult() == GameRecord.Result.LEFT)
		{
			return beat;
		}
		boolean news = counted >= NEWS_AFTER;
		counted++;
		if (g.getDamage() > damage)
		{
			if (news && damage > 0)
			{
				beat.add(Kind.DAMAGE);
			}
			damage = g.getDamage();
			damageAt = g.getEnded();
		}
		if (g.getResult() == GameRecord.Result.LOST)
		{
			streak = 0;
			runTold = false;
			return beat;
		}
		if (whole && g.getResult() == GameRecord.Result.WON && g.getSeconds() >= SHORTEST_WIN && (fastest == 0 || g.getSeconds() < fastest))
		{
			if (news && fastest > 0)
			{
				beat.add(Kind.FASTEST);
			}
			fastest = g.getSeconds();
			fastestAt = g.getEnded();
		}
		streak++;
		if (streak > bestStreak)
		{
			// Said once, as the run first passes the old best.
			if (news && bestStreak > 0 && !runTold)
			{
				beat.add(Kind.STREAK);
				runTold = true;
			}
			bestStreak = streak;
			bestStreakAt = g.getEnded();
		}
		return beat;
	}

	/** A copy to hand the panel, which draws on another thread. */
	public Bests copy()
	{
		Bests c = new Bests();
		c.damage = damage;
		c.damageAt = damageAt;
		c.fastest = fastest;
		c.fastestAt = fastestAt;
		c.streak = streak;
		c.bestStreak = bestStreak;
		c.bestStreakAt = bestStreakAt;
		c.counted = counted;
		c.runTold = runTold;
		return c;
	}

	/** Brings back figures out of range, and any a damaged save lost, from the games kept. */
	Bests repair(List<GameRecord> games)
	{
		Bests from = of(games);
		if (damage <= 0 && from.damage > 0)
		{
			damage = from.damage;
			damageAt = from.damageAt;
		}
		if (fastest <= 0 && from.fastest > 0)
		{
			fastest = from.fastest;
			fastestAt = from.fastestAt;
		}
		if (bestStreak < from.bestStreak)
		{
			bestStreak = from.bestStreak;
			bestStreakAt = from.bestStreakAt;
		}
		counted = Math.max(counted, from.counted);
		return repair();
	}

	Bests repair()
	{
		damage = Math.max(0, damage);
		fastest = Math.max(0, fastest);
		streak = Math.max(0, streak);
		bestStreak = Math.max(streak, bestStreak);
		counted = Math.max(0, counted);
		return this;
	}

	public boolean isEmpty()
	{
		return counted == 0;
	}

	/** Most damage in one game, 0 before any. */
	public int getDamage()
	{
		return damage;
	}

	public long getDamageAt()
	{
		return damageAt;
	}

	/** Seconds of the fastest win, 0 before any. */
	public int getFastest()
	{
		return fastest;
	}

	public long getFastestAt()
	{
		return fastestAt;
	}

	/** Games won in a row up to now. */
	public int getStreak()
	{
		return streak;
	}

	/** The longest run of games won. */
	public int getBestStreak()
	{
		return bestStreak;
	}

	public long getBestStreakAt()
	{
		return bestStreakAt;
	}

	/** The chat line for what a game beat, or null. */
	public String news(Set<Kind> beat)
	{
		if (beat == null || beat.isEmpty())
		{
			return null;
		}
		StringBuilder s = new StringBuilder("A new best: ");
		String sep = "";
		if (beat.contains(Kind.DAMAGE))
		{
			s.append(sep).append(damage).append(" damage");
			sep = ", ";
		}
		if (beat.contains(Kind.FASTEST))
		{
			s.append(sep).append("a win in ").append(fastest / 60).append("m ").append(String.format(java.util.Locale.ENGLISH, "%02ds", fastest % 60));
			sep = ", ";
		}
		if (beat.contains(Kind.STREAK))
		{
			s.append(sep).append(bestStreak).append(" wins in a row");
		}
		return s.toString();
	}
}

package com.codex.pestcontrol.core;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * The lander you sit in: how many players are ready, and whether it is filling too slowly for a
 * game to start, in which case the Pest Control world is the place to be.
 */
public final class Boarding
{
	/** A lander leaves with no fewer than this many players aboard. */
	public static final int MIN_PLAYERS = 5;
	/** The world most Pest Control players use. */
	public static final int PEST_CONTROL_WORLD = 344;
	/** Ticks a lander must stay short of players before it is called quiet: about half a minute. */
	static final int QUIET_TICKS = 50;

	private static final Pattern NUMBER = Pattern.compile("([0-9]{1,4})");

	private int ticks;
	private int ready = -1;

	/**
	 * One tick aboard.
	 *
	 * @param readyText the lander's players-ready line, such as "Players Ready: 3", or null when unread
	 */
	public void tick(String readyText)
	{
		ticks++;
		int n = parse(readyText);
		if (n >= 0)
		{
			ready = n;
		}
	}

	/** Off the lander: start again next time. */
	public void leave()
	{
		ticks = 0;
		ready = -1;
	}

	/** Players ready, or -1 when not read. */
	public int getReady()
	{
		return ready;
	}

	/** The lander has sat short of a game for a while, on a world other than the Pest Control world. */
	public boolean isQuiet(int world)
	{
		return ready >= 0 && ready < MIN_PLAYERS && ticks >= QUIET_TICKS && world != PEST_CONTROL_WORLD;
	}

	/** What to say about a quiet lander. */
	public String tip()
	{
		return "Only " + ready + " aboard and a game needs " + MIN_PLAYERS + "; most players use world " + PEST_CONTROL_WORLD;
	}

	static int parse(String text)
	{
		if (text == null)
		{
			return -1;
		}
		Matcher m = NUMBER.matcher(text.replaceAll("<[^>]*>", ""));
		return m.find() ? Integer.parseInt(m.group(1)) : -1;
	}
}

package com.codex.pestcontrol.core;

/** The three landers: the combat level to board and the points a won game gives. */
public enum Boat
{
	NOVICE("Novice", 40, 3),
	INTERMEDIATE("Intermediate", 70, 4),
	VETERAN("Veteran", 100, 5);

	private final String title;
	private final int combat;
	private final int points;

	Boat(String title, int combat, int points)
	{
		this.title = title;
		this.combat = combat;
		this.points = points;
	}

	public String getTitle()
	{
		return title;
	}

	public int getCombat()
	{
		return combat;
	}

	public int getPoints()
	{
		return points;
	}

	/** The best lander a combat level can board. */
	public static Boat forCombat(int level)
	{
		if (level >= VETERAN.combat)
		{
			return VETERAN;
		}
		if (level >= INTERMEDIATE.combat)
		{
			return INTERMEDIATE;
		}
		return NOVICE;
	}

	/** The lander a won game's points came from, or null for any other number. */
	public static Boat forPoints(int points)
	{
		for (Boat b : values())
		{
			if (b.points == points)
			{
				return b;
			}
		}
		return null;
	}

	public static Boat named(String name)
	{
		for (Boat b : values())
		{
			if (b.name().equals(name))
			{
				return b;
			}
		}
		return null;
	}
}

package com.codex.pestcontrol.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Points spent on combat experience at the Void Knights' reward shop, for points the goal does not
 * need. Per the OSRS Wiki, each point buys floor(level squared / 600) times 35 experience in
 * Attack, Strength, Defence or Hitpoints, 32 in Ranged or Magic and 18 in Prayer; a skill must be
 * at level 25 to buy any; and buying 100 points at once adds 10%, 10 at once 1%.
 */
public final class Experience
{
	/** The lowest level the shop sells experience at. */
	public static final int MIN_LEVEL = 25;

	/** The skills the shop sells experience in, with the experience a point buys per level-squared step. */
	public enum Skill
	{
		ATTACK("Attack", 35),
		STRENGTH("Strength", 35),
		DEFENCE("Defence", 35),
		HITPOINTS("Hitpoints", 35),
		RANGED("Ranged", 32),
		MAGIC("Magic", 32),
		PRAYER("Prayer", 18);

		private final String title;
		private final int factor;

		Skill(String title, int factor)
		{
			this.title = title;
			this.factor = factor;
		}

		public String getTitle()
		{
			return title;
		}
	}

	/** What spare points buy in one skill. */
	public static final class Line
	{
		private final Skill skill;
		private final int level;
		private final long xp;

		Line(Skill skill, int level, long xp)
		{
			this.skill = skill;
			this.level = level;
			this.xp = xp;
		}

		public Skill getSkill()
		{
			return skill;
		}

		public int getLevel()
		{
			return level;
		}

		/** Experience the points buy; 0 below level 25. */
		public long getXp()
		{
			return xp;
		}

		public boolean isLocked()
		{
			return level < MIN_LEVEL;
		}
	}

	private Experience()
	{
	}

	/** Experience one point buys at a level, before any bundle bonus; 0 below level 25. */
	public static int perPoint(Skill skill, int level)
	{
		if (level < MIN_LEVEL)
		{
			return 0;
		}
		int capped = Math.min(99, level);
		return capped * capped / 600 * skill.factor;
	}

	/** Total experience a level starts at, the game's own table; 0 for level 1 or below. */
	public static long xpFor(int level)
	{
		long points = 0;
		for (int lvl = 1; lvl < Math.min(level, 127); lvl++)
		{
			points += (long) Math.floor(lvl + 300.0 * Math.pow(2.0, lvl / 7.0));
		}
		return points / 4;
	}

	/** The level a total of experience makes, up to 99. */
	public static int levelFor(long xp)
	{
		int level = 1;
		while (level < 99 && xpFor(level + 1) <= xp)
		{
			level++;
		}
		return level;
	}

	/**
	 * Points it takes to reach a level by buying experience alone, in the biggest bundles that do
	 * not buy more than is needed, and with each purchase paid at the level it is made at.
	 *
	 * @param xp experience in the skill now
	 * @return the points, 0 when the level is already reached, or -1 below level 25, where the shop sells nothing
	 */
	public static int pointsTo(Skill skill, long xp, int target)
	{
		long goal = xpFor(Math.min(99, target));
		int points = 0;
		long have = xp;
		while (have < goal)
		{
			int per = perPoint(skill, levelFor(have));
			if (per == 0)
			{
				return -1;
			}
			long left = goal - have;
			if (left >= per * 110L)
			{
				points += 100;
				have += per * 110L;
			}
			else if (left >= per * 101L / 10)
			{
				points += 10;
				have += per * 101L / 10;
			}
			else
			{
				points += 1;
				have += per;
			}
		}
		return points;
	}

	/** Experience the points buy when spent in the biggest bundles: hundreds, then tens, then ones. */
	public static long forPoints(Skill skill, int level, int points)
	{
		int per = perPoint(skill, level);
		if (per == 0 || points <= 0)
		{
			return 0;
		}
		long hundreds = points / 100;
		long tens = points % 100 / 10;
		long ones = points % 10;
		// Each bundle is paid out whole, rounded down, as the shop pays one purchase at a time.
		return hundreds * (per * 110L) + tens * (per * 101L / 10) + ones * per;
	}

	/**
	 * Points the goal leaves spare: everything held once the goal is bought or complete, else none.
	 *
	 * @return 0 when points are not known or the goal still needs them all
	 */
	public static int spare(Outlook outlook)
	{
		if (outlook == null || !outlook.isPointsKnown())
		{
			return 0;
		}
		return Math.max(0, outlook.getPoints() - outlook.getCost());
	}

	/**
	 * Games it takes to earn the points for some experience, after the goal: points the goal leaves
	 * spare count first, and the points the goal still needs are earned before any go to experience.
	 *
	 * @return the games, 0 when the spare points already cover it, -1 before the points are read
	 */
	public static int gamesFor(Outlook outlook, int points)
	{
		if (!outlook.isPointsKnown())
		{
			return -1;
		}
		long earn = (long) points - spare(outlook) + outlook.getRemaining();
		return earn <= 0 ? 0 : (int) Math.ceil(earn / Math.max(0.5, outlook.getPerGame()));
	}

	/**
	 * What the points buy in every skill, the most experience first and skills below 25 last.
	 *
	 * @param levels each skill's real level, in {@link Skill} order
	 */
	public static List<Line> of(int[] levels, int points)
	{
		List<Line> out = new ArrayList<>();
		for (Skill s : Skill.values())
		{
			int level = levels != null && s.ordinal() < levels.length ? levels[s.ordinal()] : 0;
			out.add(new Line(s, level, forPoints(s, level, points)));
		}
		out.sort((a, b) -> a.isLocked() != b.isLocked() ? (a.isLocked() ? 1 : -1)
			: a.xp != b.xp ? Long.compare(b.xp, a.xp) : a.skill.compareTo(b.skill));
		return Collections.unmodifiableList(out);
	}
}

