package com.codex.pestcontrol.core;

/** One finished game, as kept in the logbook. Fields are plain so Gson can store it. */
public class GameRecord
{
	public enum Result
	{
		WON,
		LOST,
		/** Won, but too little damage was dealt to be given points. */
		NO_POINTS,
		/** Left or logged out before the end. */
		LEFT
	}

	/** The most points one game gives: a won veteran game, with room to spare. */
	public static final int MAX_POINTS = 100;
	/** No game lasts longer than its twenty minutes. */
	static final int MAX_SECONDS = 20 * 60;

	private long ended;
	private String boat;
	private String result;
	private int points;
	private int damage;
	private int seconds;

	public GameRecord()
	{
	}

	public GameRecord(long ended, Boat boat, Result result, int points, int damage, int seconds)
	{
		this.ended = ended;
		this.boat = boat == null ? null : boat.name();
		this.result = result.name();
		this.points = points;
		this.damage = damage;
		this.seconds = seconds;
	}

	public long getEnded()
	{
		return ended;
	}

	public Boat getBoat()
	{
		return Boat.named(boat);
	}

	public Result getResult()
	{
		try
		{
			return result == null ? Result.LEFT : Result.valueOf(result);
		}
		catch (IllegalArgumentException e)
		{
			return Result.LEFT;
		}
	}

	public int getPoints()
	{
		return points;
	}

	public int getDamage()
	{
		return damage;
	}

	public int getSeconds()
	{
		return seconds;
	}

	/** Brings figures a damaged save holds out of range back into it. */
	void repair()
	{
		ended = Math.max(0, ended);
		points = Math.max(0, Math.min(points, MAX_POINTS));
		damage = Math.max(0, damage);
		seconds = Math.max(0, Math.min(seconds, MAX_SECONDS));
	}
}

package com.codex.pestcontrol.core;

import java.text.NumberFormat;
import java.util.Locale;

/**
 * The line written in the chat box after a game: what it gave, how far the goal is, and the
 * sitting so far with its points an hour, lander time counted. Warns when the points near the cap
 * the Void Knights will hold.
 */
public final class GameSummary
{
	/** The warning comes this close to the cap. */
	static final int CAP_WARN = 50;
	/** Damage a game needs before it gives points. */
	static final int ZEAL = 50;

	private GameSummary()
	{
	}

	/**
	 * The line when the points newly cover a piece of the goal, or all of it, or null.
	 *
	 * @param locked elite pieces the hard diary still locks, which points cannot buy
	 */
	public static String announcement(Outlook before, Outlook after, java.util.Set<Reward> locked)
	{
		if (before == null || after == null || !after.isPointsKnown())
		{
			return null;
		}
		Reward now = firstBuy(after, locked);
		Reward was = firstBuy(before, locked);
		// Points that cover a piece the diary locks do not buy it, so neither is announced.
		boolean all = after.isAffordable() && (locked == null || locked.isEmpty());
		boolean wasAll = before.isAffordable() && (locked == null || locked.isEmpty());
		if (now == null || was == now && wasAll == all)
		{
			return null;
		}
		return all
			? "your " + number(after.getPoints()) + " points now cover everything left in your goal. Visit the Void Knights' reward shop."
			: "your " + number(after.getPoints()) + " points now cover the " + now.getTitle().toLowerCase(Locale.ENGLISH) + ".";
	}

	/** The first piece the buy order says the points buy now, never a locked one, or null. */
	private static Reward firstBuy(Outlook o, java.util.Set<Reward> locked)
	{
		if (!o.isPointsKnown())
		{
			return null;
		}
		for (Outlook.Milestone m : o.milestones(locked))
		{
			return m.getGames() == 0 && (locked == null || !locked.contains(m.getReward())) ? m.getReward() : null;
		}
		return null;
	}

	/**
	 * @param after the goal as it stands after the game, or null
	 * @param sitting the sitting the game ends, or null
	 * @return the line, or null for a game left before the end
	 */
	public static String of(GameRecord game, Outlook after, Sitting sitting)
	{
		if (game == null || game.getResult() == GameRecord.Result.LEFT)
		{
			return null;
		}
		StringBuilder text = new StringBuilder();
		switch (game.getResult())
		{
			case WON:
				text.append("Won, +").append(game.getPoints()).append(game.getPoints() == 1 ? " point" : " points");
				break;
			case NO_POINTS:
				// The damage counted here can miss what the game counts; only say how short when it was.
				text.append(game.getDamage() < ZEAL ? "Won, but no points: " + game.getDamage() + " of the 50 damage needed"
					: "Won, but the game gave no points for too little damage");
				break;
			default:
				text.append("Lost");
				break;
		}
		if (game.getResult() != GameRecord.Result.NO_POINTS)
		{
			text.append(", ").append(game.getDamage()).append(" damage");
		}
		if (after != null && after.isPointsKnown())
		{
			if (!after.isComplete() && !after.isAffordable())
			{
				text.append(". ").append(number(after.getPoints())).append(" of ").append(number(after.getCost()))
					.append(" points for your goal, about ").append(number(after.getGames())).append(after.getGames() == 1 ? " game" : " games")
					.append(" to go");
			}
			if (after.getPoints() >= Logbook.POINTS_CAP - CAP_WARN)
			{
				text.append(". You hold ").append(number(after.getPoints())).append(" of the ")
					.append(number(Logbook.POINTS_CAP)).append(" points the knights will keep: spend some");
			}
		}
		if (sitting != null && sitting.getGames().size() >= 2)
		{
			text.append(". This sitting: ").append(number(sitting.getGames().size())).append(" games, ")
				.append(number(sitting.getPoints())).append(" points");
			if (sitting.pointsPerHour() > 0)
			{
				text.append(", ").append(sitting.pointsPerHour()).append(" an hour");
			}
		}
		return text.append(".").toString();
	}

	private static String number(long n)
	{
		return NumberFormat.getIntegerInstance(Locale.ENGLISH).format(n);
	}
}

package com.codex.pestcontrol.core;

/**
 * When a Pest Control game starts and ends, from whether its status bar is shown each tick. The
 * bar going does not end the game at once: its closing messages (points, a loss) arrive a few
 * ticks later, so the game settles for {@link #SETTLE_TICKS} first. If the bar comes back while it
 * settles (a dropped connection the client got back, an interface that flickered), the same game
 * carries on with the damage already dealt, rather than a fresh one starting from nothing.
 */
public final class GameWatch
{
	/** What a tick asks of the plugin. */
	public enum Act
	{
		NONE,
		/** A new game began: start counting. */
		START,
		/** The game that was settling is still on: carry on with it. */
		RESUME,
		/** The bar went: hold the game while its closing messages arrive. */
		SETTLE,
		/** The game settled: record it. */
		FINISH
	}

	/** Ticks after a game's status bar goes for its closing messages to arrive. */
	public static final int SETTLE_TICKS = 4;

	private boolean shown;
	/** Ticks the settling game has waited, counting the tick the bar went; 0 when none is settling. */
	private int settling;

	/** @param barShown the game's status bar is shown this tick */
	public Act tick(boolean barShown)
	{
		if (barShown)
		{
			if (shown)
			{
				return Act.NONE;
			}
			shown = true;
			if (settling > 0)
			{
				settling = 0;
				return Act.RESUME;
			}
			return Act.START;
		}
		if (shown)
		{
			shown = false;
			settling = 1;
			return SETTLE_TICKS <= 1 ? finish() : Act.SETTLE;
		}
		if (settling > 0 && ++settling >= SETTLE_TICKS)
		{
			return finish();
		}
		return Act.NONE;
	}

	private Act finish()
	{
		settling = 0;
		return Act.FINISH;
	}

	/** The game is over whatever the bar does next, as at logout: start afresh. */
	public void reset()
	{
		shown = false;
		settling = 0;
	}

	/** A game is being counted or settling. */
	public boolean isBusy()
	{
		return shown || settling > 0;
	}
}

