package com.codex.pestcontrol.core;

import java.util.ArrayList;
import java.util.List;

/**
 * How much the player plays Pest Control, read from their own sittings over the last four weeks,
 * so a number of games can be turned into a date: "the set is yours about 12 Nov". A first busy
 * weekend is spread over a week, so it does not read as playing every day, unless the logbook no
 * longer holds the older games, in which case only the time its games span is counted.
 */
public final class Habit
{
	static final long DAY_MS = 24 * 3_600_000L;
	static final long WINDOW_MS = 28 * DAY_MS;
	static final long MIN_SPAN_MS = 7 * DAY_MS;
	/** Fewer sittings than this say nothing about how often the player comes back. */
	static final int MIN_SITTINGS = 2;
	/** Past this a date says nothing useful. */
	static final long MAX_DAYS = 3 * 365;

	private final int sittings;
	private final int games;
	private final long playedMs;
	private final long spanMs;

	private Habit(int sittings, int games, long playedMs, long spanMs)
	{
		this.sittings = sittings;
		this.games = games;
		this.playedMs = playedMs;
		this.spanMs = spanMs;
	}

	/**
	 * @param games the games kept, oldest first
	 * @param complete whether the logbook still holds every game ever played, so the oldest kept is the first
	 */
	public static Habit of(List<GameRecord> games, boolean complete, long now)
	{
		List<List<GameRecord>> sittings = new ArrayList<>();
		List<GameRecord> group = null;
		for (GameRecord g : games)
		{
			long start = g.getEnded() - g.getSeconds() * 1000L;
			if (start < now - WINDOW_MS || g.getEnded() > now)
			{
				continue;
			}
			if (group == null || start - group.get(group.size() - 1).getEnded() > Logbook.BREAK_MS)
			{
				group = new ArrayList<>();
				sittings.add(group);
			}
			group.add(g);
		}
		int n = 0;
		long played = 0;
		long first = now;
		for (List<GameRecord> s : sittings)
		{
			GameRecord a = s.get(0);
			long start = a.getEnded() - a.getSeconds() * 1000L;
			played += Math.max(0, s.get(s.size() - 1).getEnded() - start);
			n += s.size();
			first = Math.min(first, start);
		}
		long span = Math.max(DAY_MS, now - first);
		if (complete)
		{
			span = Math.max(MIN_SPAN_MS, span);
		}
		return new Habit(sittings.size(), n, played, span);
	}

	/** Enough sittings to tell a pace from. */
	public boolean isKnown()
	{
		return sittings >= MIN_SITTINGS && playedMs > 0 && games > 0;
	}

	/** Hours played a week. */
	public double hoursPerWeek()
	{
		return playedMs / 3_600_000.0 * (7.0 * DAY_MS / spanMs);
	}

	/** Games played an hour, the lander time between them included. */
	public double gamesPerHour()
	{
		return playedMs <= 0 ? 0 : games * 3_600_000.0 / playedMs;
	}

	/** @return when that many more games are played at this pace, or -1 when it cannot be told or is years away */
	public long afterGames(long more, long now)
	{
		if (!isKnown() || more < 0)
		{
			return -1;
		}
		double days = more / gamesPerHour() / hoursPerWeek() * 7;
		return days > MAX_DAYS ? -1 : now + Math.round(days * DAY_MS);
	}
}

package com.codex.pestcontrol.core;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/**
 * How each lander has gone for you, from your own games: how often you win there, the points a
 * game really gives once losses are counted, how long one game takes from the end of the last,
 * and so the points an hour. A veteran game pays more but a quick intermediate world can beat it.
 */
public final class Landers
{
	/** Games on a lander before its figures are trusted for a recommendation. */
	public static final int TRUSTED = 3;

	/** One lander's figures. */
	public static final class Line
	{
		private final Boat boat;
		private final int games;
		private final int won;
		private final double pointsPerGame;
		private final double minutesPerGame;
		private final double averageDamage;

		Line(Boat boat, int games, int won, double pointsPerGame, double minutesPerGame, double averageDamage)
		{
			this.boat = boat;
			this.games = games;
			this.won = won;
			this.pointsPerGame = pointsPerGame;
			this.minutesPerGame = minutesPerGame;
			this.averageDamage = averageDamage;
		}

		public Boat getBoat()
		{
			return boat;
		}

		public int getGames()
		{
			return games;
		}

		public int getWon()
		{
			return won;
		}

		public double winRate()
		{
			return games == 0 ? 0 : won / (double) games;
		}

		public double getPointsPerGame()
		{
			return pointsPerGame;
		}

		/** Minutes from the end of one game to the end of the next, lander wait included. */
		public double getMinutesPerGame()
		{
			return minutesPerGame;
		}

		public double getAverageDamage()
		{
			return averageDamage;
		}

		public double pointsPerHour()
		{
			return minutesPerGame <= 0 ? 0 : pointsPerGame * 60 / minutesPerGame;
		}

		public boolean isTrusted()
		{
			return games >= TRUSTED;
		}
	}

	private Landers()
	{
	}

	/**
	 * Each lander's figures from the games kept, in lander order, leaving out landers never played.
	 * Games left early are not counted.
	 */
	public static List<Line> of(List<GameRecord> games)
	{
		Map<Boat, int[]> counts = new EnumMap<>(Boat.class);
		Map<Boat, double[]> sums = new EnumMap<>(Boat.class);
		GameRecord previous = null;
		for (GameRecord g : games)
		{
			if (g.getResult() == GameRecord.Result.LEFT)
			{
				previous = null;
				continue;
			}
			Boat b = g.getBoat();
			if (b == null)
			{
				previous = g;
				continue;
			}
			int[] c = counts.computeIfAbsent(b, k -> new int[3]);
			double[] s = sums.computeIfAbsent(b, k -> new double[4]);
			c[0]++;
			if (g.getResult() != GameRecord.Result.LOST)
			{
				c[1]++;
			}
			s[0] += g.getPoints();
			s[1] += g.getSeconds();
			s[3] += g.getDamage();
			// Back to back on the same lander: the gap between endings is a whole game with its wait.
			if (previous != null && previous.getBoat() == b)
			{
				long gap = g.getEnded() - previous.getEnded();
				if (gap > 0 && gap < Logbook.BREAK_MS)
				{
					s[2] += gap / 60_000.0;
					c[2]++;
				}
			}
			previous = g;
		}
		List<Line> out = new ArrayList<>();
		for (Boat b : Boat.values())
		{
			int[] c = counts.get(b);
			if (c == null)
			{
				continue;
			}
			double[] s = sums.get(b);
			double minutes = c[2] >= 2 ? s[2] / c[2] : (s[1] / c[0] + Logbook.LANDER_SECONDS) / 60.0;
			out.add(new Line(b, c[0], c[1], s[0] / c[0], minutes, s[3] / c[0]));
		}
		return out;
	}

	/** The trusted lander with the most points an hour that the combat level can board, or null. */
	public static Line best(List<Line> lines, int combat)
	{
		Line best = null;
		for (Line l : lines)
		{
			if (l.isTrusted() && combat >= l.getBoat().getCombat() && (best == null || l.pointsPerHour() > best.pointsPerHour()))
			{
				best = l;
			}
		}
		return best;
	}

	/** The line for a lander, or null when it has not been played. */
	public static Line of(List<Line> lines, Boat boat)
	{
		for (Line l : lines)
		{
			if (l.getBoat() == boat)
			{
				return l;
			}
		}
		return null;
	}
}

package com.codex.pestcontrol.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;

/**
 * Everything the Pilot keeps for one account: the points last seen, the goal, which rewards
 * the account already owns, and its games. Saved as one Gson blob per RuneScape profile.
 */
public class Logbook
{
	/** Games kept one by one; older ones live on only in the totals. */
	static final int KEEP = 60;
	/**
	 * A save at least this long is far bigger than any the pilot writes (60 games come to about
	 * 6,000 characters) and takes long enough to read that it is read off the client thread.
	 */
	public static final int LARGE = 100_000;
	/** Games the points-per-game average is taken over. */
	static final int RECENT = 20;
	/** A gap longer than this between two games is a break, not lander time. */
	static final long BREAK_MS = 15 * 60_000L;
	/** Lander wait assumed before any has been measured, in seconds. */
	static final int LANDER_SECONDS = 60;
	/** The most points the Void Knights will hold for you. */
	public static final int POINTS_CAP = 4000;

	private int points = -1;
	private long pointsSeen;
	private List<String> goal;
	private List<String> owned;
	private long ownedSeen;
	private List<GameRecord> games;
	private int played;
	private int won;
	private int earned;
	private long seconds;
	private ShieldClock clock;
	private Bests bests;

	public Logbook()
	{
		goal = names(Goal.MELEE.getRewards());
		owned = new ArrayList<>();
		games = new ArrayList<>();
		clock = new ShieldClock();
		bests = new Bests();
	}

	/** How long shields take to drop, learned from your games. */
	public ShieldClock getClock()
	{
		if (clock == null)
		{
			clock = new ShieldClock();
		}
		return clock;
	}

	/**
	 * Reads the logbook saved for an account, or a fresh one when there is none. A damaged save
	 * keeps all it can: a field or game that cannot be read is lost alone.
	 */
	public static Logbook read(com.google.gson.Gson gson, String saved)
	{
		Logbook read = Salvage.read(gson, saved, Logbook.class);
		return read == null ? new Logbook() : read.repair();
	}

	/** Fills in anything an older or damaged save left out, and brings back figures out of range. */
	public Logbook repair()
	{
		if (goal == null)
		{
			goal = names(Goal.MELEE.getRewards());
		}
		goal.removeIf(n -> n == null);
		if (owned == null)
		{
			owned = new ArrayList<>();
		}
		owned.removeIf(n -> n == null);
		if (games == null)
		{
			games = new ArrayList<>();
		}
		games.removeIf(g -> g == null);
		games.forEach(GameRecord::repair);
		while (games.size() > KEEP)
		{
			games.remove(0);
		}
		if (clock == null)
		{
			clock = new ShieldClock();
		}
		clock.repair();
		// A save from before bests were kept starts from the games it holds.
		bests = bests == null || bests.isEmpty() ? Bests.of(games) : bests.repair(games);
		// The knights hold at most the cap; below zero is "not read yet".
		points = points < 0 ? -1 : Math.min(points, POINTS_CAP);
		pointsSeen = Math.max(0, pointsSeen);
		ownedSeen = Math.max(0, ownedSeen);
		played = Math.max(0, played);
		won = Math.max(0, Math.min(won, played));
		earned = Math.max(0, earned);
		seconds = Math.max(0, seconds);
		return this;
	}

	/** @return whether the number changed */
	public boolean seePoints(int value, long now)
	{
		if (value < 0)
		{
			return false;
		}
		boolean changed = value != points;
		points = value;
		pointsSeen = now;
		return changed;
	}

	/** Points last seen, or -1 before the first lander or reward shop. */
	public int getPoints()
	{
		return points;
	}

	public long getPointsSeen()
	{
		return pointsSeen;
	}

	public Set<Reward> getGoal()
	{
		return set(goal);
	}

	public void setGoal(Set<Reward> rewards)
	{
		goal = names(rewards);
	}

	public void toggle(Reward reward)
	{
		Set<Reward> g = getGoal();
		if (!g.remove(reward))
		{
			g.add(reward);
		}
		setGoal(g);
	}

	public Set<Reward> getOwned()
	{
		return set(owned);
	}

	/** @return whether what is owned changed */
	public boolean seeOwned(Set<Reward> rewards, long now)
	{
		Set<Reward> before = getOwned();
		owned = names(rewards);
		ownedSeen = now;
		return !before.equals(rewards);
	}

	/** When the bank was last looked through for rewards, or 0 if never. */
	public long getOwnedSeen()
	{
		return ownedSeen;
	}

	/** Your best games; see {@link Bests}. */
	public Bests getBests()
	{
		if (bests == null)
		{
			bests = Bests.of(games);
		}
		return bests;
	}

	/** @return the bests the game beat */
	public Set<Bests.Kind> record(GameRecord game)
	{
		return record(game, true);
	}

	/**
	 * @param whole whether the game was seen from its start
	 * @return the bests the game beat
	 */
	public Set<Bests.Kind> record(GameRecord game, boolean whole)
	{
		Set<Bests.Kind> beat = getBests().add(game, whole);
		games.add(game);
		while (games.size() > KEEP)
		{
			games.remove(0);
		}
		if (game.getResult() == GameRecord.Result.LEFT)
		{
			return beat;
		}
		played++;
		if (game.getResult() != GameRecord.Result.LOST)
		{
			won++;
		}
		earned += game.getPoints();
		seconds += game.getSeconds();
		return beat;
	}

	public List<GameRecord> getGames()
	{
		return Collections.unmodifiableList(games);
	}

	/** Finished games, not counting ones left early. */
	public int getPlayed()
	{
		return played;
	}

	public int getWon()
	{
		return won;
	}

	public int getEarned()
	{
		return earned;
	}

	public long getSeconds()
	{
		return seconds;
	}

	/** The finished games among the most recent ones, newest last. */
	List<GameRecord> recentFinished()
	{
		List<GameRecord> out = new ArrayList<>();
		for (int i = games.size() - 1; i >= 0 && out.size() < RECENT; i--)
		{
			GameRecord g = games.get(i);
			if (g.getResult() != GameRecord.Result.LEFT)
			{
				out.add(0, g);
			}
		}
		return out;
	}

	/**
	 * Points a game is worth to you, lost games included: measured once three games are in,
	 * else what a won game on the given lander gives.
	 */
	public double pointsPerGame(Boat fallback)
	{
		List<GameRecord> recent = recentFinished();
		if (recent.size() < 3)
		{
			return fallback.getPoints();
		}
		double sum = 0;
		for (GameRecord g : recent)
		{
			sum += g.getPoints();
		}
		return Math.max(0.5, sum / recent.size());
	}

	/** Whether the points per game are measured rather than assumed. */
	public boolean isMeasured()
	{
		return recentFinished().size() >= 3;
	}

	/**
	 * Minutes from one game to the next, lander wait included: measured from games played back
	 * to back, else the average game plus a minute in the lander, else five minutes.
	 */
	public double minutesPerGame()
	{
		List<GameRecord> recent = recentFinished();
		double gaps = 0;
		int n = 0;
		for (int i = 1; i < recent.size(); i++)
		{
			long gap = recent.get(i).getEnded() - recent.get(i - 1).getEnded();
			if (gap > 0 && gap < BREAK_MS)
			{
				gaps += gap;
				n++;
			}
		}
		if (n >= 2)
		{
			return gaps / n / 60_000.0;
		}
		if (!recent.isEmpty())
		{
			double s = 0;
			for (GameRecord g : recent)
			{
				s += g.getSeconds();
			}
			return (s / recent.size() + LANDER_SECONDS) / 60.0;
		}
		return 5;
	}

	private static List<String> names(Iterable<Reward> rewards)
	{
		List<String> out = new ArrayList<>();
		for (Reward r : rewards)
		{
			out.add(r.name());
		}
		return out;
	}

	private static Set<Reward> set(List<String> names)
	{
		Set<Reward> out = EnumSet.noneOf(Reward.class);
		if (names != null)
		{
			for (String n : names)
			{
				Reward r = Reward.named(n);
				if (r != null)
				{
					out.add(r);
				}
			}
		}
		return out;
	}
}

package com.codex.pestcontrol.core;

import com.google.gson.Gson;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * The combat levels Codex Navigator's pinned goals still need, for the experience the reward shop sells. Navigator saves its goal board
 * for companion plugins under the RS profile key {@code codexnavigator.goalBoard} (fields are
 * only ever added); this keeps each unfinished goal's title and levels. Read only, and with
 * Navigator not installed there is no board and nothing is shown.
 */
public final class NavigatorGoals
{
	public static final String GROUP = "codexnavigator";
	public static final String KEY = "goalBoard";

	/** One pinned goal, as saved. Field names are Navigator's. */
	static final class Entry
	{
		String key;
		String title;
		boolean complete;
		Map<String, Integer> skills;
	}

	/** Navigator's saved board, as far as it is read here. */
	static final class Board
	{
		String focus;
		List<Entry> goals;
	}

	/** A level one goal needs. */
	public static final class Need
	{
		private final String goal;
		private final String skill;
		private final int level;
		private final boolean focus;

		Need(String goal, String skill, int level, boolean focus)
		{
			this.goal = goal;
			this.skill = skill;
			this.level = level;
			this.focus = focus;
		}

		/** The skill as Navigator names it, such as "Prayer". */
		public String getSkill()
		{
			return skill;
		}

		/** The goal's title, such as "Song of the Elves". */
		public String getGoal()
		{
			return goal;
		}

		public int getLevel()
		{
			return level;
		}

		/** The goal Navigator has in focus. */
		public boolean isFocus()
		{
			return focus;
		}
	}

	private NavigatorGoals()
	{
	}

	/**
	 * @param json the board as Navigator saved it, or null
	 * @param levels each skill's level now by name, such as "Prayer"; skills not listed are not asked about
	 * @return every unfinished goal's need above the level now in those skills, the focus goal first, then lowest level first
	 */
	public static List<Need> needs(Gson gson, String json, Map<String, Integer> levels)
	{
		if (json == null || json.isEmpty())
		{
			return Collections.emptyList();
		}
		Board board;
		try
		{
			board = gson.fromJson(json, Board.class);
		}
		catch (RuntimeException | StackOverflowError e)
		{
			// Cut short, not JSON, or garbage nested deeper than Gson reads.
			return Collections.emptyList();
		}
		if (board == null || board.goals == null)
		{
			return Collections.emptyList();
		}
		List<Need> out = new ArrayList<>();
		for (Entry e : board.goals)
		{
			if (e == null || e.complete || e.skills == null)
			{
				continue;
			}
			for (Map.Entry<String, Integer> s : e.skills.entrySet())
			{
				Integer need = s.getValue();
				String skill = canonical(levels, s.getKey());
				if (skill == null || need == null || need <= levels.get(skill) || need > 99)
				{
					continue;
				}
				String title = e.title == null || e.title.isEmpty() ? "A Navigator goal" : e.title;
				out.add(new Need(title, skill, need, e.key != null && e.key.equals(board.focus)));
			}
		}
		out.sort((a, b) -> a.focus != b.focus ? (a.focus ? -1 : 1) : Integer.compare(a.level, b.level));
		return out;
	}

	/** The skill's name as the levels spell it, matching however Navigator capitalised it; null when not asked about. */
	private static String canonical(Map<String, Integer> levels, String name)
	{
		if (name == null)
		{
			return null;
		}
		for (String k : levels.keySet())
		{
			if (k.equalsIgnoreCase(name))
			{
				return k;
			}
		}
		return null;
	}
}

package com.codex.pestcontrol.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumSet;
import java.util.List;
import java.util.Set;

/** How far the goal is: the points still needed, the games that takes and how long. */
public final class Outlook
{
	private final List<Reward> needed;
	private final List<Reward> owned;
	private final int cost;
	private final int points;
	private final int remaining;
	private final int games;
	private final double minutes;
	private final double perGame;
	private final boolean measured;
	private final Reward nextBuy;
	private final double minutesPerGame;

	private Outlook(List<Reward> needed, List<Reward> owned, int cost, int points, double perGame, double minutesPerGame, boolean measured)
	{
		this.needed = needed;
		this.owned = owned;
		this.cost = cost;
		this.points = points;
		this.perGame = perGame;
		this.measured = measured;
		this.remaining = Math.max(0, cost - Math.max(0, points));
		// Unread points are not zero points, so the games are only counted once they are read.
		this.games = points < 0 && !needed.isEmpty() ? -1 : remaining == 0 ? 0 : (int) Math.ceil(remaining / perGame);
		this.minutesPerGame = minutesPerGame;
		this.minutes = games < 0 ? -1 : games * minutesPerGame;
		List<Reward> best = bestSet(needed, Math.max(0, points));
		this.nextBuy = best.isEmpty() ? null : best.get(0);
	}

	/**
	 * The pieces that together spend the most of the points held, dearest first. Ties go to fewer
	 * pieces, then to the pieces earlier in the reward list. A goal has at most ten pieces, so every
	 * set is tried.
	 */
	static List<Reward> bestSet(List<Reward> pieces, int held)
	{
		List<Reward> sorted = new ArrayList<>(pieces);
		// Stable: pieces of the same cost keep the reward order.
		sorted.sort((a, b) -> Integer.compare(b.getCost(), a.getCost()));
		int n = Math.min(sorted.size(), 16);
		int bestMask = 0;
		int bestSum = 0;
		int bestCount = 0;
		for (int mask = 1; mask < 1 << n; mask++)
		{
			int sum = 0;
			for (int i = 0; i < n && sum <= held; i++)
			{
				if ((mask & 1 << i) != 0)
				{
					sum += sorted.get(i).getCost();
				}
			}
			if (sum > held || sum < bestSum)
			{
				continue;
			}
			int count = Integer.bitCount(mask);
			if (sum > bestSum || count < bestCount || count == bestCount && earlier(mask, bestMask))
			{
				bestMask = mask;
				bestSum = sum;
				bestCount = count;
			}
		}
		List<Reward> out = new ArrayList<>();
		for (int i = 0; i < n; i++)
		{
			if ((bestMask & 1 << i) != 0)
			{
				out.add(sorted.get(i));
			}
		}
		return out;
	}

	/** Whether set a holds the first piece, in order, that the two sets do not share. */
	private static boolean earlier(int a, int b)
	{
		int diff = a ^ b;
		return diff != 0 && (a & Integer.lowestOneBit(diff)) != 0;
	}

	/**
	 * @param points points held, or -1 when not yet seen
	 */
	public static Outlook of(Set<Reward> goal, Set<Reward> owned, int points, double perGame, double minutesPerGame, boolean measured)
	{
		List<Reward> needed = new ArrayList<>();
		List<Reward> have = new ArrayList<>();
		int cost = 0;
		for (Reward r : Reward.values())
		{
			if (!goal.contains(r))
			{
				continue;
			}
			if (owned.contains(r))
			{
				have.add(r);
			}
			else
			{
				needed.add(r);
				cost += r.getCost();
			}
		}
		return new Outlook(needed, have, cost, points, Math.max(0.5, perGame), minutesPerGame, measured);
	}

	public List<Reward> getNeeded()
	{
		return Collections.unmodifiableList(needed);
	}

	public List<Reward> getOwned()
	{
		return Collections.unmodifiableList(owned);
	}

	/** Points the pieces still needed cost. */
	public int getCost()
	{
		return cost;
	}

	public int getPoints()
	{
		return points;
	}

	public boolean isPointsKnown()
	{
		return points >= 0;
	}

	/** Whether the games left can be counted: not before the points held are read. */
	public boolean isGamesKnown()
	{
		return games >= 0;
	}

	public int getRemaining()
	{
		return remaining;
	}

	/** Games until the points cover the whole goal: 0 when they do, -1 before the points are read. */
	public int getGames()
	{
		return games;
	}

	public double getMinutes()
	{
		return minutes;
	}

	public double getPerGame()
	{
		return perGame;
	}

	public boolean isMeasured()
	{
		return measured;
	}

	/** How much of the cost is already held, from 0 to 1. */
	public double progress()
	{
		if (cost == 0)
		{
			return 1;
		}
		return Math.min(1, Math.max(0, points) / (double) cost);
	}

	public boolean isComplete()
	{
		return needed.isEmpty();
	}

	public boolean isAffordable()
	{
		return !needed.isEmpty() && remaining == 0;
	}

	/** The dearest piece of the set the points buy together, locked or not, or null. */
	public Reward getNextBuy()
	{
		return nextBuy;
	}

	/** Whether the cost is more than the Void Knights will hold at once. */
	public boolean isOverCap()
	{
		return cost > Logbook.POINTS_CAP;
	}

	/** One piece on the way to the goal: the points it takes counting the pieces before it, and when. */
	public static final class Milestone
	{
		private final Reward reward;
		private final int total;
		private final int games;
		private final double minutes;

		Milestone(Reward reward, int total, int games, double minutes)
		{
			this.reward = reward;
			this.total = total;
			this.games = games;
			this.minutes = minutes;
		}

		public Reward getReward()
		{
			return reward;
		}

		/** Points spent once this piece and every one before it are bought. */
		public int getTotal()
		{
			return total;
		}

		/** Games until it can be bought, 0 when it can be already, -1 before the points are read. */
		public int getGames()
		{
			return games;
		}

		public double getMinutes()
		{
			return minutes;
		}
	}

	/**
	 * The pieces still needed in the order to buy them. First the pieces the points held buy
	 * together, choosing the set that spends the most of them, so the Void Knights hold as few
	 * points as they can: 400 points toward a top and two helms buy both helms, not the top and
	 * 150 left over. The rest follow cheapest first, as each is yours soonest. Pieces in the given
	 * set (elite pieces still locked behind the diary) go last. Before the points are read no
	 * piece is timed: each one's games are -1.
	 */
	public List<Milestone> milestones(Set<Reward> last)
	{
		List<Reward> open = new ArrayList<>();
		List<Reward> later = new ArrayList<>();
		for (Reward r : needed)
		{
			(last != null && last.contains(r) ? later : open).add(r);
		}
		// Stable sorts keep the reward order between pieces of the same cost.
		open.sort((a, b) -> Integer.compare(a.getCost(), b.getCost()));
		later.sort((a, b) -> Integer.compare(a.getCost(), b.getCost()));
		int held = Math.max(0, points);
		List<Reward> order = new ArrayList<>(bestSet(open, held));
		open.removeAll(order);
		// Nothing left fits in what the set leaves, or the set would have taken it.
		order.addAll(open);
		order.addAll(later);
		List<Milestone> out = new ArrayList<>();
		int total = 0;
		for (Reward r : order)
		{
			total += r.getCost();
			int shortfall = Math.max(0, total - held);
			int g = !isPointsKnown() ? -1 : shortfall == 0 ? 0 : (int) Math.ceil(shortfall / perGame);
			out.add(new Milestone(r, total, g, g < 0 ? -1 : g * minutesPerGame));
		}
		return out;
	}

	/**
	 * The pieces the points held buy now, together: the set that spends the most of them, which
	 * the buy order starts with. With 412 points toward a top, a robe and a helm, that is the top
	 * alone, not each of the three that 412 would cover on its own; with 400 toward a top and two
	 * helms, it is the two helms. Pieces in {@code locked} (elite ones behind the diary) are never
	 * among them; unknown points buy nothing.
	 */
	public Set<Reward> buyableNow(Set<Reward> locked)
	{
		Set<Reward> out = EnumSet.noneOf(Reward.class);
		if (!isPointsKnown())
		{
			return out;
		}
		for (Milestone m : milestones(locked))
		{
			if (m.getGames() > 0)
			{
				break;
			}
			if (locked == null || !locked.contains(m.getReward()))
			{
				out.add(m.getReward());
			}
		}
		return out;
	}
}

package com.codex.pestcontrol.core;

import java.util.Locale;

/**
 * The four portals around the outpost, in the order the game numbers them: the status widgets,
 * the portal NPCs and the shield messages all count purple, blue, yellow, red.
 */
public enum Portal
{
	PURPLE("Purple", "west", "west gate", 0xB070E0),
	BLUE("Blue", "east", "east gate", 0x5AA0F0),
	YELLOW("Yellow", "south-east", "south gate", 0xE8C84A),
	RED("Red", "south-west", "south gate", 0xE05A4A);

	private final String title;
	private final String side;
	private final String gate;
	private final int rgb;

	Portal(String title, String side, String gate, int rgb)
	{
		this.title = title;
		this.side = side;
		this.gate = gate;
		this.rgb = rgb;
	}

	public String getTitle()
	{
		return title;
	}

	/** Where it stands from the Void Knight, such as "south-east". */
	public String getSide()
	{
		return side;
	}

	/** The outpost gate to leave by to reach it. */
	public String getGate()
	{
		return gate;
	}

	public int getRgb()
	{
		return rgb;
	}

	/** The portal a shield message names, such as "purple", or null. */
	public static Portal named(String colour)
	{
		if (colour == null)
		{
			return null;
		}
		String c = colour.trim().toUpperCase(Locale.ENGLISH);
		for (Portal p : values())
		{
			if (p.name().equals(c))
			{
				return p;
			}
		}
		return null;
	}
}

package com.codex.pestcontrol.core;

/**
 * The Void Knights' rewards that a goal can be made of, with their cost in commendation
 * points and every item that counts as already owning one (broken and ornamented copies too).
 * After the first id each piece lists its broken copy, its trouver-locked copy, the copy made with
 * the Shattered Relics void ornament kit and that one locked, then the locked copies broken and
 * mangled on death.
 */
public enum Reward
{
	TOP("Void knight top", "Top", 250, false, 8839, 20465, 24177, 26463, 27000, 33476, 33478),
	ROBE("Void knight robe", "Robe", 250, false, 8840, 20469, 24179, 26465, 27001, 33484, 33486),
	GLOVES("Void knight gloves", "Gloves", 150, false, 8842, 20475, 24182, 26467, 27002, 33492, 33494),
	MELEE_HELM("Void melee helm", "Melee helm", 200, false, 11665, 20481, 24185, 26477, 27007, 33464, 33466),
	RANGER_HELM("Void ranger helm", "Ranger helm", 200, false, 11664, 20479, 24184, 26475, 27006, 33472, 33474),
	MAGE_HELM("Void mage helm", "Mage helm", 200, false, 11663, 20477, 24183, 26473, 27005, 33468, 33470),
	ELITE_TOP("Elite void top", "Elite top", 200, true, 13072, 20467, 24178, 26469, 27003, 33480, 33482),
	ELITE_ROBE("Elite void robe", "Elite robe", 200, true, 13073, 20471, 24180, 26471, 27004, 33488, 33490),
	MACE("Void knight mace", "Mace", 250, false, 8841, 20473, 24181),
	SEAL("Void seal", "Seal", 10, false, 11666, 11667, 11668, 11669, 11670, 11671, 11672, 11673);

	private final String title;
	private final String shortTitle;
	private final int cost;
	private final boolean elite;
	private final int[] items;

	Reward(String title, String shortTitle, int cost, boolean elite, int... items)
	{
		this.title = title;
		this.shortTitle = shortTitle;
		this.cost = cost;
		this.elite = elite;
		this.items = items;
	}

	public String getTitle()
	{
		return title;
	}

	public String getShortTitle()
	{
		return shortTitle;
	}

	public int getCost()
	{
		return cost;
	}

	/** Elite pieces need the hard Western Provinces diary. */
	public boolean isElite()
	{
		return elite;
	}

	/** The item to draw for it. */
	public int getIcon()
	{
		return items[0];
	}

	public boolean isOwnedBy(int itemId)
	{
		for (int id : items)
		{
			if (id == itemId)
			{
				return true;
			}
		}
		return false;
	}

	/** Pieces worn as void equipment, which need level 42 combat skills and 22 Prayer. */
	public boolean isVoidGear()
	{
		return this != SEAL;
	}

	public static Reward named(String name)
	{
		for (Reward r : values())
		{
			if (r.name().equals(name))
			{
				return r;
			}
		}
		return null;
	}

	/**
	 * The reward a line of the Void Knights' reward shop offers, from its words or the item it
	 * draws, or null. Words are matched loosely ("Void Knight Mage Helm" is the mage helm), elite
	 * pieces first so "Elite void top" is never read as the plain top.
	 */
	public static Reward inShop(String text, int itemId)
	{
		if (itemId > 0)
		{
			for (Reward r : values())
			{
				if (r.isOwnedBy(itemId))
				{
					return r;
				}
			}
		}
		if (text == null || text.isEmpty())
		{
			return null;
		}
		String words = loose(text);
		if (words.isEmpty())
		{
			return null;
		}
		for (Reward r : SHOP_ORDER)
		{
			if (words.contains(loose(r.title)))
			{
				return r;
			}
		}
		return null;
	}

	private static final Reward[] SHOP_ORDER = {ELITE_TOP, ELITE_ROBE, TOP, ROBE, GLOVES, MELEE_HELM, RANGER_HELM, MAGE_HELM, MACE, SEAL};

	private static String loose(String text)
	{
		return (" " + text.replaceAll("<[^>]*>", " ").toLowerCase(java.util.Locale.ENGLISH).replaceAll("[^a-z]+", " ") + " ")
			.replace(" knight ", " ").replace(" knights ", " ").replaceAll(" +", " ").trim();
	}
}

package com.codex.pestcontrol.core;

import static com.codex.pestcontrol.core.Portal.BLUE;
import static com.codex.pestcontrol.core.Portal.PURPLE;
import static com.codex.pestcontrol.core.Portal.RED;
import static com.codex.pestcontrol.core.Portal.YELLOW;

/**
 * The orders in which portal shields drop. Every game follows one of these six, so once a
 * shield or two has dropped the rest of the game can be read ahead.
 */
public enum Rotation
{
	PBYR(PURPLE, BLUE, YELLOW, RED),
	PYBR(PURPLE, YELLOW, BLUE, RED),
	BRYP(BLUE, RED, YELLOW, PURPLE),
	BPRY(BLUE, PURPLE, RED, YELLOW),
	YRPB(YELLOW, RED, PURPLE, BLUE),
	YPRB(YELLOW, PURPLE, RED, BLUE);

	private final Portal[] order;

	Rotation(Portal... order)
	{
		this.order = order;
	}

	/** The portal whose shield drops at a step, counting from zero, or null past the last. */
	public Portal at(int step)
	{
		return step < 0 || step >= order.length ? null : order[step];
	}

	public Portal[] order()
	{
		return order.clone();
	}
}

package com.codex.pestcontrol.core;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.Map;

/**
 * Reads a saved value that may be damaged, keeping as much of it as can be read. A field of the
 * wrong type, or a number too big for its field, costs only that field; a damaged entry of a list
 * or map costs only that entry. A value that is not an object at all, or cannot be parsed, reads
 * as null.
 */
public final class Salvage
{
	private Salvage()
	{
	}

	/** @return what could be read, or null when nothing could */
	public static <T> T read(Gson gson, String json, Class<T> type)
	{
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}
		JsonElement root;
		try
		{
			root = gson.fromJson(json, JsonElement.class);
		}
		catch (RuntimeException | StackOverflowError e)
		{
			// Cut short, not JSON, or nested past what can be read: nothing is kept.
			return null;
		}
		if (root == null || !root.isJsonObject())
		{
			return null;
		}
		T whole = parse(gson, root, type);
		if (whole != null)
		{
			return whole;
		}
		JsonObject kept = new JsonObject();
		for (Map.Entry<String, JsonElement> field : root.getAsJsonObject().entrySet())
		{
			JsonElement value = field.getValue();
			if (fits(gson, field.getKey(), value, type))
			{
				kept.add(field.getKey(), value);
				continue;
			}
			JsonElement trimmed = trim(gson, field.getKey(), value, type);
			// A list where a map belongs trims to an empty list that still does not fit; then the
			// field is lost alone, not with everything else.
			if (trimmed != null && fits(gson, field.getKey(), trimmed, type))
			{
				kept.add(field.getKey(), trimmed);
			}
		}
		return parse(gson, kept, type);
	}

	/** A list or map field with only the entries that can be read, or null for any other field. */
	private static <T> JsonElement trim(Gson gson, String name, JsonElement value, Class<T> type)
	{
		if (value.isJsonArray())
		{
			JsonArray out = new JsonArray();
			for (JsonElement e : value.getAsJsonArray())
			{
				JsonArray one = new JsonArray();
				one.add(e);
				if (fits(gson, name, one, type))
				{
					out.add(e);
				}
			}
			return out;
		}
		if (value.isJsonObject())
		{
			JsonObject out = new JsonObject();
			for (Map.Entry<String, JsonElement> e : value.getAsJsonObject().entrySet())
			{
				JsonObject one = new JsonObject();
				one.add(e.getKey(), e.getValue());
				if (fits(gson, name, one, type))
				{
					out.add(e.getKey(), e.getValue());
				}
			}
			return out;
		}
		return null;
	}

	/**
	 * True when saving {@code kept}, read from {@code json}, in place of {@code json} would lose
	 * something {@code json} holds: a field or value this version does not know (one a newer
	 * version wrote), or one it had to mend or leave out. A field {@code json} lacks, as an older
	 * save does, loses nothing. A value that cannot be parsed at all loses everything.
	 */
	public static boolean wouldLose(Gson gson, String json, Object kept)
	{
		if (json == null || json.trim().isEmpty())
		{
			return false;
		}
		JsonElement was;
		try
		{
			was = gson.fromJson(json, JsonElement.class);
		}
		catch (RuntimeException | StackOverflowError e)
		{
			return true;
		}
		if (was == null || was.isJsonNull())
		{
			return false;
		}
		try
		{
			return kept == null || !covers(was, gson.toJsonTree(kept));
		}
		catch (StackOverflowError e)
		{
			return true;
		}
	}

	/** True when {@code now} holds everything {@code was} does: every field, list entry and value. */
	private static boolean covers(JsonElement was, JsonElement now)
	{
		if (was.isJsonNull())
		{
			// Gson leaves an empty field out.
			return true;
		}
		if (was.isJsonObject())
		{
			if (!now.isJsonObject())
			{
				return false;
			}
			JsonObject have = now.getAsJsonObject();
			for (Map.Entry<String, JsonElement> e : was.getAsJsonObject().entrySet())
			{
				JsonElement value = have.get(e.getKey());
				if (!e.getValue().isJsonNull() && (value == null || !covers(e.getValue(), value)))
				{
					return false;
				}
			}
			return true;
		}
		if (was.isJsonArray())
		{
			JsonArray a = was.getAsJsonArray();
			if (!now.isJsonArray() || now.getAsJsonArray().size() != a.size())
			{
				return false;
			}
			JsonArray b = now.getAsJsonArray();
			for (int i = 0; i < a.size(); i++)
			{
				if (!covers(a.get(i), b.get(i)))
				{
					return false;
				}
			}
			return true;
		}
		return was.equals(now);
	}

	private static <T> boolean fits(Gson gson, String name, JsonElement value, Class<T> type)
	{
		JsonObject one = new JsonObject();
		one.add(name, value);
		return parse(gson, one, type) != null;
	}

	private static <T> T parse(Gson gson, JsonElement json, Class<T> type)
	{
		try
		{
			return gson.fromJson(json, type);
		}
		catch (RuntimeException | StackOverflowError e)
		{
			return null;
		}
	}
}

package com.codex.pestcontrol.core;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;

/**
 * The bank as another Codex plugin last saw it, read from what that plugin saves in the RuneLite
 * profile. Only read, never written, and absent when neither plugin is installed.
 *
 * <p>Codex Bank Steward's {@code codexbanksteward/bankV1} is preferred: it holds every item with
 * its quantity and when it was seen,
 * {@code {"version":1,"savedAt":1760000000000,"items":{"995":1234567,"26950":1},"truncated":false}}.
 * Codex Gear Roadmap's {@code codexgearroadmap/bank} is the fallback, {@code {"items":[4151],"coins":N}}:
 * only the gear Roadmap knows, with no quantities (each counts as one) and no time.</p>
 */
public final class SharedBank
{
	public static final String STEWARD_GROUP = "codexbanksteward";
	public static final String STEWARD_KEY = "bankV1";
	public static final String ROADMAP_GROUP = "codexgearroadmap";
	public static final String ROADMAP_KEY = "bank";
	private static final int COINS = 995;
	/** Readers accept no more kinds of item than the Steward ever writes. */
	private static final int MAX_ITEMS = 2000;

	/** Where a shared bank came from. */
	public enum Source
	{
		/** Every item and its quantity. */
		BANK_STEWARD,
		/** Only the gear Gear Roadmap tracks, and coins. */
		GEAR_ROADMAP
	}

	private final Source source;
	private final Map<Integer, Long> items;
	private final long savedAt;
	private final boolean complete;

	private SharedBank(Source source, Map<Integer, Long> items, long savedAt, boolean complete)
	{
		this.source = source;
		this.items = Collections.unmodifiableMap(items);
		this.savedAt = savedAt;
		this.complete = complete;
	}

	/**
	 * The best bank on offer: Bank Steward's, else Gear Roadmap's, else null.
	 *
	 * @param steward what {@code codexbanksteward/bankV1} holds for this profile, or null
	 * @param roadmap what {@code codexgearroadmap/bank} holds for this profile, or null
	 */
	public static SharedBank read(Gson gson, String steward, String roadmap)
	{
		SharedBank bank = readSteward(gson, steward);
		return bank != null ? bank : readRoadmap(gson, roadmap);
	}

	static SharedBank readSteward(Gson gson, String json)
	{
		JsonObject root = object(gson, json);
		JsonElement list = root == null ? null : root.get("items");
		if (list == null || !list.isJsonObject())
		{
			return null;
		}
		Map<Integer, Long> items = new HashMap<>();
		for (Map.Entry<String, JsonElement> e : list.getAsJsonObject().entrySet())
		{
			Integer id = integer(e.getKey());
			Long qty = number(e.getValue());
			if (id != null && id > 0 && qty != null && qty > 0 && items.size() < MAX_ITEMS)
			{
				// No bank slot holds more than this; a larger count is damage, held to it.
				items.put(id, Math.min(qty, Integer.MAX_VALUE));
			}
		}
		Long savedAt = number(root.get("savedAt"));
		JsonElement truncated = root.get("truncated");
		boolean cut = truncated != null && truncated.isJsonPrimitive() && truncated.getAsJsonPrimitive().isBoolean()
			&& truncated.getAsBoolean();
		return new SharedBank(Source.BANK_STEWARD, items, savedAt == null ? 0 : Math.max(0, savedAt), !cut);
	}

	static SharedBank readRoadmap(Gson gson, String json)
	{
		JsonObject root = object(gson, json);
		JsonElement list = root == null ? null : root.get("items");
		if (list == null || !list.isJsonArray())
		{
			return null;
		}
		Map<Integer, Long> items = new HashMap<>();
		for (JsonElement e : list.getAsJsonArray())
		{
			Long id = number(e);
			if (id != null && id > 0 && id <= Integer.MAX_VALUE && items.size() < MAX_ITEMS)
			{
				items.put(id.intValue(), 1L);
			}
		}
		Long coins = number(root.get("coins"));
		if (coins != null && coins > 0)
		{
			items.put(COINS, coins);
		}
		return new SharedBank(Source.GEAR_ROADMAP, items, 0, false);
	}

	public Source getSource()
	{
		return source;
	}

	/** Item id to quantity; a Gear Roadmap bank counts each item it lists as one. */
	public Map<Integer, Long> getItems()
	{
		return items;
	}

	public Set<Integer> ids()
	{
		return items.keySet();
	}

	public long count(int itemId)
	{
		return items.getOrDefault(itemId, 0L);
	}

	/** When the bank was seen, in epoch milliseconds; 0 when the source does not say. */
	public long getSavedAt()
	{
		return savedAt;
	}

	/**
	 * Whether every item in the bank is here with its true quantity, so a missing item really is
	 * not in the bank. Only Bank Steward's snapshot is.
	 */
	public boolean isComplete()
	{
		return complete;
	}

	private static JsonObject object(Gson gson, String json)
	{
		if (json == null || json.trim().isEmpty())
		{
			return null;
		}
		try
		{
			JsonElement root = gson.fromJson(json, JsonElement.class);
			return root != null && root.isJsonObject() ? root.getAsJsonObject() : null;
		}
		catch (RuntimeException | StackOverflowError e)
		{
			// Cut short, not JSON, or garbage nested deeper than Gson reads.
			return null;
		}
	}

	private static Long number(JsonElement e)
	{
		if (e == null || !e.isJsonPrimitive() || !e.getAsJsonPrimitive().isNumber())
		{
			return null;
		}
		try
		{
			return e.getAsLong();
		}
		catch (NumberFormatException ex)
		{
			return null;
		}
	}

	private static Integer integer(String s)
	{
		try
		{
			return Integer.parseInt(s.trim());
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}
}

package com.codex.pestcontrol.core;

/**
 * How long shields take to drop, learned from your own games: the ticks from the start to the
 * first drop, and between each drop and the next. Saved inside the logbook.
 */
public class ShieldClock
{
	/** Gaps taken as one sample at least; others are missed messages or late starts. */
	static final int MIN_GAP = 5;
	static final int MAX_GAP = 600;
	/** Samples needed before a gap is trusted. */
	static final int TRUSTED = 2;

	private long[] sums = new long[4];
	private int[] counts = new int[4];

	/** Learns from one game's drop ticks, -1 for drops whose moment was not seen. */
	public void learn(java.util.List<Integer> drops)
	{
		repair();
		int previous = 0;
		for (int step = 0; step < drops.size() && step < 4; step++)
		{
			int at = drops.get(step);
			if (at < 0 || previous < 0)
			{
				previous = at;
				continue;
			}
			int gap = at - previous;
			if (gap >= MIN_GAP && gap <= MAX_GAP)
			{
				sums[step] += gap;
				counts[step]++;
			}
			previous = at;
		}
	}

	/** Ticks the gap before drop number step usually lasts, or -1 when not yet learned. */
	public int expected(int step)
	{
		repair();
		if (step < 0 || step >= 4 || counts[step] < TRUSTED)
		{
			return -1;
		}
		long gap = Math.round(sums[step] / (double) counts[step]);
		// Only a damaged save gives an average no single gap could.
		return gap < MIN_GAP || gap > MAX_GAP ? -1 : (int) gap;
	}

	public int samples(int step)
	{
		repair();
		return step < 0 || step >= 4 ? 0 : counts[step];
	}

	/** Fills in what a damaged save left out; a step with a count or sum below zero starts again. */
	void repair()
	{
		if (sums == null || sums.length != 4)
		{
			sums = new long[4];
		}
		if (counts == null || counts.length != 4)
		{
			counts = new int[4];
		}
		for (int i = 0; i < 4; i++)
		{
			if (sums[i] < 0 || counts[i] < 0)
			{
				sums[i] = 0;
				counts[i] = 0;
			}
		}
	}
}

package com.codex.pestcontrol.core;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * One sitting at the outpost: games played back to back, with no break longer than
 * {@link Logbook#BREAK_MS} between one ending and the next starting. Its rate counts the time in
 * the lander between games, which the record's "in games" rate leaves out, so it is what an hour
 * at Pest Control really pays.
 */
public final class Sitting
{
	private final List<GameRecord> games;
	private final boolean current;
	private final int won;
	private final int points;
	private final int unpaid;

	private Sitting(List<GameRecord> games, boolean current)
	{
		this.games = Collections.unmodifiableList(games);
		this.current = current;
		int w = 0;
		int p = 0;
		int u = 0;
		for (GameRecord g : games)
		{
			w += g.getResult() == GameRecord.Result.WON || g.getResult() == GameRecord.Result.NO_POINTS ? 1 : 0;
			p += g.getPoints();
			u += g.getResult() == GameRecord.Result.NO_POINTS ? 1 : 0;
		}
		won = w;
		points = p;
		unpaid = u;
	}

	/**
	 * The newest sitting in the games.
	 *
	 * @param games the games kept, oldest first
	 * @param now the time now, to tell a sitting still going from one that has ended
	 */
	public static Sitting latest(List<GameRecord> games, long now)
	{
		List<GameRecord> picked = new ArrayList<>();
		if (games != null)
		{
			for (int i = games.size() - 1; i >= 0; i--)
			{
				GameRecord g = games.get(i);
				if (!picked.isEmpty() && start(picked.get(0)) - g.getEnded() > Logbook.BREAK_MS)
				{
					break;
				}
				picked.add(0, g);
			}
		}
		boolean current = !picked.isEmpty() && now - picked.get(picked.size() - 1).getEnded() <= Logbook.BREAK_MS;
		return new Sitting(picked, current);
	}

	private static long start(GameRecord g)
	{
		return g.getEnded() - g.getSeconds() * 1000L;
	}

	public boolean isEmpty()
	{
		return games.isEmpty();
	}

	/** Whether the last game ended recently enough that the sitting is still going. */
	public boolean isCurrent()
	{
		return current;
	}

	public List<GameRecord> getGames()
	{
		return games;
	}

	/** Games won, with or without the damage for points. */
	public int getWon()
	{
		return won;
	}

	public int getPoints()
	{
		return points;
	}

	/** Games won without the 50 damage for points. */
	public int getUnpaid()
	{
		return unpaid;
	}

	public long getStartedAt()
	{
		return games.isEmpty() ? 0 : start(games.get(0));
	}

	/** From the first game starting to the last ending, the lander time between them included. */
	public long spanMs()
	{
		return games.isEmpty() ? 0 : Math.max(0, games.get(games.size() - 1).getEnded() - getStartedAt());
	}

	/**
	 * Points an hour over the sitting, or 0 before there are two games (one game has no lander time
	 * in it to count) or ten minutes, when the figure means little.
	 */
	public int pointsPerHour()
	{
		long span = spanMs();
		return games.size() < 2 || span < 10 * 60_000L ? 0 : (int) Math.round(points * 3_600_000.0 / span);
	}
}

package com.codex.pestcontrol.core;

import java.util.Locale;

/** How you fight, read from the weapon you hold: ranged and magic can work from behind cover. */
public enum Style
{
	MELEE,
	RANGED,
	MAGIC;

	private static final String[] RANGED_WORDS = {"bow", "dart", "knife", "thrownaxe", "chinchompa", "blowpipe", "ballista", "javelin", "eclipse atlatl"};
	private static final String[] MAGIC_WORDS = {"staff", "wand", "trident", "sceptre", "sanguinesti", "tumeken", "nightmare staff", "harmonised", "kodai"};

	/** The style a weapon's name suggests; melee for anything else or nothing held. */
	public static Style ofWeapon(String name)
	{
		if (name == null)
		{
			return MELEE;
		}
		String n = name.toLowerCase(Locale.ENGLISH);
		for (String w : RANGED_WORDS)
		{
			if (n.contains(w))
			{
				return RANGED;
			}
		}
		for (String w : MAGIC_WORDS)
		{
			if (n.contains(w))
			{
				return MAGIC;
			}
		}
		return MELEE;
	}

	public boolean isDistant()
	{
		return this != MELEE;
	}
}

package com.codex.pestcontrol.core;

import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * What the void worn now does for the weapon in hand. The set bonus needs all four slots: a helm,
 * the top (or the elite top), the robe (or the elite robe) and the gloves. The helm decides the
 * style it helps, so a mage helm worn with a bow gives nothing. Read before a game, when there is
 * still time to fix it.
 */
public final class VoidCheck
{
	public enum Kind
	{
		/** All four pieces on, the helm matching the weapon. */
		SET_ON,
		/** All four on, but the helm is for another style. */
		WRONG_HELM,
		/** Some pieces on, not all four: no bonus at all. */
		INCOMPLETE,
		/** None on, though a full set for this weapon is owned. */
		NOT_WORN
	}

	private final Kind kind;
	private final String headline;
	private final String detail;

	private VoidCheck(Kind kind, String headline, String detail)
	{
		this.kind = kind;
		this.headline = headline;
		this.detail = detail;
	}

	public Kind getKind()
	{
		return kind;
	}

	public String getHeadline()
	{
		return headline;
	}

	public String getDetail()
	{
		return detail;
	}

	/** Worth raising on the plaque: the void worn gives no bonus as it stands. */
	public boolean isWarning()
	{
		return kind == Kind.WRONG_HELM || kind == Kind.INCOMPLETE;
	}

	/** The helm that helps a style. */
	public static Reward helmFor(Style style)
	{
		switch (style)
		{
			case RANGED:
				return Reward.RANGER_HELM;
			case MAGIC:
				return Reward.MAGE_HELM;
			default:
				return Reward.MELEE_HELM;
		}
	}

	/**
	 * @param worn the rewards worn now
	 * @param style the style of the weapon in hand
	 * @param owned every reward owned, in the bank or carried
	 * @return what to say, or null when there is nothing to say (no void worn and no full set owned)
	 */
	public static VoidCheck of(Set<Reward> worn, Style style, Set<Reward> owned)
	{
		Reward helm = null;
		for (Reward h : EnumSet.of(Reward.MELEE_HELM, Reward.RANGER_HELM, Reward.MAGE_HELM))
		{
			if (worn.contains(h))
			{
				helm = h;
			}
		}
		boolean top = worn.contains(Reward.TOP) || worn.contains(Reward.ELITE_TOP);
		boolean robe = worn.contains(Reward.ROBE) || worn.contains(Reward.ELITE_ROBE);
		boolean gloves = worn.contains(Reward.GLOVES);
		boolean elite = worn.contains(Reward.ELITE_TOP) && worn.contains(Reward.ELITE_ROBE);
		Reward right = helmFor(style);
		String styleName = style.name().toLowerCase(Locale.ENGLISH);
		if (helm == null && !top && !robe && !gloves)
		{
			boolean hasSet = owned.contains(right) && (owned.contains(Reward.TOP) || owned.contains(Reward.ELITE_TOP))
				&& (owned.contains(Reward.ROBE) || owned.contains(Reward.ELITE_ROBE)) && owned.contains(Reward.GLOVES);
			return hasSet ? new VoidCheck(Kind.NOT_WORN, "Your void is not on",
				"You own a full set with the " + lower(right) + ": wear it for the " + styleName + " set bonus") : null;
		}
		if (helm == null || !top || !robe || !gloves)
		{
			List<String> missing = new ArrayList<>();
			if (helm == null)
			{
				missing.add(lower(right));
			}
			if (!top)
			{
				missing.add("top");
			}
			if (!robe)
			{
				missing.add("robe");
			}
			if (!gloves)
			{
				missing.add("gloves");
			}
			boolean ownsRest = true;
			if (helm == null && !owned.contains(right) || !top && !owned.contains(Reward.TOP) && !owned.contains(Reward.ELITE_TOP)
				|| !robe && !owned.contains(Reward.ROBE) && !owned.contains(Reward.ELITE_ROBE) || !gloves && !owned.contains(Reward.GLOVES))
			{
				ownsRest = false;
			}
			return new VoidCheck(Kind.INCOMPLETE, "Void set incomplete", "No " + join(missing) + " on, so no set bonus at all"
				+ (ownsRest ? ". You own the rest" : ""));
		}
		if (helm != right)
		{
			return new VoidCheck(Kind.WRONG_HELM, capital(lower(helm)) + " on a " + styleName + " weapon",
				owned.contains(right) ? "Swap to your " + lower(right) + " for the set bonus"
					: "Only the " + lower(right) + " helps a " + styleName + " weapon: " + right.getCost() + " points");
		}
		return new VoidCheck(Kind.SET_ON, elite ? "Elite void on" : "Void set on", capital(styleName) + " set bonus for this game");
	}

	/** "mage helm" from "Mage helm". */
	private static String lower(Reward r)
	{
		return r.getShortTitle().toLowerCase(Locale.ENGLISH);
	}

	private static String capital(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}

	/** "top", "top or robe", "top, robe or gloves". */
	private static String join(List<String> parts)
	{
		StringBuilder out = new StringBuilder();
		for (int i = 0; i < parts.size(); i++)
		{
			out.append(i == 0 ? "" : i == parts.size() - 1 ? " or " : ", ").append(parts.get(i));
		}
		return out.toString();
	}
}

