package com.codex.pestcontrol.overlay;

import com.codex.pestcontrol.ui.Sigil;
import com.codex.pestcontrol.ui.Theme;
import com.codex.pestcontrol.ui.Ui;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A gilt plaque in the game view: in a game, what to work next in the portal's colour, why,
 * and your damage toward points; at the outpost, your points toward the goal. It draws what
 * the plugin hands it.
 */
public class PilotPlaque extends Overlay
{
	private static final int PAD = 8;
	private static final int ICON = 22;
	private static final int MIN_WIDTH = 150;
	/** The widest a line of the detail runs before it wraps. */
	private static final int MAX_TEXT = 230;

	private volatile Shown shown;

	/** One plaque's worth of text. */
	public static final class Shown
	{
		final String kicker;
		final String headline;
		final Color color;
		final String detail;
		final String foot;
		final Color footColor;
		/** The layout, worked out on the first frame this is shown and kept, so a frame measures and allocates nothing. */
		private java.util.List<String> lines;
		private int width;
		private int height;
		private RoundRectangle2D shape;
		private GradientPaint fill;
		private GradientPaint edge;

		/**
		 * @param kicker the small capitals above, such as "WORK NEXT"
		 * @param foot a last line, such as the damage dealt, or null
		 */
		public Shown(String kicker, String headline, Color color, String detail, String foot, Color footColor)
		{
			this.kicker = kicker;
			this.headline = headline;
			this.color = color;
			this.detail = detail;
			this.foot = foot;
			this.footColor = footColor;
		}
	}

	public PilotPlaque()
	{
		setPosition(OverlayPosition.TOP_CENTER);
	}

	/** @param shown what to draw, or null to hide the plaque */
	public void show(Shown shown)
	{
		this.shown = shown;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Shown s = shown;
		if (s == null)
		{
			return null;
		}
		return paint(g, s);
	}

	/** Draws a plaque at the origin; previews use the same drawing. */
	public static Dimension paint(Graphics2D g, Shown s)
	{
		Theme.smooth(g);
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();

		if (s.lines == null)
		{
			layout(s, bold, small);
		}
		java.util.List<String> detail = s.lines;
		int width = s.width;
		int height = s.height;
		g.setPaint(s.fill);
		g.fill(s.shape);
		Shape clip = g.getClip();
		g.clip(s.shape);
		g.setPaint(s.edge);
		g.fillRect(0, 0, 3, height);
		g.setClip(clip);
		g.setColor(RIM);
		g.draw(s.shape);
		g.setColor(SHINE);
		g.drawLine(8, 1, width - 8, 1);

		g.drawImage(MARK, PAD + 2, PAD + 2, null);
		int x = PAD + ICON + 10;
		int y = PAD + small.getAscent();
		g.setFont(Theme.small());
		Ui.shadowed(g, s.kicker, x, y, Theme.TEXT_MUTED);
		y += small.getDescent() + bold.getAscent() + 1;
		g.setFont(Theme.title());
		Ui.shadowed(g, s.headline, x, y, s.color);
		g.setFont(Theme.small());
		for (String line : detail)
		{
			y += small.getHeight();
			Ui.shadowed(g, line, x, y, Theme.TEXT);
		}
		if (s.foot != null)
		{
			y += small.getHeight();
			Ui.shadowed(g, s.foot, x, y, s.footColor == null ? Theme.TEXT_MUTED : s.footColor);
		}
		return new Dimension(width, height);
	}

	private static final Color RIM = Theme.alpha(Theme.GOLD, 150);
	private static final Color SHINE = Theme.alpha(Color.WHITE, 14);
	/** The mark, drawn once. */
	private static final BufferedImage MARK = Sigil.icon(ICON);

	private static void layout(Shown s, FontMetrics bold, FontMetrics small)
	{
		java.util.List<String> detail = wrap(s.detail, small, MAX_TEXT);
		int textW = Math.max(bold.stringWidth(s.headline), small.stringWidth(s.kicker));
		for (String line : detail)
		{
			textW = Math.max(textW, small.stringWidth(line));
		}
		if (s.foot != null)
		{
			textW = Math.max(textW, small.stringWidth(s.foot));
		}
		s.width = Math.max(MIN_WIDTH, PAD + ICON + 8 + textW + PAD + 2);
		int lines = 2 + detail.size() + (s.foot != null ? 1 : 0);
		s.height = PAD + small.getHeight() + bold.getHeight() + (lines - 2) * small.getHeight() + PAD - 2;
		s.shape = new RoundRectangle2D.Float(0.5f, 0.5f, s.width - 1, s.height - 1, 12, 12);
		s.fill = new GradientPaint(0, 0, Theme.alpha(Theme.CARD_TOP, 236), 0, s.height, Theme.alpha(Theme.INK_DEEP, 236));
		s.edge = new GradientPaint(0, 0, s.color, 0, s.height, Theme.alpha(s.color, 70));
		s.lines = detail;
	}

	/** Breaks text into lines no wider than the width, at spaces. */
	static java.util.List<String> wrap(String text, FontMetrics fm, int width)
	{
		java.util.List<String> lines = new java.util.ArrayList<>();
		if (text == null || text.isEmpty())
		{
			return lines;
		}
		StringBuilder line = new StringBuilder();
		for (String word : text.split(" "))
		{
			String next = line.length() == 0 ? word : line + " " + word;
			if (line.length() > 0 && fm.stringWidth(next) > width)
			{
				lines.add(line.toString());
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(next);
			}
		}
		lines.add(line.toString());
		return lines;
	}
}

package com.codex.pestcontrol.overlay;

import com.codex.pestcontrol.ui.Theme;
import com.codex.pestcontrol.ui.Ui;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.NPC;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Marks the portal to work next in the world: an outline in its colour, a gilt ring on the
 * ground and a word over it. Portals that might be next get a faint outline only.
 */
public class PortalMarker extends Overlay
{
	private final ModelOutlineRenderer outlines;
	private volatile Mark mark;

	/** What to mark. */
	public static final class Mark
	{
		final NPC target;
		final Color color;
		final String label;
		final List<NPC> maybe;
		final List<Color> maybeColors;

		public Mark(NPC target, Color color, String label, List<NPC> maybe, List<Color> maybeColors)
		{
			this.target = target;
			this.color = color;
			this.label = label;
			this.maybe = maybe == null ? Collections.emptyList() : maybe;
			this.maybeColors = maybeColors == null ? Collections.emptyList() : maybeColors;
		}
	}

	@Inject
	PortalMarker(ModelOutlineRenderer outlines)
	{
		this.outlines = outlines;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	/** @param mark what to mark, or null to mark nothing */
	public void show(Mark mark)
	{
		this.mark = mark;
	}

	Mark current()
	{
		return mark;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Mark m = mark;
		if (m == null)
		{
			return null;
		}
		for (int i = 0; i < m.maybe.size(); i++)
		{
			NPC npc = m.maybe.get(i);
			outlines.drawOutline(npc, 2, Theme.alpha(m.maybeColors.get(i), 110), 2);
		}
		NPC npc = m.target;
		if (npc == null)
		{
			return null;
		}
		outlines.drawOutline(npc, 3, m.color, 3);
		Polygon tile = npc.getCanvasTilePoly();
		if (tile != null)
		{
			g.setStroke(new BasicStroke(2f));
			g.setColor(Theme.alpha(Theme.GOLD_BRIGHT, 200));
			g.draw(tile);
			g.setColor(Theme.alpha(m.color, 40));
			g.fill(tile);
		}
		if (m.label != null)
		{
			g.setFont(Theme.title());
			Point at = npc.getCanvasTextLocation(g, m.label, npc.getLogicalHeight() + 40);
			if (at != null)
			{
				Ui.shadowed(g, m.label, at.getX(), at.getY(), Theme.GOLD_BRIGHT);
			}
		}
		return null;
	}
}

package com.codex.pestcontrol.overlay;

import com.codex.pestcontrol.core.Reward;
import com.codex.pestcontrol.ui.Theme;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.Collections;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Lights your goal in the Void Knights' reward shop: teal round the pieces your points buy now,
 * a quiet gold line round the rest of the goal. Lines it cannot read are left alone.
 */
public class RewardShopGuide extends Overlay
{
	/** Deeper than any line of the shop nests its words. */
	private static final int MAX_DEPTH = 4;

	private final Client client;
	private volatile Guide guide;

	/** What to light. */
	public static final class Guide
	{
		final Set<Reward> buy;
		final Set<Reward> goal;

		/**
		 * @param buy the goal's pieces the points buy now
		 * @param goal the goal's pieces still to buy
		 */
		public Guide(Set<Reward> buy, Set<Reward> goal)
		{
			this.buy = buy == null || buy.isEmpty() ? Collections.emptySet() : EnumSet.copyOf(buy);
			this.goal = goal == null || goal.isEmpty() ? Collections.emptySet() : EnumSet.copyOf(goal);
		}
	}

	@Inject
	RewardShopGuide(Client client)
	{
		this.client = client;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/** @param guide what to light, or null to light nothing */
	public void show(Guide guide)
	{
		this.guide = guide;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		Guide gd = guide;
		if (gd == null || gd.goal.isEmpty())
		{
			return null;
		}
		Widget options = client.getWidget(InterfaceID.PestRewardshop.OPTIONS);
		if (options == null || options.isHidden())
		{
			return null;
		}
		Map<Reward, Rectangle> lines = lines(options);
		if (lines.isEmpty())
		{
			return null;
		}
		Widget frame = client.getWidget(InterfaceID.PestRewardshop.OPTIONS_CONTAINER);
		Shape clip = g.getClip();
		if (frame != null && !frame.isHidden())
		{
			g.clip(frame.getBounds());
		}
		Theme.smooth(g);
		for (Map.Entry<Reward, Rectangle> e : lines.entrySet())
		{
			Reward r = e.getKey();
			if (!gd.goal.contains(r))
			{
				continue;
			}
			paint(g, e.getValue(), gd.buy.contains(r));
		}
		g.setClip(clip);
		return null;
	}

	/** Each reward's line in the shop: its words and its picture together. */
	static Map<Reward, Rectangle> lines(Widget options)
	{
		Map<Reward, Rectangle> lines = new EnumMap<>(Reward.class);
		find(options, lines, 0);
		return lines;
	}

	private static void find(Widget w, Map<Reward, Rectangle> lines, int depth)
	{
		if (w == null || w.isHidden() || depth > MAX_DEPTH)
		{
			return;
		}
		Reward r = Reward.inShop(w.getText(), w.getItemId());
		Rectangle b = w.getBounds();
		if (r != null && b != null && b.width > 0 && b.height > 0)
		{
			Rectangle had = lines.get(r);
			lines.put(r, had == null ? new Rectangle(b) : had.union(b));
		}
		for (Widget[] kids : new Widget[][]{w.getDynamicChildren(), w.getStaticChildren(), w.getNestedChildren()})
		{
			if (kids != null)
			{
				for (Widget k : kids)
				{
					find(k, lines, depth + 1);
				}
			}
		}
	}

	/** Draws one lit line of the shop; previews use the same drawing. */
	public static void paint(Graphics2D g, Rectangle line, boolean buy)
	{
		Color c = buy ? Theme.TEAL : Theme.GOLD;
		Rectangle r = new Rectangle(line.x - 2, line.y - 1, line.width + 4, line.height + 2);
		g.setColor(Theme.alpha(c, buy ? 46 : 22));
		g.fillRoundRect(r.x, r.y, r.width, r.height, 6, 6);
		g.setStroke(buy ? new BasicStroke(1.6f) : new BasicStroke(1f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 1f, new float[]{3f, 3f}, 0f));
		g.setColor(Theme.alpha(c, buy ? 230 : 170));
		g.drawRoundRect(r.x, r.y, r.width, r.height, 6, 6);

		String tag = buy ? "BUY" : "GOAL";
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		int w = fm.stringWidth(tag) + 8;
		int h = fm.getAscent() + 2;
		int x = r.x + r.width - w - 2;
		int y = r.y + 2;
		g.setColor(Theme.alpha(Theme.INK_DEEP, 220));
		g.fillRoundRect(x, y, w, h, 5, 5);
		g.setColor(c);
		g.drawRoundRect(x, y, w, h, 5, 5);
		g.drawString(tag, x + 4, y + fm.getAscent());
	}
}

