package com.codex.pestcontrol.ui;

import java.awt.Component;
import javax.swing.Timer;

/** Eases a value toward its target on the Swing thread so rings and bars fill instead of jumping. */
final class Animator
{
	private static final int FRAME_MS = 16;
	private static final double EASE = 0.18;

	private final Component owner;
	private final Timer timer;
	private double value;
	private double target;

	Animator(Component owner)
	{
		this.owner = owner;
		this.timer = new Timer(FRAME_MS, e -> step());
	}

	double get()
	{
		return value;
	}

	void set(double newTarget, boolean animate)
	{
		target = newTarget;
		if (!animate || !owner.isShowing())
		{
			value = newTarget;
			timer.stop();
			owner.repaint();
			return;
		}
		if (!timer.isRunning())
		{
			timer.start();
		}
	}

	private void step()
	{
		value += (target - value) * EASE;
		if (Math.abs(target - value) < 0.002 || !owner.isShowing())
		{
			value = target;
			timer.stop();
		}
		owner.repaint();
	}
}

package com.codex.pestcontrol.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.LayoutManager;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;

/**
 * A rounded, softly lit surface. Optionally clickable, with a hover lift and an
 * accent stripe down the left edge.
 */
public class Card extends JPanel
{
	private Color accent;
	private boolean hover;
	private boolean highlighted;
	private Runnable onClick;

	public Card(LayoutManager layout)
	{
		super(layout);
		setOpaque(false);
		setBorder(new EmptyBorder(8, 10, 8, 10));
	}

	public Card accent(Color color)
	{
		accent = color;
		repaint();
		return this;
	}

	/** A brighter rim for the card that matters most on screen. */
	public Card highlighted(boolean value)
	{
		highlighted = value;
		repaint();
		return this;
	}

	public Card onClick(Runnable action)
	{
		onClick = action;
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		MouseAdapter adapter = new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				// Children forward their events here, so only clear hover when the pointer has really left.
				if (!contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					hover = false;
					repaint();
				}
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e) && onClick != null
					&& contains(SwingUtilities.convertPoint(e.getComponent(), e.getPoint(), Card.this)))
				{
					onClick.run();
				}
			}
		};
		addMouseListener(adapter);
		Ui.forwardMouse(this, adapter);
		return this;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);

		Color top = hover ? Theme.CARD_HOVER : Theme.CARD_TOP;
		Color bottom = hover ? Theme.mix(Theme.CARD_HOVER, Theme.CARD, 0.5) : Theme.CARD;
		g.setPaint(new GradientPaint(0, 0, top, 0, h, bottom));
		g.fill(shape);

		if (accent != null)
		{
			g.setClip(shape);
			g.setPaint(new GradientPaint(0, 0, accent, 0, h, Theme.alpha(accent, 90)));
			g.fillRect(0, 0, 3, h);
			g.setClip(null);
		}

		Color rim = highlighted ? Theme.alpha(Theme.GOLD, 150) : hover ? Theme.alpha(Theme.GOLD, 90) : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.draw(shape);

		// A one pixel sheen along the top edge, like light on vellum.
		g.setColor(Theme.alpha(Color.WHITE, hover ? 22 : 12));
		g.drawLine(Theme.RADIUS / 2, 1, w - Theme.RADIUS / 2, 1);
		g.dispose();
		super.paintComponent(graphics);
	}
}

package com.codex.pestcontrol.ui;

import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;
import javax.swing.Timer;

/** A gilt-edged button; the primary style is filled, the quiet style is just an outline. */
public class CodexButton extends JComponent
{
	private String text;
	private final String label;
	private final boolean primary;
	private Runnable action;
	private Timer restore;
	private boolean hover;
	private boolean pressed;

	public CodexButton(String text, boolean primary, Runnable action)
	{
		this.text = text;
		this.label = text;
		this.primary = primary;
		this.action = action;
		setFont(Theme.small());
		setOpaque(false);
		setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		FontMetrics fm = getFontMetrics(getFont());
		Dimension d = new Dimension(fm.stringWidth(text) + 20, 22);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseEntered(MouseEvent e)
			{
				hover = true;
				repaint();
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				hover = false;
				pressed = false;
				repaint();
			}

			@Override
			public void mousePressed(MouseEvent e)
			{
				pressed = true;
				repaint();
			}

			@Override
			public void mouseReleased(MouseEvent e)
			{
				boolean fire = pressed && contains(e.getPoint());
				pressed = false;
				repaint();
				if (fire && CodexButton.this.action != null)
				{
					CodexButton.this.action.run();
				}
			}
		});
	}

	public void setAction(Runnable action)
	{
		this.action = action;
	}

	/** Shows a short confirmation in place of the label for a moment, such as "Copied". */
	public void flash(String message)
	{
		text = message;
		FontMetrics fm = getFontMetrics(getFont());
		int w = Math.max(fm.stringWidth(label), fm.stringWidth(message)) + 20;
		Dimension d = new Dimension(w, 22);
		setPreferredSize(d);
		setMinimumSize(d);
		setMaximumSize(d);
		revalidate();
		repaint();
		if (restore != null)
		{
			restore.stop();
		}
		restore = new Timer(1600, e ->
		{
			text = label;
			repaint();
		});
		restore.setRepeats(false);
		restore.start();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		int dy = pressed ? 1 : 0;
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f + dy, w - 1, h - 2, 8, 8);
		Color text;
		if (primary)
		{
			Color top = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
			g.setPaint(new GradientPaint(0, 0, top, 0, h, Theme.GOLD_DIM));
			g.fill(shape);
			text = Theme.INK_DEEP;
		}
		else
		{
			g.setColor(hover ? Theme.alpha(Theme.GOLD, 40) : Theme.alpha(Theme.GOLD, 14));
			g.fill(shape);
			text = hover ? Theme.GOLD_BRIGHT : Theme.GOLD;
		}
		g.setColor(Theme.alpha(Theme.GOLD, primary ? 220 : 140));
		g.draw(shape);
		g.setFont(getFont());
		FontMetrics fm = g.getFontMetrics();
		g.setColor(text);
		g.drawString(this.text, (w - fm.stringWidth(this.text)) / 2, (h + fm.getAscent()) / 2 - 2 + dy);
		g.dispose();
	}
}

package com.codex.pestcontrol.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/**
 * The crest at the top of the panel: the Pilot's medallion, the figure that matters most
 * right now in large gilt numerals (points, or a portal's health in a game), and a status line.
 */
public class Crest extends JComponent
{
	private static final int HEIGHT = 104;

	private final Animator count = new Animator(this);
	private String heading = "PEST CONTROL";
	private String status = "Log in to plan your points";
	private String shortStatus;
	private Color statusColor = Theme.TEXT_MUTED;
	private boolean known;
	private String unit = "";
	private Color figureTint = Theme.GOLD;

	public Crest()
	{
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setMinimumSize(new Dimension(10, HEIGHT));
	}

	/**
	 * @param value the figure, or null when not known
	 * @param unit the small word after the figure, such as "points"
	 * @param status the line under the figure
	 * @param shortStatus a shorter line for when the status does not fit, or null
	 */
	public void update(String heading, Integer value, String unit, String status, String shortStatus, Color statusColor, Color tint)
	{
		this.heading = heading;
		this.status = status;
		this.shortStatus = shortStatus;
		this.statusColor = statusColor;
		this.known = value != null;
		this.unit = unit == null ? "" : unit;
		this.figureTint = tint;
		if (value != null)
		{
			count.set(value, count.get() > 0);
		}
		repaint();
	}

	/**
	 * Draws text at twice the size of the game's bold font by doubling every pixel, the way the
	 * game itself draws large numbers, so the figures stay crisp instead of being re-rasterised.
	 *
	 * @return the width drawn
	 */
	static int paintLarge(Graphics2D g, String text, int x, int y, Color tint)
	{
		Font font = Theme.title();
		FontMetrics fm = g.getFontMetrics(font);
		int w = Math.max(1, fm.stringWidth(text) + 1);
		int h = fm.getHeight() + 1;
		BufferedImage small = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
		Graphics2D sg = small.createGraphics();
		sg.setFont(font);
		sg.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		int base = fm.getAscent();
		sg.setColor(Color.BLACK);
		sg.drawString(text, 1, base + 1);
		sg.setPaint(new GradientPaint(0, base - fm.getAscent() + 3, Theme.mix(tint, Color.WHITE, 0.35), 0, base, tint));
		sg.drawString(text, 0, base);
		sg.dispose();
		Graphics2D lg = (Graphics2D) g.create();
		lg.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_NEAREST_NEIGHBOR);
		lg.drawImage(small, x, y - 2 * fm.getAscent() + 22, w * 2, h * 2, null);
		lg.dispose();
		return w * 2;
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK, Theme.GOLD_DIM, 0.22), 0, h, Theme.INK));
		g.fillRect(0, 0, w, h);

		// The medallion: a gilt ring with the mark inside, lit from above.
		int mx = 10;
		int my = 14;
		int md = 54;
		g.setPaint(new RadialGradientPaint(mx + md / 2f, my + md / 3f, md * 0.7f, new float[]{0, 1},
			new Color[]{Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.35), Theme.INK_DEEP}));
		g.fill(new Ellipse2D.Float(mx, my, md, md));
		g.setStroke(new BasicStroke(2f));
		g.setPaint(new GradientPaint(mx, my, Theme.GOLD_BRIGHT, mx, my + md, Theme.GOLD_DIM));
		g.draw(new Ellipse2D.Float(mx + 1, my + 1, md - 2, md - 2));
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.alpha(Theme.GOLD, 70));
		g.draw(new Ellipse2D.Float(mx + 5, my + 5, md - 10, md - 10));
		Sigil.paint(g, mx + 11, my + 11, md - 22);

		int tx = mx + md + 12;
		int room = w - tx - 8;
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(Ui.clip(heading, small, room), tx, 22);

		int top = 27;
		int cy = top + 50;
		if (!known)
		{
			// No points read yet: what to do takes the figure's place rather than a lone dash.
			String line = shortStatus != null && g.getFontMetrics(Theme.body()).stringWidth(status) > room ? shortStatus : status;
			g.setFont(Theme.body());
			Ui.shadowed(g, Ui.clip(line == null ? "" : line, g.getFontMetrics(), room), tx, top + 18, Theme.mix(Theme.TEXT_MUTED, Theme.GOLD, 0.45));
			g.setFont(Theme.small());
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Ui.clip("Commendation points", small, room), tx, top + 34);
		}
		else
		{
			int figureW = paintLarge(g, Format.number(Math.round(count.get())), tx, top, figureTint);
			if (!unit.isEmpty())
			{
				g.setFont(Theme.small());
				g.setColor(Theme.GOLD_DIM);
				g.drawString(Ui.clip(unit, small, Math.max(0, room - figureW - 3)), tx + figureW + 3, top + 18);
			}
		}
		g.setFont(Theme.small());
		if (status != null && known)
		{
			String line = shortStatus != null && small.stringWidth(status) > room ? shortStatus : status;
			Ui.shadowed(g, Ui.clip(line, small, room), tx, cy, statusColor);
		}

		// The gilt rule under the crest, with a diamond at its middle.
		int y = h - 2;
		g.setPaint(new GradientPaint(0, 0, Theme.alpha(Theme.GOLD, 0), w / 2f, 0, Theme.alpha(Theme.GOLD, 150), true));
		g.drawLine(0, y, w, y);
		Path2D diamond = new Path2D.Float();
		diamond.moveTo(w / 2f, y - 3);
		diamond.lineTo(w / 2f + 3, y);
		diamond.lineTo(w / 2f, y + 3);
		diamond.lineTo(w / 2f - 3, y);
		diamond.closePath();
		g.setColor(Theme.GOLD);
		g.fill(diamond);
		g.dispose();
	}
}

package com.codex.pestcontrol.ui;

import com.codex.pestcontrol.core.Battle;
import com.codex.pestcontrol.core.GameRecord;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.util.List;
import javax.swing.JComponent;

/**
 * Your damage in each recent game as a row of bars, oldest on the left, coloured by how the game
 * ended, against the dashed line at the 50 damage a game needs for points. A bar short of the
 * line is a game that gave nothing for your time.
 */
class DamageChart extends JComponent
{
	private static final int HEIGHT = 64;

	private final List<GameRecord> games;

	DamageChart(List<GameRecord> games)
	{
		this.games = games;
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		int w = getWidth();
		int h = getHeight();
		int most = Battle.DAMAGE_FOR_POINTS * 2;
		for (GameRecord game : games)
		{
			most = Math.max(most, game.getDamage());
		}
		int floor = h - 1;
		int top = fm.getHeight() + 3;
		int span = floor - top;
		g.setColor(Theme.alpha(Theme.GOLD, 40));
		g.fillRect(0, floor, w, 1);

		int n = Math.max(1, games.size());
		int gap = 2;
		int slot = Math.max(3, Math.min(12, (w + gap) / n - gap));
		int x = 0;
		for (GameRecord game : games)
		{
			int bh = Math.max(2, (int) Math.round(span * Math.min(game.getDamage(), most) / (double) most));
			Color c = game.getDamage() < Battle.DAMAGE_FOR_POINTS ? Theme.EMBER : GameRow.color(game.getResult());
			g.setPaint(new GradientPaint(0, floor - bh, c, 0, floor, Theme.mix(c, Theme.INK, 0.6)));
			g.fillRoundRect(x, floor - bh, slot, bh, 3, 3);
			x += slot + gap;
		}

		int line = floor - (int) Math.round(span * Battle.DAMAGE_FOR_POINTS / (double) most);
		g.setStroke(new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 1f, new float[]{3, 3}, 0));
		g.setColor(Theme.alpha(Theme.TEXT, 150));
		g.drawLine(0, line, w, line);
		// The line's key sits in the top corner, clear of the bars.
		String label = Battle.DAMAGE_FOR_POINTS + " for points";
		int lx = w - fm.stringWidth(label);
		g.drawLine(lx - 16, fm.getAscent() / 2 + 1, lx - 4, fm.getAscent() / 2 + 1);
		g.setStroke(new BasicStroke(1f));
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(label, lx, fm.getAscent());
		String peak = String.valueOf(most);
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(peak, 0, fm.getAscent());
		g.dispose();
	}
}

package com.codex.pestcontrol.ui;

import java.text.NumberFormat;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

/** Numbers and times written the way the panel shows them. */
public final class Format
{
	private Format()
	{
	}

	public static String number(long n)
	{
		return NumberFormat.getIntegerInstance(Locale.ENGLISH).format(n);
	}

	/** "45s", "3m 20s" for a game's length. */
	public static String clock(int seconds)
	{
		if (seconds < 60)
		{
			return seconds + "s";
		}
		return seconds / 60 + "m " + String.format(Locale.ENGLISH, "%02ds", seconds % 60);
	}

	/** "35m", "2.9h", "14h", "3d" for how long a goal takes, short enough for a tile. */
	public static String span(double minutes)
	{
		long m = Math.round(minutes);
		if (m < 60)
		{
			return m + "m";
		}
		double h = minutes / 60;
		if (h < 10)
		{
			return String.format(Locale.ENGLISH, "%.1fh", h);
		}
		if (h < 48)
		{
			return Math.round(h) + "h";
		}
		return Math.round(h / 24) + "d";
	}

	/** "now", "12m ago", "3h ago", "2d ago". */
	public static String ago(long then, long now)
	{
		long m = Math.max(0, now - then) / 60_000L;
		if (m < 1)
		{
			return "now";
		}
		if (m < 60)
		{
			return m + "m ago";
		}
		long h = m / 60;
		if (h < 24)
		{
			return h + "h ago";
		}
		return h / 24 + "d ago";
	}

	public static String plural(long n, String one, String many)
	{
		return number(n) + " " + (n == 1 ? one : many);
	}

	private static final DateTimeFormatter SHORT_DAY = DateTimeFormatter.ofPattern("d MMM", Locale.ENGLISH);

	/** "16 Oct". */
	public static String shortDay(long epochMs)
	{
		return SHORT_DAY.format(Instant.ofEpochMilli(epochMs).atZone(ZoneId.systemDefault()));
	}
}

package com.codex.pestcontrol.ui;

import com.codex.pestcontrol.core.Boat;
import com.codex.pestcontrol.core.GameRecord;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** One finished game: how it ended, the lander, the points it gave and how it went. */
class GameRow extends JComponent
{
	private final GameRecord game;
	private final long now;

	GameRow(GameRecord game, long now)
	{
		this.game = game;
		this.now = now;
		setOpaque(false);
		setPreferredSize(new Dimension(10, 36));
	}

	static String result(GameRecord.Result r)
	{
		switch (r)
		{
			case WON:
				return "Won";
			case LOST:
				return "Lost";
			case NO_POINTS:
				return "Won, no points";
			default:
				return "Left early";
		}
	}

	static Color color(GameRecord.Result r)
	{
		switch (r)
		{
			case WON:
				return Theme.GREEN;
			case LOST:
				return Theme.BLOOD;
			case NO_POINTS:
				return Theme.EMBER;
			default:
				return Theme.TEXT_FAINT;
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, 8, 8);
		g.setPaint(new GradientPaint(0, 0, Theme.CARD_TOP, 0, h, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);

		GameRecord.Result r = game.getResult();
		Color c = color(r);
		g.setColor(Theme.alpha(c, 60));
		g.fill(new Ellipse2D.Float(7, h / 2f - 6, 12, 12));
		g.setColor(c);
		g.fill(new Ellipse2D.Float(10, h / 2f - 3, 6, 6));

		int tx = 26;
		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		Boat boat = game.getBoat();
		String title = result(r) + (boat == null ? "" : "  -  " + boat.getTitle());
		String pts = game.getPoints() > 0 ? "+" + game.getPoints() : "0";
		g.setFont(Theme.title());
		FontMetrics bold = g.getFontMetrics();
		int pw = bold.stringWidth(pts);
		Ui.shadowed(g, pts, w - pw - 8, 4 + bold.getAscent(), game.getPoints() > 0 ? Theme.GOLD_BRIGHT : Theme.TEXT_FAINT);
		g.setFont(Theme.body());
		Ui.shadowed(g, Ui.clip(title, body, w - tx - pw - 14), tx, 4 + body.getAscent(), Theme.TEXT);

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		String line = game.getDamage() + " dmg  -  " + Format.clock(game.getSeconds()) + "  -  " + Format.ago(game.getEnded(), now);
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(Ui.clip(line, small, w - tx - 8), tx, h - 7);
		g.dispose();
	}
}

package com.codex.pestcontrol.ui;

import java.awt.image.BufferedImage;
import java.util.Collection;

/** Item pictures, which may arrive later; the callback runs once one has loaded. */
public interface ItemIcons
{
	BufferedImage get(int itemId, Runnable onLoaded);

	/**
	 * Runs {@code then} once every one of these pictures has arrived: at once when they all have,
	 * otherwise when the last comes in. A card drawn to be shared waits on this, so it never goes
	 * out with an empty slot where a picture was still on its way.
	 */
	default void whenLoaded(Collection<Integer> itemIds, Runnable then)
	{
		then.run();
	}
}

package com.codex.pestcontrol.ui;

import java.awt.image.BufferedImage;
import java.util.Collection;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;
import java.util.WeakHashMap;
import java.util.concurrent.Executor;
import java.util.function.IntFunction;
import javax.swing.SwingUtilities;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Item pictures from RuneLite's item manager, with the callback handed over only until the picture
 * arrives. Once an image has loaded, {@link AsyncBufferedImage#onLoaded} runs a callback again for
 * every call, so a row asking for its icon while it paints, with a repaint to follow, would paint
 * forever. Here a picture is watched once; every row that asked before it arrived is told when it
 * does, and a row asking after is just handed the picture.
 *
 * <p>A row should hand over the same callback each time it asks, such as a repaint kept in a field,
 * so a row painting many times while a picture loads is told once and never crowds out another.</p>
 *
 * <p>Asked on the Swing thread, where the callbacks also run.</p>
 */
public final class LoadingIcons implements ItemIcons
{
	private final IntFunction<AsyncBufferedImage> source;
	private final Executor swing;
	/** Pictures that have arrived; weak, so the item manager's cache decides how long they live. */
	private final Set<AsyncBufferedImage> arrived = Collections.newSetFromMap(new WeakHashMap<>());
	/** For each picture still loading, the callbacks waiting on it. */
	private final Map<AsyncBufferedImage, Set<Runnable>> waiting = new WeakHashMap<>();
	/** Most callbacks kept for one picture, so one that never arrives cannot gather them without end. */
	static final int MOST_WAITING = 256;

	public LoadingIcons(IntFunction<AsyncBufferedImage> source)
	{
		this(source, SwingUtilities::invokeLater);
	}

	LoadingIcons(IntFunction<AsyncBufferedImage> source, Executor swing)
	{
		this.source = source;
		this.swing = swing;
	}

	@Override
	public BufferedImage get(int itemId, Runnable onLoaded)
	{
		AsyncBufferedImage image = source.apply(itemId);
		if (image != null && onLoaded != null && !arrived.contains(image))
		{
			watch(image, onLoaded, true);
		}
		return image;
	}

	@Override
	public void whenLoaded(Collection<Integer> itemIds, Runnable then)
	{
		Set<AsyncBufferedImage> pending = Collections.newSetFromMap(new IdentityHashMap<>());
		for (int id : itemIds)
		{
			AsyncBufferedImage image = source.apply(id);
			if (image != null && !arrived.contains(image))
			{
				pending.add(image);
			}
		}
		if (pending.isEmpty())
		{
			then.run();
			return;
		}
		// One callback for every picture the card waits on; it runs then when the last is in.
		int[] left = {pending.size()};
		Runnable one = () ->
		{
			if (--left[0] == 0)
			{
				then.run();
			}
		};
		for (AsyncBufferedImage image : pending)
		{
			// Never turned away by the bound on rows: a card waits on each picture just once.
			watch(image, one, false);
		}
	}

	private void watch(AsyncBufferedImage image, Runnable onLoaded, boolean bounded)
	{
		Set<Runnable> queue = waiting.get(image);
		if (queue == null)
		{
			Set<Runnable> fresh = new LinkedHashSet<>();
			waiting.put(image, fresh);
			queue = fresh;
			// Runs on the client thread when the picture arrives; the rows hear of it on Swing's.
			image.onLoaded(() -> swing.execute(() ->
			{
				arrived.add(image);
				Set<Runnable> told = waiting.remove(image);
				if (told != null)
				{
					told.forEach(Runnable::run);
				}
			}));
		}
		// A row painting while the picture loads asks each frame; it need only be told once.
		if (!bounded || queue.size() < MOST_WAITING)
		{
			queue.add(onLoaded);
		}
	}
}

package com.codex.pestcontrol.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import javax.swing.JComponent;

/** A gilt progress bar with its label above: "412 / 850 points" and how far that is. */
class Meter extends JComponent
{
	private final Animator fill = new Animator(this);
	private String left = "";
	private String right = "";
	private Color color = Theme.GOLD;

	Meter()
	{
		setOpaque(false);
		setPreferredSize(new Dimension(10, 30));
	}

	void set(double progress, String left, String right, Color color)
	{
		this.left = left;
		this.right = right;
		this.color = color;
		fill.set(Math.max(0, Math.min(1, progress)), true);
		repaint();
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		int base = fm.getAscent();
		Ui.shadowed(g, Ui.clip(left, fm, w - fm.stringWidth(right) - 8), 0, base, Theme.TEXT);
		g.setColor(Theme.TEXT_MUTED);
		g.drawString(right, w - fm.stringWidth(right), base);

		int y = base + 6;
		int h = 10;
		RoundRectangle2D track = new RoundRectangle2D.Float(0.5f, y + 0.5f, w - 1, h - 1, h, h);
		g.setColor(Theme.INK_DEEP);
		g.fill(track);
		int fw = (int) Math.round((w - 2) * fill.get());
		if (fw > 0)
		{
			g.setClip(track);
			g.setPaint(new GradientPaint(0, y, Theme.mix(color, Color.WHITE, 0.3), 0, y + h, Theme.mix(color, Theme.INK_DEEP, 0.3)));
			g.fill(new RoundRectangle2D.Float(1, y + 1, fw, h - 2, h - 2, h - 2));
			g.setColor(Theme.alpha(Color.WHITE, 60));
			g.drawLine(3, y + 2, Math.max(3, fw - 2), y + 2);
			g.setClip(null);
		}
		g.setColor(Theme.STROKE_SOFT);
		g.draw(track);
		// Quarter marks, engraved into the track.
		g.setColor(Theme.alpha(Theme.INK_DEEP, 160));
		for (int i = 1; i < 4; i++)
		{
			int x = w * i / 4;
			g.drawLine(x, y + 2, x, y + h - 3);
		}
		g.dispose();
	}
}

package com.codex.pestcontrol.ui;

import com.codex.pestcontrol.core.Outlook;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.geom.Ellipse2D;
import java.awt.image.BufferedImage;
import javax.swing.JComponent;

/**
 * One stop on the way to the goal, drawn as a node on a gilt line: the piece, the points it takes
 * with everything before it, and how many games until it can be bought.
 */
class MilestoneRow extends JComponent
{
	private static final int HEIGHT = 30;

	private final Outlook.Milestone milestone;
	private final boolean first;
	private final boolean last;
	private final boolean locked;
	private final ItemIcons icons;
	/** Handed over each time an icon is asked for, so a row waiting on a picture is told once. */
	private final Runnable repaint = this::repaint;

	MilestoneRow(Outlook.Milestone milestone, boolean first, boolean last, boolean locked, ItemIcons icons)
	{
		this.milestone = milestone;
		this.first = first;
		this.last = last;
		this.locked = locked;
		this.icons = icons;
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();
		int cx = 8;
		int cy = h / 2;
		boolean ready = milestone.getGames() == 0;
		Color node = locked ? Theme.BLOCKED : ready ? Theme.TEAL : Theme.GOLD;

		g.setStroke(new BasicStroke(2f));
		g.setColor(Theme.alpha(Theme.GOLD, 90));
		if (!first)
		{
			g.drawLine(cx, 0, cx, cy - 5);
		}
		if (!last)
		{
			g.drawLine(cx, cy + 5, cx, h);
		}
		g.setStroke(new BasicStroke(1.4f));
		g.setColor(Theme.INK_DEEP);
		g.fill(new Ellipse2D.Float(cx - 5, cy - 5, 10, 10));
		g.setColor(node);
		g.draw(new Ellipse2D.Float(cx - 5, cy - 5, 10, 10));
		if (ready || last)
		{
			g.fill(new Ellipse2D.Float(cx - 2.5f, cy - 2.5f, 5, 5));
		}

		int tx = 22;
		BufferedImage icon = icons == null ? null : icons.get(milestone.getReward().getIcon(), repaint);
		if (icon != null)
		{
			int s = 24;
			g.drawImage(icon, tx, cy - s / 2, s, s, null);
			tx += s + 4;
		}

		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		boolean unknown = milestone.getGames() < 0;
		String when = locked ? "diary" : ready ? "now" : unknown ? "?" : Format.plural(milestone.getGames(), "game", "games");
		String time = locked || ready || unknown ? null : Format.span(milestone.getMinutes());
		int rw = Math.max(small.stringWidth(when), time == null ? 0 : small.stringWidth(time));
		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		String name = milestone.getReward().getShortTitle();
		Ui.shadowed(g, Ui.clip(name, body, w - tx - rw - 8), tx, cy - 1, last ? Theme.GOLD_BRIGHT : Theme.TEXT);
		g.setFont(Theme.small());
		g.setColor(Theme.TEXT_FAINT);
		g.drawString(Ui.clip(Format.number(milestone.getTotal()) + " points", small, w - tx - rw - 8), tx, cy + small.getAscent() + 1);
		Ui.shadowed(g, when, w - small.stringWidth(when), time == null ? cy + small.getAscent() / 2 : cy - 1, node);
		if (time != null)
		{
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(time, w - small.stringWidth(time), cy + small.getAscent() + 1);
		}
		g.dispose();
	}
}

package com.codex.pestcontrol.ui;

import com.codex.pestcontrol.core.Advice;
import com.codex.pestcontrol.core.Portal;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RadialGradientPaint;
import java.awt.geom.Ellipse2D;
import java.awt.geom.Path2D;
import java.awt.geom.Point2D;
import java.awt.geom.RoundRectangle2D;
import java.util.List;
import javax.swing.JComponent;
import javax.swing.Timer;

/**
 * The island drawn as a small chart: the outpost walls and gates round the Void Knight, and the
 * four portals where they stand. Open portals glow, shielded ones sit behind a pale ring,
 * fallen ones go grey, and the one to work next wears a gold halo with the way there traced
 * from the knight through the right gate.
 */
public class OutpostMap extends JComponent
{
	private static final int HEIGHT = 178;
	private static final int R = 15;

	private final Timer pulse = new Timer(60, e -> repaint());
	private View.Fight fight;

	public OutpostMap()
	{
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setMinimumSize(new Dimension(10, HEIGHT));
	}

	public void setFight(View.Fight fight)
	{
		this.fight = fight;
		boolean animate = fight != null && fight.advice != null && fight.advice.getPortal() != null;
		if (animate && !pulse.isRunning())
		{
			pulse.start();
		}
		else if (!animate)
		{
			pulse.stop();
		}
		repaint();
	}

	@Override
	public void removeNotify()
	{
		pulse.stop();
		super.removeNotify();
	}

	@Override
	public void addNotify()
	{
		super.addNotify();
		setFight(fight);
	}

	private static Point2D.Float spot(Portal p, int w, int h)
	{
		switch (p)
		{
			case PURPLE:
				return new Point2D.Float(w * 0.13f, h * 0.36f);
			case BLUE:
				return new Point2D.Float(w * 0.87f, h * 0.36f);
			case YELLOW:
				return new Point2D.Float(w * 0.72f, h * 0.80f);
			default:
				return new Point2D.Float(w * 0.28f, h * 0.80f);
		}
	}

	/** The gate a portal is reached through, on the outpost wall. */
	private static Point2D.Float gate(Portal p, float left, float top, float right, float bottom)
	{
		float midY = (top + bottom) / 2;
		switch (p)
		{
			case PURPLE:
				return new Point2D.Float(left, midY);
			case BLUE:
				return new Point2D.Float(right, midY);
			default:
				return new Point2D.Float((left + right) / 2, bottom);
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		int h = getHeight();

		// The chart: a dark well with a faint sea-green wash, the island a warmer patch.
		RoundRectangle2D well = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, h - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(0, 0, Theme.mix(Theme.INK_DEEP, Theme.TEAL, 0.06), 0, h, Theme.INK_DEEP));
		g.fill(well);
		g.setClip(well);
		g.setPaint(new RadialGradientPaint(w / 2f, h * 0.5f, w * 0.62f, new float[]{0f, 1f},
			new Color[]{Theme.alpha(Theme.mix(Theme.CARD_TOP, Theme.GOLD_DIM, 0.25), 200), Theme.alpha(Theme.INK_DEEP, 0)}));
		g.fill(new Ellipse2D.Float(-w * 0.1f, h * 0.02f, w * 1.2f, h * 0.98f));
		g.setClip(null);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(well);

		// The outpost walls with their three gates left open.
		float left = w * 0.33f;
		float right = w * 0.67f;
		float top = h * 0.14f;
		float bottom = h * 0.56f;
		float gap = 7;
		float midX = (left + right) / 2;
		float midY = (top + bottom) / 2;
		g.setStroke(new BasicStroke(2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		g.setColor(Theme.mix(Theme.STROKE, Theme.GOLD_DIM, 0.35));
		Path2D wall = new Path2D.Float();
		wall.moveTo(left, midY - gap);
		wall.lineTo(left, top);
		wall.lineTo(right, top);
		wall.lineTo(right, midY - gap);
		wall.moveTo(right, midY + gap);
		wall.lineTo(right, bottom);
		wall.lineTo(midX + gap, bottom);
		wall.moveTo(midX - gap, bottom);
		wall.lineTo(left, bottom);
		wall.lineTo(left, midY + gap);
		g.draw(wall);

		View.Fight f = fight;
		Portal target = f == null || f.advice == null ? null : f.advice.getPortal();
		List<Portal> maybe = f == null || f.advice == null ? null : f.advice.getCandidates();
		boolean waiting = f != null && f.advice != null && f.advice.getKind() == Advice.Kind.WAIT;

		// The way there: from the knight, out through the gate, to the portal.
		Point2D.Float knight = new Point2D.Float(midX, midY);
		if (target != null)
		{
			Point2D.Float door = gate(target, left, top, right, bottom);
			Point2D.Float to = spot(target, w, h);
			Path2D path = new Path2D.Float();
			path.moveTo(knight.x, knight.y);
			path.lineTo(door.x, door.y);
			path.lineTo(to.x, to.y);
			// The dashes march outward: the phase runs down through one dash period.
			float phase = 10 - (System.currentTimeMillis() % 1200) / 1200f * 10;
			g.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 1f, new float[]{4, 6}, phase));
			g.setColor(Theme.alpha(Theme.GOLD, 190));
			g.draw(path);
		}

		// The Void Knight.
		g.setStroke(new BasicStroke(1f));
		paintKnight(g, knight.x, knight.y, f == null ? -1 : f.knightHealth);

		g.setFont(Theme.small());
		FontMetrics fm = g.getFontMetrics();
		double glow = 0.5 + 0.5 * Math.sin(System.currentTimeMillis() / 260.0);
		for (Portal p : Portal.values())
		{
			View.PortalState s = f == null ? new View.PortalState(p, true, false, -1, -1) : f.portal(p);
			Point2D.Float c = spot(p, w, h);
			boolean isTarget = p == target;
			boolean isMaybe = waiting && maybe != null && maybe.contains(p);
			paintPortal(g, s, c.x, c.y, isTarget, isMaybe, glow);

			String below = s.fallen ? "Fallen" : s.health >= 0 ? String.valueOf(s.health) : s.shielded ? "Shielded" : "Open";
			Color belowColor = s.fallen ? Theme.TEXT_FAINT : s.shielded ? Theme.TEXT_MUTED : Theme.TEXT;
			Ui.shadowed(g, below, Math.round(c.x - fm.stringWidth(below) / 2f), Math.round(c.y + R + 4 + fm.getAscent()), belowColor);
			if (!s.fallen && s.eta >= 0)
			{
				// How long the rest of the team will take to bring it down, so the slow portal stands out.
				// A portal only you are hitting reads as stalled for the team; say it is yours instead.
				boolean stalled = s.eta == com.codex.pestcontrol.core.Battle.STALLED;
				String pace = stalled ? s.yoursAlone ? "just you" : "stalled" : "~" + s.eta + "s";
				Ui.shadowed(g, pace, Math.round(c.x - fm.stringWidth(pace) / 2f), Math.round(c.y + R + 5 + fm.getAscent() + fm.getHeight() - 2),
					stalled ? s.yoursAlone ? Theme.GOLD : Theme.EMBER : Theme.TEXT_FAINT);
			}

			if (s.crowd > 0 && !s.fallen)
			{
				paintCrowd(g, s.crowd, Math.max(14, c.x - R - 8), c.y + 6, fm);
			}
			int order = f == null ? -1 : f.order.indexOf(p);
			if (order >= 0 && !s.fallen)
			{
				paintBadge(g, String.valueOf(order + 1), c.x + R * 0.72f, c.y - R * 0.72f, fm);
			}
			if (isTarget || isMaybe)
			{
				String tag = isTarget ? (f.advice.getKind() == Advice.Kind.ATTACK ? "ATTACK" : "NEXT") : "MAYBE";
				Color tagColor = isTarget ? Theme.GOLD_BRIGHT : Theme.TEXT_MUTED;
				Ui.shadowed(g, tag, Math.round(c.x - fm.stringWidth(tag) / 2f), Math.round(c.y - R - 5), tagColor);
			}
		}

		// The game clock and, once learned, when the next shield is due.
		if (f != null)
		{
			g.setColor(Theme.TEXT_FAINT);
			g.drawString(Format.clock(f.seconds), 8, 14);
			int down = 0;
			for (View.PortalState s : f.portals)
			{
				down += s.shielded ? 0 : 1;
			}
			if (f.nextDrop >= 0 && down < 4)
			{
				String due = f.nextDrop <= 3 ? "Shield any moment" : "Next shield " + f.nextDrop + "s";
				Ui.shadowed(g, due, 8, 14 + fm.getHeight(), f.nextDrop <= 3 ? Theme.GOLD_BRIGHT : Theme.GOLD);
			}
		}

		// The compass rose's north mark, so west and east read the right way round.
		g.setColor(Theme.TEXT_FAINT);
		g.drawString("N", w - 14, 14);
		g.fill(new Path2D.Float(new java.awt.Polygon(new int[]{w - 11, w - 14, w - 8}, new int[]{17, 22, 22}, 3)));
		g.dispose();
	}

	private static void paintKnight(Graphics2D g, float x, float y, int health)
	{
		float r = 8;
		g.setPaint(new RadialGradientPaint(x, y - 2, r * 1.6f, new float[]{0f, 1f},
			new Color[]{Theme.alpha(Theme.GOLD_BRIGHT, 90), Theme.alpha(Theme.GOLD, 0)}));
		g.fill(new Ellipse2D.Float(x - r * 1.6f, y - r * 1.6f, r * 3.2f, r * 3.2f));
		Sigil.paint(g, x - r, y - r, r * 2);
		if (health >= 0)
		{
			g.setFont(Theme.small());
			FontMetrics fm = g.getFontMetrics();
			String text = String.valueOf(health);
			Color color = health <= 60 ? Theme.BLOOD : health <= 120 ? Theme.EMBER : Theme.TEXT;
			Ui.shadowed(g, text, Math.round(x - fm.stringWidth(text) / 2f), Math.round(y + r + 2 + fm.getAscent()), color);
		}
	}

	private static void paintPortal(Graphics2D g, View.PortalState s, float x, float y, boolean target, boolean maybe, double glow)
	{
		Color colour = Theme.portal(s.portal);
		if (s.fallen)
		{
			colour = Theme.mix(colour, Theme.INK, 0.72);
		}
		else if (s.shielded)
		{
			colour = Theme.mix(colour, Theme.INK, 0.35);
		}

		if (target)
		{
			float halo = R + 7 + (float) glow * 2;
			g.setPaint(new RadialGradientPaint(x, y, halo, new float[]{0.55f, 1f},
				new Color[]{Theme.alpha(Theme.GOLD_BRIGHT, (int) (70 + 60 * glow)), Theme.alpha(Theme.GOLD, 0)}));
			g.fill(new Ellipse2D.Float(x - halo, y - halo, halo * 2, halo * 2));
		}
		else if (!s.fallen && !s.shielded)
		{
			float halo = R + 6;
			g.setPaint(new RadialGradientPaint(x, y, halo, new float[]{0.5f, 1f},
				new Color[]{Theme.alpha(colour, 110), Theme.alpha(colour, 0)}));
			g.fill(new Ellipse2D.Float(x - halo, y - halo, halo * 2, halo * 2));
		}

		// The rift itself: bright at its heart, the portal's colour at its rim.
		g.setPaint(new RadialGradientPaint(x - R * 0.2f, y - R * 0.25f, R, new float[]{0f, 0.6f, 1f},
			new Color[]{Theme.mix(colour, Color.WHITE, s.fallen ? 0.05 : 0.45), colour, Theme.mix(colour, Theme.INK_DEEP, 0.55)}));
		g.fill(new Ellipse2D.Float(x - R, y - R, R * 2, R * 2));
		g.setStroke(new BasicStroke(1.2f));
		g.setColor(Theme.mix(colour, Theme.INK_DEEP, 0.3));
		g.draw(new Ellipse2D.Float(x - R, y - R, R * 2, R * 2));

		if (!s.fallen)
		{
			// A swirl inside, so it reads as a portal and not a gem.
			g.setStroke(new BasicStroke(1.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(Theme.alpha(Color.WHITE, s.shielded ? 60 : 130));
			Path2D swirl = new Path2D.Float();
			swirl.moveTo(x + R * 0.55f, y - R * 0.1f);
			swirl.curveTo(x + R * 0.5f, y - R * 0.6f, x - R * 0.35f, y - R * 0.6f, x - R * 0.45f, y);
			swirl.curveTo(x - R * 0.5f, y + R * 0.45f, x + R * 0.15f, y + R * 0.5f, x + R * 0.2f, y + R * 0.1f);
			g.draw(swirl);
		}

		if (s.shielded && !s.fallen)
		{
			g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND, 1f, new float[]{3, 3}, 0));
			g.setColor(Theme.alpha(Theme.TEXT, maybe ? 200 : 120));
			g.draw(new Ellipse2D.Float(x - R - 3, y - R - 3, (R + 3) * 2, (R + 3) * 2));
		}
		if (s.fallen)
		{
			g.setStroke(new BasicStroke(1.6f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.setColor(Theme.alpha(Theme.TEXT_FAINT, 200));
			float d = R * 0.45f;
			g.draw(new java.awt.geom.Line2D.Float(x - d, y - d, x + d, y + d));
			g.draw(new java.awt.geom.Line2D.Float(x - d, y + d, x + d, y - d));
		}
		if (target)
		{
			g.setStroke(new BasicStroke(1.6f));
			g.setColor(Theme.GOLD_BRIGHT);
			g.draw(new Ellipse2D.Float(x - R - 3.5f, y - R - 3.5f, (R + 3.5f) * 2, (R + 3.5f) * 2));
		}
		g.setStroke(new BasicStroke(1f));
	}

	/** A small figure and a count: the other players at a portal. */
	private static void paintCrowd(Graphics2D g, int players, float x, float y, FontMetrics fm)
	{
		String text = String.valueOf(players);
		float w = 9 + fm.stringWidth(text) + 4;
		RoundRectangle2D pill = new RoundRectangle2D.Float(x - w / 2, y - 6, w, 12, 10, 10);
		g.setColor(Theme.alpha(Theme.INK_DEEP, 230));
		g.fill(pill);
		g.setColor(Theme.alpha(Theme.TEXT_MUTED, 150));
		g.draw(pill);
		float px = x - w / 2 + 6;
		g.setColor(Theme.TEXT);
		g.fill(new Ellipse2D.Float(px - 1.5f, y - 4, 3, 3));
		g.fill(new RoundRectangle2D.Float(px - 2.5f, y - 0.5f, 5, 4, 2, 2));
		g.drawString(text, Math.round(px + 5), Math.round(y + fm.getAscent() / 2f - 1));
	}

	private static void paintBadge(Graphics2D g, String text, float x, float y, FontMetrics fm)
	{
		float d = 11;
		g.setColor(Theme.INK_DEEP);
		g.fill(new Ellipse2D.Float(x - d / 2, y - d / 2, d, d));
		g.setColor(Theme.alpha(Theme.GOLD, 200));
		g.draw(new Ellipse2D.Float(x - d / 2, y - d / 2, d, d));
		g.setColor(Theme.GOLD_BRIGHT);
		g.drawString(text, Math.round(x - fm.stringWidth(text) / 2f), Math.round(y + fm.getAscent() / 2f - 1));
	}
}

package com.codex.pestcontrol.ui;

