import java.awt.GradientPaint;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.Consumer;
import javax.swing.JComponent;

/**
 * The void as it would be worn: the game's own equipment screen, with each reward in its slot, the
 * three helms racked along the top. What is owned is drawn whole in a gilt slot, what the goal still
 * wants is drawn dim over a bar of the points saved toward it, and the rest is a faint outline.
 * Clicking a slot adds that reward to the goal or takes it out, as the list below does.
 */
class Wardrobe extends JComponent
{
	private static final int PAD = 12;
	private static final int SLOT_W = 38;
	private static final int SLOT_H = 34;
	private static final int GAP_X = 14;
	private static final int GAP_Y = 9;
	private static final int TOP = 30;
	private static final int ROWS = 5;
	private static final int HEIGHT = TOP + ROWS * SLOT_H + (ROWS - 1) * GAP_Y + 44;

	/** Where a slot sits on the equipment screen, by column and row, and what it holds. */
	static final class Slot
	{
		final int col;
		final int row;
		/** The reward in it, or null for a slot void has nothing for. */
		final Reward reward;

		Slot(int col, int row, Reward reward)
		{
			this.col = col;
			this.row = row;
			this.reward = reward;
		}
	}

	/** Where a reward stands, for its slot's look. */
	enum Look
	{
		OWNED,
		CAN_BUY,
		WANTED,
		LOCKED,
		NONE
	}

	private final Slot[] slots;
	private final Set<Reward> goal;
	private final Set<Reward> owned;
	/** The pieces the points buy now, together, in the buy order. */
	private final Set<Reward> buyable;
	private final int points;
	private final boolean pointsKnown;
	private final boolean elite;
	private final ItemIcons icons;
	/** Handed over each time an icon is asked for, so a row waiting on a picture is told once. */
	private final Runnable repaint = this::repaint;
	private final String title;

	/**
	 * @param buyable the pieces the points buy now, together ({@link com.codex.pestcontrol.core.Outlook#buyableNow})
	 * @param points commendation points held, for how far each wanted piece is saved toward
	 * @param elite the hard Western Provinces diary is done, so elite pieces can be bought
	 * @param toggle adds a reward to the goal or takes it out; null for none
	 */
	Wardrobe(String title, Set<Reward> goal, Set<Reward> owned, Set<Reward> buyable, int points, boolean pointsKnown, boolean elite,
		ItemIcons icons, Consumer<Reward> toggle)
	{
		this.title = title;
		this.goal = goal;
		this.owned = owned;
		this.buyable = buyable;
		this.points = points;
		this.pointsKnown = pointsKnown;
		this.elite = elite;
		this.icons = icons;
		this.slots = layout(goal, owned);
		setOpaque(false);
		setPreferredSize(new Dimension(10, HEIGHT));
		setMinimumSize(new Dimension(10, HEIGHT));
		// Tooltips are worked out per slot.
		setToolTipText("");
		if (toggle != null)
		{
			addMouseListener(new MouseAdapter()
			{
				@Override
				public void mouseReleased(MouseEvent e)
				{
					Slot s = at(e.getX(), e.getY());
					if (s != null && s.reward != null && contains(e.getPoint()))
					{
						toggle.accept(s.reward);
					}
				}
			});
			addMouseMotionListener(new MouseAdapter()
			{
				@Override
				public void mouseMoved(MouseEvent e)
				{
					Slot s = at(e.getX(), e.getY());
					setCursor(Cursor.getPredefinedCursor(s != null && s.reward != null ? Cursor.HAND_CURSOR : Cursor.DEFAULT_CURSOR));
				}
			});
		}
	}

	/**
	 * The equipment screen's slots: the helms along the top in place of the head, then neck, the
	 * weapon, body and shield row, legs, and hands, feet and ring, as the game lays them out. The
	 * body and legs hold the elite pieces when the goal wants them or they are owned.
	 */
	static Slot[] layout(Set<Reward> goal, Set<Reward> owned)
	{
		boolean eliteTop = goal.contains(Reward.ELITE_TOP) || owned.contains(Reward.ELITE_TOP);
		boolean eliteRobe = goal.contains(Reward.ELITE_ROBE) || owned.contains(Reward.ELITE_ROBE);
		return new Slot[]{
			new Slot(0, 0, Reward.MELEE_HELM), new Slot(1, 0, Reward.RANGER_HELM), new Slot(2, 0, Reward.MAGE_HELM),
			new Slot(0, 1, null), new Slot(1, 1, Reward.SEAL), new Slot(2, 1, null),
			new Slot(0, 2, Reward.MACE), new Slot(1, 2, eliteTop ? Reward.ELITE_TOP : Reward.TOP), new Slot(2, 2, null),
			new Slot(1, 3, eliteRobe ? Reward.ELITE_ROBE : Reward.ROBE),
			new Slot(0, 4, Reward.GLOVES), new Slot(1, 4, null), new Slot(2, 4, null),
		};
	}

	/**
	 * How a reward's slot looks: owned whole, wanted dim with its savings, the rest faint. Teal
	 * marks only the pieces the points buy together, so three pieces that 412 points would each
	 * cover alone are not all lit when they cover one.
	 */
	static Look look(Reward r, Set<Reward> goal, Set<Reward> owned, Set<Reward> buyable, boolean elite)
	{
		if (owned.contains(r))
		{
			return Look.OWNED;
		}
		if (!goal.contains(r))
		{
			return Look.NONE;
		}
		if (r.isElite() && !elite)
		{
			return Look.LOCKED;
		}
		return buyable.contains(r) ? Look.CAN_BUY : Look.WANTED;
	}

	private int gridX()
	{
		return (getWidth() - (3 * SLOT_W + 2 * GAP_X)) / 2;
	}

	private int slotX(Slot s)
	{
		return gridX() + s.col * (SLOT_W + GAP_X);
	}

	private static int slotY(Slot s)
	{
		return TOP + s.row * (SLOT_H + GAP_Y);
	}

	private Slot at(int x, int y)
	{
		for (Slot s : slots)
		{
			int sx = slotX(s);
			int sy = slotY(s);
			if (x >= sx && x < sx + SLOT_W && y >= sy && y < sy + SLOT_H)
			{
				return s;
			}
		}
		return null;
	}

	@Override
	public String getToolTipText(MouseEvent e)
	{
		Slot s = at(e.getX(), e.getY());
		if (s == null || s.reward == null)
		{
			return null;
		}
		Reward r = s.reward;
		switch (look(r, goal, owned, buyable, elite))
		{
			case OWNED:
				return r.getTitle() + ": yours";
			case CAN_BUY:
				return r.getTitle() + ": you can buy it now (" + r.getCost() + " points). Click to take it out of your goal";
			case WANTED:
				return r.getTitle() + ": " + (pointsKnown ? toGo(r, goal, owned, points, elite) + " points to go, counting the pieces before it"
					: r.getCost() + " points") + ". Click to take it out of your goal";
			case LOCKED:
				return r.getTitle() + ": needs the hard Western Provinces diary";
			default:
				return r.getTitle() + ", " + r.getCost() + " points. Click to add it to your goal";
		}
	}

	@Override
	protected void paintComponent(Graphics graphics)
	{
		Graphics2D g = (Graphics2D) graphics.create();
		Theme.smooth(g);
		int w = getWidth();
		RoundRectangle2D shape = new RoundRectangle2D.Float(0.5f, 0.5f, w - 1, HEIGHT - 1, Theme.RADIUS, Theme.RADIUS);
		g.setPaint(new GradientPaint(0, 0, Theme.CARD_TOP, 0, HEIGHT, Theme.CARD));
		g.fill(shape);
		g.setColor(Theme.STROKE_SOFT);
		g.draw(shape);

		g.setFont(Theme.body());
		FontMetrics body = g.getFontMetrics();
		Ui.shadowed(g, "Your void", PAD, 8 + body.getAscent(), Theme.GOLD);
		g.setFont(Theme.small());
		FontMetrics small = g.getFontMetrics();
		int have = 0;
		int wanted = 0;
		for (Reward r : goal)
		{
			wanted++;
			have += owned.contains(r) ? 1 : 0;
		}
		String count = wanted == 0 ? "no goal" : have + " of " + wanted + " owned";
		g.setColor(have == wanted && wanted > 0 ? Theme.GREEN : Theme.TEXT_FAINT);
		g.drawString(count, w - PAD - small.stringWidth(count), 8 + body.getAscent());

		// The equipment screen's threads between the slots, as the game draws them.
		int gx = gridX();
		int cx = gx + SLOT_W + GAP_X + SLOT_W / 2;
		g.setColor(Theme.alpha(Theme.GOLD, 45));
		g.setStroke(new BasicStroke(2f));
		g.drawLine(cx, slotY(new Slot(1, 0, null)) + SLOT_H / 2, cx, slotY(new Slot(1, 4, null)) + SLOT_H / 2);
		for (int row : new int[]{1, 2, 4})
		{
			int y = TOP + row * (SLOT_H + GAP_Y) + SLOT_H / 2;
			g.drawLine(gx + SLOT_W / 2, y, gx + 2 * (SLOT_W + GAP_X) + SLOT_W / 2, y);
		}
		g.setStroke(new BasicStroke(1f));

		for (Slot s : slots)
		{
			paintSlot(g, s, slotX(s), slotY(s), small);
		}

		// Under it: where the goal stands, in one line.
		String foot = foot(title, goal, owned, buyable, Math.max(0, points), pointsKnown, elite);
		Color footColor = wanted == 0 ? Theme.TEXT_MUTED : have == wanted ? Theme.GREEN
			: !buyable.isEmpty() ? Theme.TEAL : foot.startsWith("Points") ? Theme.GOLD : Theme.TEXT_MUTED;
		int fy = HEIGHT - 14;
		Ui.shadowed(g, Ui.clip(foot, small, w - PAD * 2), (w - Math.min(w - PAD * 2, small.stringWidth(foot))) / 2, fy, footColor);
		g.dispose();
	}

	/**
	 * The points the buy order spends on the pieces before each needed one, the same order the Buy
	 * order list gives: elite pieces still behind the diary come last.
	 */
	static Map<Reward, Integer> ahead(Set<Reward> goal, Set<Reward> owned, int points, boolean elite)
	{
		Set<Reward> locked = EnumSet.noneOf(Reward.class);
		for (Reward r : goal)
		{
			if (r.isElite() && !elite && !owned.contains(r))
			{
				locked.add(r);
			}
		}
		Map<Reward, Integer> out = new EnumMap<>(Reward.class);
		for (Outlook.Milestone m : Outlook.of(goal, owned, Math.max(0, points), 1, 0, false).milestones(locked))
		{
			out.put(m.getReward(), m.getTotal() - m.getReward().getCost());
		}
		return out;
	}

	/** The points still to earn before a needed piece can be bought, the pieces before it counted. */
	static int toGo(Reward r, Set<Reward> goal, Set<Reward> owned, int points, boolean elite)
	{
		Integer before = ahead(goal, owned, points, elite).get(r);
		return Math.max(0, (before == null ? 0 : before) + r.getCost() - Math.max(0, points));
	}

	/** How much of a needed piece is saved toward once the pieces before it are bought, from 0 to 1. */
	static double saved(Reward r, Set<Reward> goal, Set<Reward> owned, int points, boolean elite)
	{
		Integer before = ahead(goal, owned, points, elite).get(r);
		double left = Math.max(0, points) - (before == null ? 0 : before);
		return Math.max(0, Math.min(1, left / r.getCost()));
	}

	/**
	 * The line under the slots: what the points buy now, or how to change the goal. The crest
	 * already says how many points the goal still wants, so the line does not say it again.
	 */
	static String foot(String title, Set<Reward> goal, Set<Reward> owned, Set<Reward> buyable, int points, boolean pointsKnown, boolean elite)
	{
		int left = 0;
		boolean locked = false;
		boolean all = true;
		for (Reward r : goal)
		{
			if (!owned.contains(r))
			{
				all = false;
				left += r.getCost();
				locked |= r.isElite() && !elite;
			}
		}
		if (goal.isEmpty())
		{
			return "Click a slot to set a goal";
		}
		if (all)
		{
			return "All of " + title.toLowerCase(Locale.ENGLISH) + " is yours";
		}
		if (!pointsKnown)
		{
			return Format.number(left) + " points for the rest";
		}
		int wanted = 0;
		for (Reward r : goal)
		{
			wanted += owned.contains(r) || r.isElite() && !elite ? 0 : 1;
		}
		if (points >= left && buyable.size() == wanted)
		{
			return locked ? "Points enough; the diary is due" : "Enough points for the rest now";
		}
		if (buyable.size() == 1)
		{
			return "Teal: buy the " + buyable.iterator().next().getShortTitle().toLowerCase(Locale.ENGLISH) + " now";
		}
		if (!buyable.isEmpty())
		{
			return "Teal: these " + buyable.size() + " can be bought now";
		}
		return wanted == 0 ? "The rest needs the hard diary" : "Not enough points for a piece yet";
	}

	private void paintSlot(Graphics2D g, Slot s, int x, int y, FontMetrics small)
	{
		Reward r = s.reward;
		Look look = r == null ? null : look(r, goal, owned, buyable, elite);
		RoundRectangle2D well = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, SLOT_W - 1, SLOT_H - 1, 7, 7);
		g.setPaint(new GradientPaint(0, y, Theme.INK_DEEP, 0, y + SLOT_H, Theme.mix(Theme.INK_DEEP, Theme.CARD, 0.6)));
		g.fill(well);
		Color rim = look == null ? Theme.alpha(Theme.STROKE_SOFT, 120)
			: look == Look.OWNED ? Theme.GOLD
			: look == Look.CAN_BUY ? Theme.TEAL
			: look == Look.WANTED ? Theme.GOLD_DIM
			: look == Look.LOCKED ? Theme.BLOCKED : Theme.STROKE_SOFT;
		g.setColor(rim);
		g.setStroke(new BasicStroke(look == Look.OWNED || look == Look.CAN_BUY ? 1.5f : 1f));
		g.draw(well);
		g.setStroke(new BasicStroke(1f));
		if (r == null)
		{
			return;
		}
		BufferedImage icon = icons == null ? null : icons.get(r.getIcon(), repaint);
		if (icon != null)
		{
			Composite was = g.getComposite();
			float alpha = look == Look.OWNED || look == Look.CAN_BUY ? 1f : look == Look.NONE ? 0.22f : 0.5f;
			g.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
			g.drawImage(icon, x + (SLOT_W - icon.getWidth()) / 2, y + (SLOT_H - icon.getHeight()) / 2, null);
			g.setComposite(was);
		}
		if (look == Look.OWNED)
		{
			// A small gilt tick in the corner.
			g.setStroke(new BasicStroke(1.6f));
			g.setColor(Theme.INK_DEEP);
			g.drawPolyline(new int[]{x + SLOT_W - 11, x + SLOT_W - 8, x + SLOT_W - 3}, new int[]{y + SLOT_H - 8, y + SLOT_H - 5, y + SLOT_H - 11}, 3);
			g.setColor(Theme.GREEN);
			g.setStroke(new BasicStroke(1.2f));
			g.drawPolyline(new int[]{x + SLOT_W - 11, x + SLOT_W - 8, x + SLOT_W - 3}, new int[]{y + SLOT_H - 9, y + SLOT_H - 6, y + SLOT_H - 12}, 3);
			g.setStroke(new BasicStroke(1f));
		}
		else if (look == Look.WANTED || look == Look.CAN_BUY)
		{
			// The points saved toward it, as a bar along the slot's foot.
			// A piece waiting its turn counts only what is left once the pieces before it in the order are bought.
			double share = look == Look.CAN_BUY ? 1 : pointsKnown ? saved(r, goal, owned, points, elite) : 0;
			int bw = SLOT_W - 8;
			g.setColor(Theme.alpha(Theme.INK_DEEP, 220));
			g.fillRect(x + 4, y + SLOT_H - 5, bw, 2);
			g.setColor(look == Look.CAN_BUY ? Theme.TEAL : Theme.progressColor(share));
			g.fillRect(x + 4, y + SLOT_H - 5, (int) Math.round(bw * share), 2);
		}
		else if (look == Look.LOCKED)
		{
			String lock = "diary";
			g.setColor(Theme.BLOCKED);
			g.drawString(lock, x + (SLOT_W - small.stringWidth(lock)) / 2, y + SLOT_H - 3);
		}
	}
}

package com.codex.pestcontrol.ui;

import java.awt.Color;
import java.awt.GradientPaint;
import java.awt.Graphics2D;
import java.awt.geom.RoundRectangle2D;
import java.awt.image.BufferedImage;

/** The dark slot an item sits in, like a bank slot. */
final class Well
{
	static final int SIZE = 32;

	private Well()
	{
	}

	static void paint(Graphics2D g, int x, int y, BufferedImage icon, Color rim, boolean faded)
	{
		RoundRectangle2D well = new RoundRectangle2D.Float(x + 0.5f, y + 0.5f, SIZE + 4, SIZE - 1, 7, 7);
		g.setPaint(new GradientPaint(0, y, Theme.INK_DEEP, 0, y + SIZE, Theme.mix(Theme.INK_DEEP, Theme.CARD, 0.6)));
		g.fill(well);
		g.setColor(rim == null ? Theme.STROKE_SOFT : rim);
		g.draw(well);
		if (icon != null)
		{
			Graphics2D ig = (Graphics2D) g.create();
			if (faded)
			{
				ig.setComposite(java.awt.AlphaComposite.getInstance(java.awt.AlphaComposite.SRC_OVER, 0.4f));
			}
			ig.drawImage(icon, x + 2 + (SIZE - icon.getWidth()) / 2, y + (SIZE - icon.getHeight()) / 2 + 1, null);
			ig.dispose();
		}
	}
}

package com.codex.pestcontrol;

import static org.junit.Assert.assertEquals;
import com.codex.pestcontrol.core.Outlook;
import com.codex.pestcontrol.core.Reward;
import java.util.EnumSet;
import org.junit.Test;

/** The plaque's goal line agrees with the panel and the void card about the diary. */
public class PlaqueGoalTest
{
	@Test
	public void pointsForDiaryLockedPiecesDoNotSendThePlayerToTheShop()
	{
		// Only the elite top is left and the points cover it, but the hard diary is not done.
		Outlook o = Outlook.of(EnumSet.of(Reward.TOP, Reward.ELITE_TOP), EnumSet.of(Reward.TOP), 300, 5, 3, false);
		assertEquals("Points enough; the diary is due", CodexPestControlPlugin.goalDetail(o, false));
		assertEquals("Enough for all of it: visit the reward shop", CodexPestControlPlugin.goalDetail(o, true));
	}

	@Test
	public void otherwiseTheLineIsAsBefore()
	{
		Outlook done = Outlook.of(EnumSet.of(Reward.TOP), EnumSet.of(Reward.TOP), 10, 5, 3, false);
		assertEquals("Every piece is yours", CodexPestControlPlugin.goalDetail(done, false));
		Outlook shy = Outlook.of(EnumSet.of(Reward.TOP), EnumSet.noneOf(Reward.class), 240, 5, 3, false);
		assertEquals("10 to go, about 2 games", CodexPestControlPlugin.goalDetail(shy, false));
	}

	@Test
	public void pointsThatAlreadyBuyAPieceSaySoFirst()
	{
		Outlook part = Outlook.of(EnumSet.of(Reward.TOP, Reward.ROBE, Reward.MELEE_HELM), EnumSet.noneOf(Reward.class), 412, 5, 3, false);
		assertEquals("buy the top now; 288 to go, about 58 games", CodexPestControlPlugin.goalDetail(part, false));
		Outlook two = Outlook.of(EnumSet.of(Reward.MELEE_HELM, Reward.MAGE_HELM, Reward.TOP), EnumSet.noneOf(Reward.class), 400, 5, 3, false);
		assertEquals("buy 2 pieces now; 250 to go, about 50 games", CodexPestControlPlugin.goalDetail(two, false));
	}
}

package com.codex.pestcontrol;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;
import java.lang.reflect.Field;
import java.lang.reflect.Method;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import org.junit.Test;

/**
 * Every setting reads well in RuneLite's config panel: a short name, one plain sentence saying
 * what it does, a section it belongs in, and its own place in that section's order.
 */
public class SettingsTest
{
	@Test
	public void everySettingIsNamedAndExplainedInOneSentence()
	{
		Set<String> sections = new HashSet<>();
		for (Field f : CodexPestControlConfig.class.getDeclaredFields())
		{
			ConfigSection s = f.getAnnotation(ConfigSection.class);
			if (s != null)
			{
				sections.add(f.getName());
				assertTrue(s.description().length() > 0);
			}
		}
		Set<String> keys = new HashSet<>();
		Set<String> names = new HashSet<>();
		Map<String, Set<Integer>> places = new HashMap<>();
		int items = 0;
		for (Method m : CodexPestControlConfig.class.getDeclaredMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item == null)
			{
				continue;
			}
			items++;
			String where = item.keyName() + ": ";
			assertTrue(where + "key used once", keys.add(item.keyName()));
			assertTrue(where + "name used once", names.add(item.name()));
			assertTrue(where + "a short name", item.name().length() > 0 && item.name().length() <= 28);
			String d = item.description();
			assertTrue(where + "described", d.length() >= 20);
			assertTrue(where + "one sentence, no full stop: " + d, !d.endsWith(".") && !d.matches(".*[.!?] [A-Z].*"));
			assertTrue(where + "starts with a capital", Character.isUpperCase(d.charAt(0)));
			assertFalse(where + "in a section", item.section().isEmpty());
			assertTrue(where + "a known section", sections.contains(item.section()) || sectionValue(item.section()));
			assertTrue(where + "its own place in its section",
				places.computeIfAbsent(item.section(), k -> new HashSet<>()).add(item.position()));
		}
		assertTrue(items > 0);
		assertNotNull(sections);
	}

	/** A section is named by the value of its field, which may differ from the field's name. */
	private static boolean sectionValue(String value)
	{
		for (Field f : CodexPestControlConfig.class.getDeclaredFields())
		{
			try
			{
				if (f.getAnnotation(ConfigSection.class) != null && value.equals(f.get(null)))
				{
					return true;
				}
			}
			catch (IllegalAccessException e)
			{
				return false;
			}
		}
		return false;
	}

	@Test
	public void choicesReadAsWords()
	{
		for (Method m : CodexPestControlConfig.class.getDeclaredMethods())
		{
			if (m.getAnnotation(ConfigItem.class) != null && m.getReturnType().isEnum())
			{
				for (Object choice : m.getReturnType().getEnumConstants())
				{
					String shown = choice.toString();
					// "AT_THE_BANK" or "ALWAYS" is the code's name for a choice, not words a player reads.
					assertFalse(m.getName() + " shows " + shown, shown.length() > 1 && shown.equals(shown.toUpperCase()));
					assertEquals(m.getName() + " shows " + shown, shown.trim(), shown);
				}
			}
		}
	}

	@Test
	public void savedSettingsKeepTheirKeys()
	{
		// A setting's key is where its value is saved: renaming one quietly resets it for every player who changed it.
		// Every key on main and every one added since is pinned.
		Set<String> keys = new HashSet<>();
		for (Method m : CodexPestControlConfig.class.getMethods())
		{
			ConfigItem item = m.getAnnotation(ConfigItem.class);
			if (item != null)
			{
				keys.add(item.keyName());
			}
		}
		for (String key : new String[]{"announce", "gameSummary", "knightWarn", "lander", "markCandidates", "markPortal", "markShop", "nameOnCard", "notifyKnight", "notifyShield", "notifyStart", "plaque", "voidCheck"})
		{
			assertTrue(key, keys.contains(key));
		}
	}
}

package com.codex.pestcontrol.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import java.util.List;
import org.junit.Test;

public class AlertsTest
{
	@Test
	public void portalsOpenWhenTheGameIsFirstSeenAreNotNews()
	{
		Battle b = new Battle();
		b.foundOpen(Portal.PURPLE);
		Alerts a = new Alerts();
		assertEquals(Alerts.Kind.START, a.start(b).getKind());
		assertTrue(a.check(b, 60).isEmpty());
	}

	@Test
	public void eachShieldSeenDroppingNotifiesOnceAndNamesWhatIsNext()
	{
		Battle b = new Battle();
		Alerts a = new Alerts();
		a.start(b);
		b.tick();
		b.shieldDropped(Portal.PURPLE);
		b.shieldDropped(Portal.PURPLE);
		List<Alerts.Alert> out = a.check(b, 60);
		assertEquals(1, out.size());
		assertEquals("Pest Control: the purple shield is down (west gate)", out.get(0).getMessage());
		assertTrue(a.check(b, 60).isEmpty());
		b.shieldDropped(Portal.BLUE);
		// Purple then blue leaves one order: yellow, then red.
		out = a.check(b, 60);
		assertEquals("Pest Control: the blue shield is down (east gate); yellow is next", out.get(0).getMessage());
	}

	@Test
	public void aPortalSeenFallingWithItsDropMissedIsNotAShieldAlert()
	{
