		Alerts a = new Alerts();
		a.start(b);
		b.tick();
		b.shieldDropped(Portal.YELLOW);
		a.resume(b);
		assertTrue(a.check(b, 60).isEmpty());
	}
}

package com.codex.pestcontrol.core;

import static org.junit.Assert.assertEquals;
