	@Test
	public void theChatNamesWhatThePointsBuyAndNeverALockedPiece()
	{
		java.util.Set<Reward> goal = EnumSet.copyOf(Goal.ELITE.getRewards());
		java.util.Set<Reward> owned = EnumSet.of(Reward.GLOVES, Reward.RANGER_HELM);
		java.util.Set<Reward> locked = EnumSet.of(Reward.ELITE_TOP, Reward.ELITE_ROBE);
		Outlook before = Outlook.of(goal, owned, 190, 5, 7, true);
		Outlook after = Outlook.of(goal, owned, 410, 5, 7, true);
		// Only the elite top and robe are left and the diary locks both: no "visit the shop".
		assertNull(GameSummary.announcement(before, after, locked));
		assertEquals("your 410 points now cover everything left in your goal. Visit the Void Knights' reward shop.",
			GameSummary.announcement(before, after, EnumSet.noneOf(Reward.class)));
		// With an open piece beside a locked one, the line names the open piece.
		java.util.Set<Reward> mixed = EnumSet.of(Reward.ELITE_TOP, Reward.TOP);
		assertEquals("your 260 points now cover the void knight top.", GameSummary.announcement(
			Outlook.of(mixed, EnumSet.noneOf(Reward.class), 100, 5, 7, true), Outlook.of(mixed, EnumSet.noneOf(Reward.class), 260, 5, 7, true),
			EnumSet.of(Reward.ELITE_TOP)));
	}
}

package com.codex.pestcontrol.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import org.junit.Test;

public class GameWatchTest
{
	@Test
	public void aGameStartsSettlesAndFinishes()
	{
		GameWatch w = new GameWatch();
		assertEquals(GameWatch.Act.NONE, w.tick(false));
		assertEquals(GameWatch.Act.START, w.tick(true));
		assertEquals(GameWatch.Act.NONE, w.tick(true));
		assertEquals(GameWatch.Act.SETTLE, w.tick(false));
		assertEquals(GameWatch.Act.NONE, w.tick(false));
		assertEquals(GameWatch.Act.NONE, w.tick(false));
		// The fourth tick without the bar, counting the one it went on, as the closing messages are in.
		assertEquals(GameWatch.Act.FINISH, w.tick(false));
		assertEquals(GameWatch.Act.NONE, w.tick(false));
		assertFalse(w.isBusy());
	}

	@Test
	public void theBarComingBackWhileSettlingCarriesTheSameGameOn()
	{
		GameWatch w = new GameWatch();
		w.tick(true);
		// A dropped connection the client got back: the bar is missing for a couple of ticks.
		assertEquals(GameWatch.Act.SETTLE, w.tick(false));
		assertEquals(GameWatch.Act.NONE, w.tick(false));
		assertEquals("not a fresh game with the damage gone", GameWatch.Act.RESUME, w.tick(true));
		assertEquals(GameWatch.Act.SETTLE, w.tick(false));
	}

	@Test
	public void afterAResetTheNextBarIsANewGame()
	{
		GameWatch w = new GameWatch();
		w.tick(true);
		w.tick(false);
		w.reset();
		assertEquals(GameWatch.Act.START, w.tick(true));
	}
}

package com.codex.pestcontrol.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.ArrayList;
import java.util.List;
import org.junit.Test;

public class HabitTest
{
	private static final long MIN = 60_000L;
	private static final long DAY = 24 * 60 * MIN;

	/** Six games of nine minutes, each a minute in the lander after the last, from the given day. */
	private static void sitting(List<GameRecord> games, long day)
	{
		for (int i = 0; i < 6; i++)
		{
			long end = day * DAY + (i * 10 + 9) * MIN;
			games.add(new GameRecord(end, Boat.VETERAN, GameRecord.Result.WON, 5, 120, 9 * 60));
		}
	}

	@Test
	public void twoSittingsAWeekPutTwentyFourGamesTwoWeeksAway()
	{
		List<GameRecord> games = new ArrayList<>();
		for (long day : new long[]{100, 103, 107, 110})
		{
			sitting(games, day);
		}
		long now = 114 * DAY;
		Habit h = Habit.of(games, true, now);
		assertTrue(h.isKnown());
		// Each sitting runs 59 minutes for six games; two a week.
		assertEquals(2 * 59 / 60.0, h.hoursPerWeek(), 1e-9);
		// Twenty-four games is four sittings: two weeks.
		assertEquals(now + 14 * DAY, h.afterGames(24, now), 60_000);
	}

	@Test
	public void aFirstBusyWeekendIsSpreadOverAWeekUnlessOlderGamesWereDropped()
	{
		List<GameRecord> games = new ArrayList<>();
		sitting(games, 100);
		sitting(games, 101);
		long now = 102 * DAY;
		assertEquals(2 * 59 / 60.0, Habit.of(games, true, now).hoursPerWeek(), 1e-9);
		// With older games dropped from the logbook, the two days kept are all that is known.
		assertEquals(2 * 59 / 60.0 * 3.5, Habit.of(games, false, now).hoursPerWeek(), 1e-9);
	}

	@Test
	public void oneSittingSaysNothing()
	{
		List<GameRecord> games = new ArrayList<>();
		sitting(games, 100);
		Habit h = Habit.of(games, true, 101 * DAY);
		assertFalse(h.isKnown());
		assertEquals(-1, h.afterGames(5, 101 * DAY));
	}
}

package com.codex.pestcontrol.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.EnumSet;
import org.junit.Test;

public class LogbookTest
{
	private static final long MIN = 60_000L;

	@Test
	public void assumesTheBoatUntilThreeGames()
	{
		Logbook log = new Logbook();
		assertEquals(5, log.pointsPerGame(Boat.VETERAN), 0);
		log.record(new GameRecord(10 * MIN, Boat.VETERAN, GameRecord.Result.WON, 5, 120, 150));
		log.record(new GameRecord(14 * MIN, Boat.VETERAN, GameRecord.Result.LOST, 0, 80, 200));
		assertFalse(log.isMeasured());
		log.record(new GameRecord(18 * MIN, Boat.VETERAN, GameRecord.Result.WON, 5, 90, 160));
		assertTrue(log.isMeasured());
		assertEquals(10 / 3.0, log.pointsPerGame(Boat.VETERAN), 1e-9);
		assertEquals(4, log.minutesPerGame(), 1e-9);
		assertEquals(3, log.getPlayed());
		assertEquals(2, log.getWon());
		assertEquals(10, log.getEarned());
	}

	@Test
	public void breaksAndLeftGamesDoNotCount()
	{
		Logbook log = new Logbook();
		log.record(new GameRecord(0, Boat.NOVICE, GameRecord.Result.WON, 3, 60, 180));
		log.record(new GameRecord(60 * MIN, Boat.NOVICE, GameRecord.Result.WON, 3, 60, 180));
		log.record(new GameRecord(61 * MIN, Boat.NOVICE, GameRecord.Result.LEFT, 0, 10, 30));
		assertEquals(2, log.getPlayed());
		// Only one break-length gap, so the lander time is assumed.
		assertEquals(4, log.minutesPerGame(), 1e-9);
	}

	@Test
	public void keepsTheNewestGames()
	{
		Logbook log = new Logbook();
		for (int i = 0; i < Logbook.KEEP + 5; i++)
		{
			log.record(new GameRecord(i * MIN, Boat.NOVICE, GameRecord.Result.WON, 3, 60, 100));
		}
		assertEquals(Logbook.KEEP, log.getGames().size());
		assertEquals(Logbook.KEEP + 5, log.getPlayed());
	}

	@Test
	public void goalToggles()
	{
		Logbook log = new Logbook();
		assertEquals(EnumSet.copyOf(Goal.MELEE.getRewards()), log.getGoal());
		log.toggle(Reward.MACE);
		assertTrue(log.getGoal().contains(Reward.MACE));
		log.toggle(Reward.MACE);
		assertFalse(log.getGoal().contains(Reward.MACE));
		assertTrue(log.seeOwned(EnumSet.of(Reward.TOP), 5));
		assertFalse(log.seeOwned(EnumSet.of(Reward.TOP), 6));
	}
}

