package com.codex.pestcontrol.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.EnumSet;
import org.junit.Test;

public class OutlookTest
{
	@Test
	public void voidSetCostsEightHundredFifty()
	{
		Outlook o = Outlook.of(EnumSet.copyOf(Goal.MELEE.getRewards()), EnumSet.noneOf(Reward.class), 100, 4, 4, false);
		assertEquals(850, o.getCost());
		assertEquals(750, o.getRemaining());
		assertEquals(188, o.getGames());
		assertEquals(752, o.getMinutes(), 0.001);
		assertEquals(null, o.getNextBuy());
	}

	@Test
	public void ownedPiecesCostNothing()
	{
		Outlook o = Outlook.of(EnumSet.copyOf(Goal.RANGER.getRewards()), EnumSet.of(Reward.TOP, Reward.ROBE), 300, 5, 4, true);
		assertEquals(350, o.getCost());
		assertEquals(50, o.getRemaining());
		assertEquals(10, o.getGames());
		assertEquals(Reward.RANGER_HELM, o.getNextBuy());
		assertFalse(o.isComplete());
	}

	@Test
	public void affordableAndComplete()
	{
		Outlook o = Outlook.of(EnumSet.of(Reward.SEAL), EnumSet.noneOf(Reward.class), 20, 3, 4, false);
		assertTrue(o.isAffordable());
		assertEquals(0, o.getGames());
		Outlook done = Outlook.of(EnumSet.of(Reward.SEAL), EnumSet.of(Reward.SEAL), 20, 3, 4, false);
		assertTrue(done.isComplete());
		assertEquals(1, done.progress(), 0);
	}

	@Test
	public void unknownPointsStillGiveTheCostButNoGames()
	{
		Outlook o = Outlook.of(EnumSet.copyOf(Goal.ALL.getRewards()), EnumSet.noneOf(Reward.class), -1, 5, 4, false);
		assertFalse(o.isPointsKnown());
		assertEquals(1250, o.getRemaining());
		assertEquals(-1, o.getGames());
		assertEquals(-1, o.getMinutes(), 0);
	}

	@Test
	public void presetsAreRecognised()
	{
		assertEquals(Goal.ELITE, Goal.matching(EnumSet.copyOf(Goal.ELITE.getRewards())));
		assertEquals(null, Goal.matching(EnumSet.of(Reward.MACE)));
	}

	@Test
	public void thePointsLightTheSetThatSpendsTheMostOfThem()
	{
		// 400 points toward a top (250) and two helms (200 each): the dearest piece first bought the
		// top and left 150, short of either helm. Both helms spend all 400, so they come first.
		Outlook o = Outlook.of(EnumSet.of(Reward.TOP, Reward.MELEE_HELM, Reward.RANGER_HELM), EnumSet.noneOf(Reward.class), 400, 4, 3, true);
		assertEquals(EnumSet.of(Reward.MELEE_HELM, Reward.RANGER_HELM), o.buyableNow(null));
		java.util.List<Outlook.Milestone> m = o.milestones(null);
		assertEquals(0, m.get(0).getGames());
		assertEquals(0, m.get(1).getGames());
		assertEquals(Reward.TOP, m.get(2).getReward());
		assertEquals(650, m.get(2).getTotal());
		assertEquals((int) Math.ceil(250 / 4.0), m.get(2).getGames());
		assertTrue(o.buyableNow(null).contains(o.getNextBuy()));
	}

	@Test
	public void theBestSetLeavesLockedPiecesOut()
	{
		// The elite top would make 400 with the helm, but the diary keeps it locked: the helm and
		// the gloves (350) are the most the points buy.
		java.util.Set<Reward> locked = EnumSet.of(Reward.ELITE_TOP);
		Outlook o = Outlook.of(EnumSet.of(Reward.ELITE_TOP, Reward.RANGER_HELM, Reward.GLOVES), EnumSet.noneOf(Reward.class), 400, 4, 3, true);
		assertEquals(EnumSet.of(Reward.RANGER_HELM, Reward.GLOVES), o.buyableNow(locked));
		assertEquals(Reward.ELITE_TOP, o.milestones(locked).get(2).getReward());
	}

	@Test
	public void gamesAreNotCountedBeforeThePointsAreRead()
	{
		// Unread points are not zero points: a player boarding with 600 is not 213 games away.
		Outlook o = Outlook.of(EnumSet.copyOf(Goal.MELEE.getRewards()), EnumSet.noneOf(Reward.class), -1, 4, 4, false);
		assertFalse(o.isPointsKnown());
		assertEquals(-1, o.getGames());
		assertFalse(o.isGamesKnown());
		for (Outlook.Milestone m : o.milestones(null))
		{
			assertEquals(m.getReward() + " is not timed", -1, m.getGames());
		}
		assertTrue(Outlook.of(EnumSet.copyOf(Goal.MELEE.getRewards()), EnumSet.noneOf(Reward.class), 0, 4, 4, false).isGamesKnown());
	}
}

package com.codex.pestcontrol.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import java.util.ArrayList;
import java.util.EnumSet;
import java.util.List;
import org.junit.Test;

public class PlannerTest
{
	private static final long MIN = 60_000L;

	@Test
	public void piecesAreBoughtCheapestFirstWithLockedOnesLast()
	{
		Outlook o = Outlook.of(EnumSet.copyOf(Goal.ELITE.getRewards()), EnumSet.noneOf(Reward.class), 100, 4, 6, true);
		List<Outlook.Milestone> m = o.milestones(EnumSet.of(Reward.ELITE_TOP, Reward.ELITE_ROBE));
		assertEquals(Reward.GLOVES, m.get(0).getReward());
		assertEquals(Reward.RANGER_HELM, m.get(1).getReward());
		assertEquals(Reward.ELITE_TOP, m.get(2).getReward());
		// Gloves 150 with 100 held: 50 short at 4 a game is 13 games.
		assertEquals(13, m.get(0).getGames());
		assertEquals(13 * 6.0, m.get(0).getMinutes(), 1e-9);
		assertEquals(750, m.get(3).getTotal());
		assertEquals((int) Math.ceil(650 / 4.0), m.get(3).getGames());
	}

	@Test
	public void thePieceTheOutlookSaysYouCanBuyNowIsFirstInTheBuyOrder()
	{
		// 412 points toward the melee set with the gloves owned: the top (250) and the helm (200)
		// are each affordable, not both. The outlook names the top, so the buy order must start there.
		Outlook o = Outlook.of(EnumSet.copyOf(Goal.MELEE.getRewards()), EnumSet.of(Reward.GLOVES), 412, 4.2, 4, true);
		List<Outlook.Milestone> m = o.milestones(null);
		assertEquals(o.getNextBuy(), m.get(0).getReward());
		assertEquals(Reward.TOP, m.get(0).getReward());
		assertEquals(0, m.get(0).getGames());
		// Then the helm: 450 in all, 38 short at 4.2 a game.
		assertEquals(Reward.MELEE_HELM, m.get(1).getReward());
		assertEquals(10, m.get(1).getGames());
		assertEquals(Reward.ROBE, m.get(2).getReward());
	}

	@Test
	public void piecesAlreadyAffordableAreNow()
	{
		Outlook o = Outlook.of(EnumSet.of(Reward.SEAL, Reward.GLOVES), EnumSet.noneOf(Reward.class), 200, 5, 5, true);
		List<Outlook.Milestone> m = o.milestones(null);
		assertEquals(0, m.get(0).getGames());
		assertEquals(0, m.get(1).getGames());
	}

	private static GameRecord game(long minute, Boat boat, GameRecord.Result r, int points, int damage)
	{
		return new GameRecord(minute * MIN, boat, r, points, damage, 240);
	}

	@Test
	public void eachLanderIsRatedFromItsOwnGames()
	{
		List<GameRecord> games = new ArrayList<>();
		// Four veteran games six minutes apart, one lost; three intermediate games four minutes apart.
		games.add(game(0, Boat.VETERAN, GameRecord.Result.WON, 5, 120));
		games.add(game(6, Boat.VETERAN, GameRecord.Result.LOST, 0, 90));
		games.add(game(12, Boat.VETERAN, GameRecord.Result.WON, 5, 110));
		games.add(game(18, Boat.VETERAN, GameRecord.Result.WON, 5, 130));
		games.add(game(100, Boat.INTERMEDIATE, GameRecord.Result.WON, 4, 140));
		games.add(game(104, Boat.INTERMEDIATE, GameRecord.Result.WON, 4, 150));
		games.add(game(108, Boat.INTERMEDIATE, GameRecord.Result.WON, 4, 160));
		List<Landers.Line> lines = Landers.of(games);
		assertEquals(2, lines.size());
		Landers.Line inter = lines.get(0);
		Landers.Line vet = lines.get(1);
		assertEquals(Boat.INTERMEDIATE, inter.getBoat());
		assertEquals(3.75, vet.getPointsPerGame(), 1e-9);
		assertEquals(6, vet.getMinutesPerGame(), 1e-9);
		assertEquals(37.5, vet.pointsPerHour(), 1e-9);
		assertEquals(60, inter.pointsPerHour(), 1e-9);
		assertEquals(0.75, vet.winRate(), 1e-9);
		assertEquals(Boat.INTERMEDIATE, Landers.best(lines, 110).getBoat());
		// A level 80 cannot board the veteran lander, and two games are not enough to rate one.
		assertEquals(Boat.INTERMEDIATE, Landers.best(lines, 80).getBoat());
		assertNull(Landers.best(Landers.of(games.subList(4, 6)), 110));
	}

	@Test
	public void aLanderYouCannotBoardIsNeverTheBest()
	{
		List<GameRecord> games = new ArrayList<>();
		// The veteran lander pays far better here, but needs combat 100.
		for (int i = 0; i < 3; i++)
		{
			games.add(game(i * 5, Boat.VETERAN, GameRecord.Result.WON, 5, 120));
		}
		for (int i = 0; i < 3; i++)
		{
			games.add(game(100 + i * 8, Boat.INTERMEDIATE, GameRecord.Result.WON, 4, 140));
		}
		List<Landers.Line> lines = Landers.of(games);
		assertEquals(Boat.VETERAN, Landers.best(lines, 110).getBoat());
		assertEquals(Boat.INTERMEDIATE, Landers.best(lines, 80).getBoat());
	}

	@Test
	public void gamesLeftEarlyBreakTheChainOfGaps()
	{
		List<GameRecord> games = new ArrayList<>();
		games.add(game(0, Boat.NOVICE, GameRecord.Result.WON, 3, 80));
		games.add(game(3, null, GameRecord.Result.LEFT, 0, 10));
		games.add(game(9, Boat.NOVICE, GameRecord.Result.WON, 3, 80));
		games.add(game(14, Boat.NOVICE, GameRecord.Result.WON, 3, 80));
		Landers.Line l = Landers.of(games).get(0);
		assertEquals(3, l.getGames());
		// Only one back-to-back gap (5 minutes): not enough, so game length plus the lander wait.
		assertEquals((240 + 60) / 60.0, l.getMinutesPerGame(), 1e-9);
	}
}

package com.codex.pestcontrol.core;

import static org.junit.Assert.assertEquals;
import org.junit.Test;

public class PointsToTest
{
	@Test
	public void theExperienceTableIsTheGames()
	{
		assertEquals(0, Experience.xpFor(1));
		assertEquals(83, Experience.xpFor(2));
		assertEquals(737_627, Experience.xpFor(70));
		assertEquals(13_034_431, Experience.xpFor(99));
		assertEquals(1, Experience.levelFor(82));
		assertEquals(70, Experience.levelFor(814_444));
		assertEquals(99, Experience.levelFor(200_000_000));
	}

	@Test
	public void pointsToALevelBuyTheBiggestBundlesThatFit()
	{
		// Prayer 70 to 71 is 76,818 xp at 144 a point: four hundreds (15,840 each), nine tens (1,454) and three ones.
		assertEquals(493, Experience.pointsTo(Experience.Skill.PRAYER, Experience.xpFor(70), 71));
		assertEquals(0, Experience.pointsTo(Experience.Skill.PRAYER, Experience.xpFor(71), 70));
		assertEquals("below 25 the shop sells nothing", -1, Experience.pointsTo(Experience.Skill.ATTACK, Experience.xpFor(20), 30));
	}

	@Test
	public void eachPurchaseIsPaidAtTheLevelItIsMadeAt()
	{
		// Points to go 60 to 80 in Attack cost less than at the level-60 rate throughout.
		int points = Experience.pointsTo(Experience.Skill.ATTACK, Experience.xpFor(60), 80);
		long atSixty = (Experience.xpFor(80) - Experience.xpFor(60)) / (Experience.perPoint(Experience.Skill.ATTACK, 60) * 110L / 100);
		assertEquals(true, points < atSixty);
	}

	@Test
	public void experiencePointsComeAfterTheGoalStillToBuy()
	{
		// 100 points held toward a 250-point top: 150 more go to the top before any buy experience.
		Outlook saving = Outlook.of(java.util.EnumSet.of(Reward.TOP), java.util.EnumSet.noneOf(Reward.class), 100, 5, 10, true);
		assertEquals((150 + 200) / 5, Experience.gamesFor(saving, 200));
		// With the top covered, the 40 spare points count first.
		Outlook covered = Outlook.of(java.util.EnumSet.of(Reward.TOP), java.util.EnumSet.noneOf(Reward.class), 290, 5, 10, true);
		assertEquals(0, Experience.gamesFor(covered, 40));
		assertEquals(2, Experience.gamesFor(covered, 50));
		// Points not seen yet: they are not zero, so no games are counted until they are read.
		Outlook unseen = Outlook.of(java.util.EnumSet.noneOf(Reward.class), java.util.EnumSet.noneOf(Reward.class), -1, 5, 10, true);
		assertEquals(-1, Experience.gamesFor(unseen, 20));
	}
}

