package com.codex.pestcontrol.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.util.List;
import java.util.Map;
import org.junit.Test;

/** A damaged field costs only that field, whatever shape the damage takes. */
public class SalvageTest
{
	private static final Gson GSON = new Gson();

	static final class Saved
	{
		int kept;
		List<String> names;
		Map<String, Integer> counts;
	}

	@Test
	public void aListWhereAMapBelongsCostsOnlyThatField()
	{
		// A map where the list belongs once emptied every field, as "{}" does not read as a list.
		Saved s = Salvage.read(GSON, "{\"kept\":5,\"names\":{\"x\":1},\"counts\":{\"a\":1}}", Saved.class);
		assertEquals(5, s.kept);
		assertNull(s.names);
		assertEquals(1, (int) s.counts.get("a"));
		s = Salvage.read(GSON, "{\"kept\":5,\"names\":[\"a\"],\"counts\":[1,2]}", Saved.class);
		assertEquals(5, s.kept);
		assertEquals("a", s.names.get(0));
		// Gson reads a map from a list of pairs, so this one comes back empty rather than missing.
		assertTrue(s.counts == null || s.counts.isEmpty());
	}

	@Test
	public void badEntriesCostOnlyThemselves()
	{
		Saved s = Salvage.read(GSON, "{\"kept\":\"five\",\"names\":[\"a\",{},\"b\"],\"counts\":{\"a\":1,\"b\":\"x\"}}", Saved.class);
		assertEquals(0, s.kept);
		assertEquals(2, s.names.size());
		assertEquals(1, s.counts.size());
		assertTrue(Salvage.read(GSON, "[1]", Saved.class) == null);
	}

	@Test
	public void aSaveThisVersionKeepsWholeLosesNothing()
	{
		String own = "{\"kept\":5,\"names\":[\"a\"],\"counts\":{\"a\":1}}";
		assertFalse(Salvage.wouldLose(GSON, own, Salvage.read(GSON, own, Saved.class)));
		// An older save that lacks a field, or nothing saved at all, loses nothing either.
		String older = "{\"kept\":5}";
		assertFalse(Salvage.wouldLose(GSON, older, Salvage.read(GSON, older, Saved.class)));
		assertFalse(Salvage.wouldLose(GSON, null, null));
		assertFalse(Salvage.wouldLose(GSON, "", null));
	}

	@Test
	public void aNewerOrDamagedSaveWouldLoseWhatItHolds()
	{
		// A field a newer version added, a value of a shape this one cannot read, and garbage.
		String newer = "{\"kept\":5,\"names\":[\"a\"],\"added\":{\"x\":1}}";
		assertTrue(Salvage.wouldLose(GSON, newer, Salvage.read(GSON, newer, Saved.class)));
		String damaged = "{\"kept\":\"five\",\"names\":[\"a\",{},\"b\"]}";
		assertTrue(Salvage.wouldLose(GSON, damaged, Salvage.read(GSON, damaged, Saved.class)));
		assertTrue(Salvage.wouldLose(GSON, "{\"kept\":5", null));
	}
}

package com.codex.pestcontrol.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import com.google.gson.Gson;
import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import org.junit.Test;

/**
 * Reads exactly what the other Codex plugins save. {@code bank-steward-bankV1.json} is a copy of
 * the fixture Bank Steward's own BankSnapshotTest proves its writer produces;
 * {@code gear-roadmap-bank.json} was written by Gear Roadmap's own {@code Bank} class with Gson.
 */
public class SharedBankContractTest
{
	private static final Gson GSON = new Gson();

	static String fixture(String name) throws Exception
	{
		try (InputStream in = SharedBankContractTest.class.getResourceAsStream(name))
		{
			ByteArrayOutputStream out = new ByteArrayOutputStream();
			byte[] buf = new byte[4096];
			for (int n; (n = in.read(buf)) > 0; )
			{
				out.write(buf, 0, n);
			}
			return new String(out.toByteArray(), StandardCharsets.UTF_8).trim();
		}
	}

	@Test
	public void groupsAndKeysMatchTheWriters()
	{
		// CodexBankStewardConfig.GROUP and BankSnapshot.KEY; CodexGearRoadmapConfig.GROUP and BANK_KEY.
		assertEquals("codexbanksteward", SharedBank.STEWARD_GROUP);
		assertEquals("bankV1", SharedBank.STEWARD_KEY);
		assertEquals("codexgearroadmap", SharedBank.ROADMAP_GROUP);
		assertEquals("bank", SharedBank.ROADMAP_KEY);
	}

	@Test
	public void bankStewardSnapshotHoldsEveryItemWithItsCount() throws Exception
	{
		SharedBank bank = SharedBank.read(GSON, fixture("bank-steward-bankV1.json"), null);
		assertSame(SharedBank.Source.BANK_STEWARD, bank.getSource());
		assertTrue(bank.isComplete());
		assertEquals(1_760_000_000_000L, bank.getSavedAt());
		assertEquals(1, bank.count(26950));
		assertEquals(1, bank.count(11666));
		assertEquals(240, bank.count(385));
		assertEquals(1_234_567, bank.count(995));
		assertEquals(0, bank.count(4151));
	}

	@Test
	public void gearRoadmapBankIsTheFallbackAndOnlyHalfTheStory() throws Exception
	{
		String roadmap = fixture("gear-roadmap-bank.json");
		SharedBank bank = SharedBank.read(GSON, null, roadmap);
		assertSame(SharedBank.Source.GEAR_ROADMAP, bank.getSource());
		assertFalse(bank.isComplete());
		assertEquals(0, bank.getSavedAt());
		assertEquals(1, bank.count(26948));
		assertEquals(1, bank.count(8839));
		assertEquals(1_234_567, bank.count(995));
		assertEquals("it never saves a fresh sceptre", 0, bank.count(26950));

		// Bank Steward's wins when both are there, and an unreadable one falls through.
		assertSame(SharedBank.Source.BANK_STEWARD, SharedBank.read(GSON, fixture("bank-steward-bankV1.json"), roadmap).getSource());
		assertSame(SharedBank.Source.GEAR_ROADMAP, SharedBank.read(GSON, "{\"version\":1}", roadmap).getSource());
		assertSame(SharedBank.Source.GEAR_ROADMAP, SharedBank.read(GSON, "not json {", roadmap).getSource());
	}

	@Test
	public void nothingSavedIsNoBank()
	{
		assertNull(SharedBank.read(GSON, null, null));
		assertNull(SharedBank.read(GSON, "", "  "));
		assertNull(SharedBank.read(GSON, "[1,2]", "{\"coins\":5}"));
		// Odd values inside a readable snapshot are skipped, not fatal.
		SharedBank odd = SharedBank.read(GSON, "{\"items\":{\"x\":1,\"995\":\"many\",\"385\":-2,\"391\":3},\"truncated\":true}", null);
		assertEquals(1, odd.getItems().size());
		assertEquals(3, odd.count(391));
		assertFalse("a truncated snapshot may miss items", odd.isComplete());
	}
}

package com.codex.pestcontrol.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

public class SittingTest
{
	private static final long MIN = 60_000L;

	/** A ten minute game ending at the given minute. */
	private static GameRecord game(long endMinute, GameRecord.Result result, int points)
	{
		return new GameRecord(endMinute * MIN, Boat.VETERAN, result, points, result == GameRecord.Result.NO_POINTS ? 20 : 200, 600);
	}

	@Test
	public void aBreakEndsTheSittingAndLanderTimeCounts()
	{
		// An old game, then three games each ten minutes long with two minutes in the lander between.
		List<GameRecord> games = Arrays.asList(game(0, GameRecord.Result.WON, 5),
			game(100, GameRecord.Result.WON, 5), game(112, GameRecord.Result.NO_POINTS, 0), game(124, GameRecord.Result.WON, 5));
		Sitting s = Sitting.latest(games, 125 * MIN);
		assertEquals(3, s.getGames().size());
		assertTrue(s.isCurrent());
		assertEquals(3, s.getWon());
		assertEquals(1, s.getUnpaid());
		assertEquals(10, s.getPoints());
		// From minute 90 to 124: 34 minutes for 10 points.
		assertEquals(34 * MIN, s.spanMs());
		assertEquals(Math.round(10 * 60 / 34.0), s.pointsPerHour());
	}

	@Test
	public void anOldOrShortSitting()
	{
		Sitting old = Sitting.latest(Collections.singletonList(game(0, GameRecord.Result.WON, 5)), 600 * MIN);
		assertFalse(old.isCurrent());
		assertEquals("one game has no lander time to rate", 0, old.pointsPerHour());
		assertTrue(Sitting.latest(Collections.emptyList(), 0).isEmpty());
		// A game starting exactly fifteen minutes after the last ended still belongs.
		assertEquals(2, Sitting.latest(Arrays.asList(game(0, GameRecord.Result.WON, 5), game(25, GameRecord.Result.WON, 5)), 30 * MIN)
			.getGames().size());
		assertEquals(1, Sitting.latest(Arrays.asList(game(0, GameRecord.Result.WON, 5), game(26, GameRecord.Result.WON, 5)), 30 * MIN)
			.getGames().size());
	}
}

package com.codex.pestcontrol.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class TeamPaceTest
{
	/** Both side portals open; purple's health falls by the given amount a tick, blue's by another. */
	private static Battle twoOpen(int purpleStart, int purplePerTick, int blueStart, int bluePerTick, int ticks)
	{
		Battle b = new Battle();
		b.shieldDropped(Portal.PURPLE);
		b.shieldDropped(Portal.BLUE);
		for (int t = 0; t < ticks; t++)
		{
			b.tick();
			b.setHealth(Portal.PURPLE, purpleStart - purplePerTick * t);
			b.setHealth(Portal.BLUE, blueStart - bluePerTick * t);
		}
		return b;
	}

	@Test
	public void thePaceIsMeasuredFromTheHealthFalling()
	{
		Battle b = twoOpen(200, 4, 200, 0, 12);
		// 156 left at 4 a tick is 39 ticks, about 24 seconds.
		assertEquals((int) Math.ceil(156 / 4.0 * 0.6), b.secondsToFall(Portal.PURPLE));
		assertEquals(Battle.STALLED, b.secondsToFall(Portal.BLUE));
		assertEquals(-1, b.secondsToFall(Portal.RED));
	}

	@Test
	public void tooFewReadingsAreNotAPace()
	{
		Battle b = twoOpen(200, 4, 200, 0, 3);
		assertEquals(-1, b.secondsToFall(Portal.PURPLE));
	}

	@Test
	public void yourOwnHitsAreLeftOutOfTheTeamsPace()
	{
		Battle b = new Battle();
		b.shieldDropped(Portal.PURPLE);
		int hp = 200;
		for (int t = 0; t < 12; t++)
		{
			b.tick();
			b.setHealth(Portal.PURPLE, hp);
			// You alone hit it for 5 a tick; nobody else is there.
			b.addDamage(5, Portal.PURPLE);
			hp -= 5;
		}
		assertEquals(Battle.STALLED, b.secondsToFall(Portal.PURPLE));
	}

	@Test
	public void withPointsEarnedItSendsYouToThePortalHoldingTheGameUp()
	{
		Battle b = twoOpen(100, 5, 220, 0, 12);
		b.addDamage(60);
		Advice a = b.advise(null);
		assertEquals(Advice.Kind.ATTACK, a.getKind());
		assertEquals(Portal.BLUE, a.getPortal());
		assertTrue(a.getDetail(), a.getDetail().contains("holds the game up"));
	}

	@Test
	public void beforePointsTheWeakestStillComesFirst()
	{
		Battle b = twoOpen(100, 5, 220, 0, 12);
		assertEquals(Portal.PURPLE, b.advise(null).getPortal());
	}

	@Test
	public void twoPortalsFallingAtTheSamePaceDoNotPullYouAcross()
	{
		Battle b = twoOpen(100, 5, 110, 5, 12);
		b.addDamage(60);
		Advice a = b.advise(null);
		assertEquals(Portal.PURPLE, a.getPortal());
		assertTrue(a.getDetail(), a.getDetail().startsWith("Shield down"));
	}

	@Test
	public void theChoiceHoldsWhileTheGapIsSmall()
	{
		Battle b = new Battle();
		b.shieldDropped(Portal.PURPLE);
		b.shieldDropped(Portal.BLUE);
		b.addDamage(60);
		int p = 120;
		int q = 200;
		for (int t = 0; t < 12; t++)
		{
			b.tick();
			b.setHealth(Portal.PURPLE, p -= 6);
			b.setHealth(Portal.BLUE, q);
		}
		assertEquals(Portal.BLUE, b.advise(null).getPortal());
		// The team arrives at blue and wears it down fast; purple is now the slower, but only by a little.
		for (int t = 0; t < 18; t++)
		{
			b.tick();
			b.setHealth(Portal.PURPLE, p -= 1);
			b.setHealth(Portal.BLUE, q -= 6);
		}
		int purple = b.secondsToFall(Portal.PURPLE);
		int blue = b.secondsToFall(Portal.BLUE);
		assertTrue(purple + " vs " + blue, purple > blue && purple - blue < 12);
		assertEquals(Portal.BLUE, b.advise(null).getPortal());
		// Once purple lags clearly, the advice does move.
		for (int t = 0; t < 18; t++)
		{
			b.tick();
			b.setHealth(Portal.PURPLE, p);
			b.setHealth(Portal.BLUE, q -= 2);
		}
		assertEquals(Portal.PURPLE, b.advise(null).getPortal());
	}

	@Test
	public void aPortalJustOpenedIsNotStalledByItsShieldedReadings()
	{
		Battle b = new Battle();
		b.shieldDropped(Portal.PURPLE);
		b.addDamage(60);
		for (int t = 0; t < 12; t++)
		{
			b.tick();
			b.setHealth(Portal.PURPLE, 200 - 5 * t);
			// Blue sits behind its shield at full health.
			b.setHealth(Portal.BLUE, 250);
		}
		b.shieldDropped(Portal.BLUE);
		b.tick();
		b.setHealth(Portal.PURPLE, 140);
		b.setHealth(Portal.BLUE, 250);
		assertEquals(-1, b.secondsToFall(Portal.BLUE));
		assertEquals(Portal.PURPLE, b.advise(null).getPortal());
	}

	@Test
	public void aPortalOnlyYouAreHittingIsCalledYoursNotEmpty()
	{
		Battle b = new Battle();
		b.shieldDropped(Portal.PURPLE);
		b.shieldDropped(Portal.BLUE);
		b.addDamage(60);
		int hp = 200;
		for (int t = 0; t < 12; t++)
		{
			b.tick();
			b.setHealth(Portal.PURPLE, 150 - 6 * t);
			b.setHealth(Portal.BLUE, hp);
			b.addDamage(4, Portal.BLUE);
			hp -= 4;
		}
		assertTrue(b.isYoursAlone(Portal.BLUE));
		assertTrue(!b.isYoursAlone(Portal.PURPLE));
		// Nobody else is at blue, but you are: the advice must not say nobody is there.
		Advice a = b.advise(new Field().crowd(Portal.BLUE, 0).crowd(Portal.PURPLE, 6));
		assertEquals(Portal.BLUE, a.getPortal());
		assertTrue(a.getDetail(), a.getDetail().startsWith("Only you are"));
	}
}

package com.codex.pestcontrol.core;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import java.util.EnumSet;
import java.util.Set;
import org.junit.Test;

public class VoidCheckTest
{
	private static final Set<Reward> RANGER_SET = EnumSet.of(Reward.RANGER_HELM, Reward.TOP, Reward.ROBE, Reward.GLOVES);
	private static final Set<Reward> NONE = EnumSet.noneOf(Reward.class);

	@Test
	public void theFullSetWithTheRightHelmIsOn()
	{
		VoidCheck c = VoidCheck.of(RANGER_SET, Style.RANGED, RANGER_SET);
		assertEquals(VoidCheck.Kind.SET_ON, c.getKind());
		assertFalse(c.isWarning());
		assertEquals("Ranged set bonus for this game", c.getDetail());
	}

	@Test
	public void eliteTopAndRobeFillTheirSlots()
	{
		Set<Reward> elite = EnumSet.of(Reward.MAGE_HELM, Reward.ELITE_TOP, Reward.ELITE_ROBE, Reward.GLOVES);
		VoidCheck c = VoidCheck.of(elite, Style.MAGIC, elite);
		assertEquals(VoidCheck.Kind.SET_ON, c.getKind());
		assertEquals("Elite void on", c.getHeadline());
	}

	@Test
	public void aHelmForAnotherStyleGivesNothing()
	{
		Set<Reward> mage = EnumSet.of(Reward.MAGE_HELM, Reward.TOP, Reward.ROBE, Reward.GLOVES);
		Set<Reward> owned = EnumSet.copyOf(mage);
		owned.add(Reward.RANGER_HELM);
		VoidCheck c = VoidCheck.of(mage, Style.RANGED, owned);
		assertEquals(VoidCheck.Kind.WRONG_HELM, c.getKind());
		assertTrue(c.isWarning());
		assertEquals("Mage helm on a ranged weapon", c.getHeadline());
		assertEquals("Swap to your ranger helm for the set bonus", c.getDetail());
		assertEquals("Only the ranger helm helps a ranged weapon: 200 points", VoidCheck.of(mage, Style.RANGED, mage).getDetail());
	}

	@Test
	public void threePiecesOfFourGiveNoBonusAtAll()
	{
		Set<Reward> worn = EnumSet.of(Reward.MELEE_HELM, Reward.TOP, Reward.ROBE);
		VoidCheck c = VoidCheck.of(worn, Style.MELEE, worn);
		assertEquals(VoidCheck.Kind.INCOMPLETE, c.getKind());
		assertEquals("No gloves on, so no set bonus at all", c.getDetail());
		// With the gloves in the bank, it says so.
		Set<Reward> owned = EnumSet.copyOf(worn);
		owned.add(Reward.GLOVES);
		assertEquals("No gloves on, so no set bonus at all. You own the rest", VoidCheck.of(worn, Style.MELEE, owned).getDetail());
	}

	@Test
	public void noHelmNamesTheOneTheWeaponWants()
	{
		Set<Reward> worn = EnumSet.of(Reward.TOP, Reward.ROBE);
		VoidCheck c = VoidCheck.of(worn, Style.RANGED, worn);
		assertEquals("No ranger helm or gloves on, so no set bonus at all", c.getDetail());
	}

	@Test
	public void noVoidOnIsOnlyWorthSayingWithAFullSetOwned()
	{
		assertNull(VoidCheck.of(NONE, Style.MELEE, NONE));
		assertNull("a ranger set does not help a melee weapon", VoidCheck.of(NONE, Style.MELEE, RANGER_SET));
		VoidCheck c = VoidCheck.of(NONE, Style.RANGED, RANGER_SET);
		assertEquals(VoidCheck.Kind.NOT_WORN, c.getKind());
		assertFalse("not a warning: plenty play without void", c.isWarning());
	}

	@Test
	public void aSealOrMaceAloneIsNotVoidWorn()
	{
		assertNull(VoidCheck.of(EnumSet.of(Reward.SEAL, Reward.MACE), Style.MELEE, NONE));
	}

	/** Every reward an item id counts as, the way the plugin reads the worn items. */
	private static Set<Reward> worn(int... ids)
	{
		Set<Reward> out = EnumSet.noneOf(Reward.class);
		for (int id : ids)
		{
			for (Reward r : Reward.values())
			{
				if (r.isOwnedBy(id))
				{
					out.add(r);
				}
			}
		}
		return out;
	}

	@Test
	public void ornamentedVoidFromTheShatteredRelicsKitCountsAsVoid()
	{
		// Void knight top, robe, gloves (or) and the void ranger helm (or): a full set bonus in game.
		Set<Reward> or = worn(26463, 26465, 26467, 26475);
		VoidCheck c = VoidCheck.of(or, Style.RANGED, or);
		assertEquals(VoidCheck.Kind.SET_ON, c.getKind());
		// Elite top and robe (or), mage helm (or), the trouver-locked gloves (or).
		Set<Reward> elite = worn(26469, 26471, 27002, 26473);
		assertEquals("Elite void on", VoidCheck.of(elite, Style.MAGIC, elite).getHeadline());
		// The melee helm (or) locked with Perdu's trouver parchment.
		assertTrue(Reward.MELEE_HELM.isOwnedBy(27007));
	}
}

package com.codex.pestcontrol.overlay;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import com.codex.pestcontrol.core.Reward;
import java.awt.Rectangle;
import java.lang.reflect.Proxy;
import java.util.Map;
import net.runelite.api.widgets.Widget;
import org.junit.Test;

public class RewardShopGuideTest
{
	/** A widget that answers only what the guide asks. */
	private static Widget widget(String text, int item, Rectangle bounds, boolean hidden, Widget... kids)
	{
		return (Widget) Proxy.newProxyInstance(Widget.class.getClassLoader(), new Class<?>[]{Widget.class}, (proxy, m, args) ->
		{
			switch (m.getName())
			{
				case "getText":
					return text;
				case "getItemId":
					return item;
				case "getBounds":
					return bounds;
				case "isHidden":
					return hidden;
				case "getDynamicChildren":
					return kids;
				case "getStaticChildren":
				case "getNestedChildren":
					return new Widget[0];
				default:
					return null;
			}
		});
	}

	@Test
	public void aLinesWordsAndPictureAreLitTogether()
	{
		Widget options = widget("", -1, new Rectangle(0, 0, 400, 300), false,
			widget(null, 8839, new Rectangle(10, 10, 36, 32), false),
			widget("Void knight top", -1, new Rectangle(50, 12, 100, 14), false),
			widget("(250 pts)", -1, new Rectangle(50, 28, 60, 14), false),
			widget("Elite void top", -1, new Rectangle(250, 12, 100, 14), false),
			widget("Attack", -1, new Rectangle(10, 200, 60, 14), false));
		Map<Reward, Rectangle> lines = RewardShopGuide.lines(options);
		assertEquals(2, lines.size());
		assertEquals(new Rectangle(10, 10, 140, 32), lines.get(Reward.TOP));
		assertEquals(new Rectangle(250, 12, 100, 14), lines.get(Reward.ELITE_TOP));
	}

	@Test
	public void hiddenLinesAndEmptyBoundsAreLeftAlone()
	{
		Widget options = widget("", -1, new Rectangle(0, 0, 400, 300), false,
			widget("Void knight robe", -1, new Rectangle(50, 12, 100, 14), true),
			widget("Void knight gloves", -1, new Rectangle(0, 0, 0, 0), false));
		assertTrue(RewardShopGuide.lines(options).isEmpty());
		assertFalse(RewardShopGuide.lines(widget("", -1, null, true)).containsKey(Reward.TOP));
	}
}

